import math


def most_correlated_columns(data):
    """
    Return a tuple (name1, name2) of the two distinct columns whose Pearson
    correlation has the largest absolute value. The column that appears first
    in the dict is placed first in the tuple.

    Raises:
        ValueError: if there is no data, fewer than two columns, columns of
                    unequal length, or columns with no values.
        TypeError:  if any column contains non-numeric values.

    A column with zero variance has an undefined correlation; it is treated
    as having correlation 0 with every other column.
    """
    if not data:
        raise ValueError("no data provided")
    if len(data) < 2:
        raise ValueError("at least two columns are required")

    names = list(data.keys())
    columns = {}
    length = None

    for name in names:
        values = list(data[name])
        for v in values:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError(
                    f"column {name!r} contains non-numeric value {v!r}"
                )
        if length is None:
            length = len(values)
        elif len(values) != length:
            raise ValueError("all columns must have the same length")
        columns[name] = [float(v) for v in values]

    if length == 0:
        raise ValueError("no data provided")

    means = {name: sum(vals) / length for name, vals in columns.items()}
    # Centered values and sums of squares, precomputed per column.
    centered = {name: [x - means[name] for x in vals] for name, vals in columns.items()}
    ss = {name: sum(c * c for c in centered[name]) for name in names}

    def pearson(a, b):
        if ss[a] == 0 or ss[b] == 0:
            return 0.0
        cov = sum(x * y for x, y in zip(centered[a], centered[b]))
        return cov / math.sqrt(ss[a] * ss[b])

    best_pair = None
    best_abs = -1.0
    for i in range(len(names)):
        for j in range(i + 1, len(names)):
            r = abs(pearson(names[i], names[j]))
            if r > best_abs:
                best_abs = r
                best_pair = (names[i], names[j])

    return best_pair
