import math


def most_correlated_columns(data):
    """
    Return a tuple (name1, name2) of the two distinct columns whose Pearson
    correlation has the largest absolute value. The column that appears first
    in the dict is placed first in the tuple.

    Raises:
        ValueError: if there is no data, fewer than two columns, the columns
                    have different lengths, or the columns are empty.
        TypeError:  if any column contains a non-numeric value.

    If a column is constant (zero variance), its correlation with any other
    column is undefined; such pairs are treated as having correlation 0.
    Ties are resolved in favor of the pair that appears first.
    """
    if not data:
        raise ValueError("no data provided")
    if len(data) < 2:
        raise ValueError("at least two columns are required")

    names = list(data.keys())
    columns = {}
    for name in names:
        values = list(data[name])
        for v in values:
            # bool is a subclass of int, but it is not meaningful as a number here
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError(
                    f"column {name!r} contains non-numeric value {v!r}"
                )
        columns[name] = values

    lengths = {len(values) for values in columns.values()}
    if len(lengths) != 1:
        raise ValueError("all columns must have the same length")
    n = lengths.pop()
    if n == 0:
        raise ValueError("no data provided")

    # Precompute centered values and sums of squares for each column.
    centered = {}
    sq_norm = {}
    for name, values in columns.items():
        mean = sum(values) / n
        dev = [x - mean for x in values]
        centered[name] = dev
        sq_norm[name] = sum(d * d for d in dev)

    def pearson(a, b):
        if sq_norm[a] == 0 or sq_norm[b] == 0:
            return 0.0
        cov = sum(x * y for x, y in zip(centered[a], centered[b]))
        return cov / math.sqrt(sq_norm[a] * sq_norm[b])

    best_abs = None
    best_pair = None
    for i in range(len(names)):
        for j in range(i + 1, len(names)):
            a, b = names[i], names[j]
            r = abs(pearson(a, b))
            if best_abs is None or r > best_abs:
                best_abs = r
                best_pair = (a, b)

    return best_pair


if __name__ == "__main__":
    print(most_correlated_columns({'a': [1, 2, 3, 4], 'b': [2, 1, 4, 3], 'c': [8, 6, 4, 1]}))
    # ('a', 'c')
