def fit_linear_regression(features, values):
    """
    Fit an ordinary least-squares linear regression with an intercept.

    Solves the normal equations (X^T X) beta = X^T y, where X is the design
    matrix with a leading column of ones for the intercept.

    Returns a dict with:
        'coefficients': list of floats, one per feature column
        'intercept': float
    """
    if len(features) == 0:
        raise ValueError("features must not be empty")
    if len(features) != len(values):
        raise ValueError("features and values must have the same length")

    n_features = len(features[0])
    for row in features:
        if len(row) != n_features:
            raise ValueError("all feature rows must have the same length")

    # Design matrix: prepend a column of ones for the intercept.
    X = [[1.0] + [float(x) for x in row] for row in features]
    y = [float(v) for v in values]
    p = n_features + 1  # number of parameters including intercept

    # Build normal equations: A = X^T X (p x p), b = X^T y (p)
    A = [[0.0] * p for _ in range(p)]
    b = [0.0] * p
    for row, yi in zip(X, y):
        for i in range(p):
            b[i] += row[i] * yi
            for j in range(p):
                A[i][j] += row[i] * row[j]

    # Solve A beta = b with Gaussian elimination and partial pivoting.
    aug = [A[i][:] + [b[i]] for i in range(p)]
    for col in range(p):
        pivot = max(range(col, p), key=lambda r: abs(aug[r][col]))
        if abs(aug[pivot][col]) < 1e-12:
            raise ValueError("design matrix is singular; features are collinear")
        aug[col], aug[pivot] = aug[pivot], aug[col]
        pivot_val = aug[col][col]
        for j in range(col, p + 1):
            aug[col][j] /= pivot_val
        for r in range(p):
            if r != col and aug[r][col] != 0.0:
                factor = aug[r][col]
                for j in range(col, p + 1):
                    aug[r][j] -= factor * aug[col][j]

    beta = [aug[i][p] for i in range(p)]

    return {
        'coefficients': beta[1:],
        'intercept': float(beta[0]),
    }


if __name__ == "__main__":
    result = fit_linear_regression([[1, 2], [2, 1], [3, 4], [4, 3]], [9, 8, 19, 18])
    print(result)  # {'coefficients': [2.0, 3.0], 'intercept': 1.0}
```

The function builds the design matrix with a leading column of ones so the intercept is solved alongside the feature coefficients. It forms the normal equations and solves them with Gaussian elimination using partial pivoting, which needs no external libraries. If the features are collinear, the normal-equation matrix is singular and the function raises a `ValueError`.

