import csv
import io
import math


def _convert(cell):
    """Return None for empty cells, a number for numeric-looking cells,
    and the original string otherwise."""
    if cell is None:
        return None
    stripped = cell.strip()
    if stripped == "":
        return None
    try:
        return int(stripped)
    except ValueError:
        pass
    try:
        number = float(stripped)
    except ValueError:
        return cell
    # Reject 'nan', 'inf', etc., which float() accepts but are not numeric data.
    if math.isfinite(number):
        return number
    return cell


def merge_csv_texts(csv_texts):
    """Stack the data rows of several CSV documents into one table.

    Returns a list of dicts, one per data row, in input order. Every column
    seen in any input appears in every dict (in first-appearance order);
    missing or empty cells are None, and numeric-looking values become numbers.
    """
    parsed = []  # list of (header, data_rows) per input document
    columns = []
    seen = set()

    for text in csv_texts:
        rows = [row for row in csv.reader(io.StringIO(text)) if row]
        if not rows:
            continue
        header, data_rows = rows[0], rows[1:]
        parsed.append((header, data_rows))
        for col in header:
            if col not in seen:
                seen.add(col)
                columns.append(col)

    result = []
    for header, data_rows in parsed:
        for data in data_rows:
            record = {col: None for col in columns}
            for i, col in enumerate(header):
                if i < len(data):
                    record[col] = _convert(data[i])
            result.append(record)

    return result
```

Running your example, `merge_csv_texts(['Name,Age\nAlice,25', 'Name,Age,City\nBob,30,Paris'])` gives `[{'Name': 'Alice', 'Age': 25, 'City': None}, {'Name': 'Bob', 'Age': 30, 'City': 'Paris'}]`. An empty input list returns `[]`.

Some choices I made beyond the spec:
- Cells are stripped of surrounding whitespace before the numeric check, so `" 25 "` becomes `25`. Whitespace-only cells count as empty and become `None`.
- Values like `nan` or `inf` stay as strings, since they are not useful as numeric data.
- Rows shorter than their header fill the missing trailing columns with `None`.
- Blank lines in the CSV text are skipped.

