import csv
import io
import re

_NUMBER_RE = re.compile(r'[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$')


def _convert(value):
    """Return None for missing/empty cells, a number for numeric-looking
    text, and the original string otherwise."""
    if value is None:
        return None
    stripped = value.strip()
    if stripped == '':
        return None
    if _NUMBER_RE.match(stripped):
        try:
            return int(stripped)
        except ValueError:
            return float(stripped)
    return value


def merge_csv_texts(csv_texts):
    columns = []          # union of all columns, in order of first appearance
    seen = set()
    raw_rows = []         # (row dict from its own file) in input order

    for text in csv_texts:
        reader = csv.DictReader(io.StringIO(text))
        if reader.fieldnames:
            for name in reader.fieldnames:
                if name not in seen:
                    seen.add(name)
                    columns.append(name)
        for row in reader:
            raw_rows.append(row)

    result = []
    for raw in raw_rows:
        # raw.get returns None for columns this row's file doesn't have
        result.append({col: _convert(raw.get(col)) for col in columns})
    return result
