import csv
import io
import re

_NUMBER_RE = re.compile(r'[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?')
_INT_RE = re.compile(r'[+-]?\d+')


def _convert(value):
    """Return None for empty cells, a number for numeric-looking text, else the string."""
    if value is None or value.strip() == '':
        return None
    s = value.strip()
    if _NUMBER_RE.fullmatch(s):
        if _INT_RE.fullmatch(s):
            return int(s)
        return float(s)
    return value


def merge_csv_texts(csv_texts):
    parsed = []        # list of (list of raw row dicts) per document
    columns = {}       # ordered union of column names (dict used as ordered set)

    # First pass: parse every document and collect all column names in order of appearance.
    for text in csv_texts:
        reader = csv.DictReader(io.StringIO(text))
        for name in (reader.fieldnames or []):
            if name is not None:
                columns.setdefault(name, None)
        rows = []
        for raw in reader:
            rows.append({k: v for k, v in raw.items() if k is not None})
        parsed.append(rows)

    # Second pass: build the stacked table in input order.
    result = []
    for rows in parsed:
        for raw in rows:
            record = {}
            for col in columns:
                record[col] = _convert(raw[col]) if col in raw else None
            result.append(record)
    return result
