import csv
import io
import re

_NUMBER_RE = re.compile(r'[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?')


def _convert(value):
    """Return None for empty cells, a number for numeric-looking text, else the string."""
    if value is None or value == '':
        return None
    if _NUMBER_RE.fullmatch(value):
        try:
            return int(value)
        except ValueError:
            return float(value)
    return value


def merge_csv_texts(csv_texts):
    # Ordered union of all column names, in order of first appearance.
    columns = {}
    records = []

    for text in csv_texts:
        reader = csv.DictReader(io.StringIO(text))
        if reader.fieldnames:
            for name in reader.fieldnames:
                columns.setdefault(name, None)
        for record in reader:
            records.append(record)

    # DictReader yields None for columns missing from a row's file,
    # so rec.get(col) covers both absent columns and empty cells.
    return [
        {col: _convert(rec.get(col)) for col in columns}
        for rec in records
    ]
