import math

def letter_count_correlations(strings):
    """
    Return a nested dict where result[x][y] is the Pearson correlation between
    the per-string counts of letter x and letter y. Returns None for an empty list.
    """
    if not strings:
        return None

    # Letters that occur anywhere in the input, in sorted order.
    letters = sorted({ch for s in strings for ch in s})

    # counts[letter] is a list with one count per string.
    counts = {
        letter: [s.count(letter) for s in strings]
        for letter in letters
    }

    n = len(strings)
    means = {letter: sum(counts[letter]) / n for letter in letters}

    # Centered vectors and their sums of squares.
    dev = {
        letter: [c - means[letter] for c in counts[letter]]
        for letter in letters
    }
    ss = {
        letter: sum(d * d for d in dev[letter])
        for letter in letters
    }

    result = {}
    for x in letters:
        result[x] = {}
        for y in letters:
            if x == y:
                result[x][y] = 1.0
                continue
            cov = sum(dx * dy for dx, dy in zip(dev[x], dev[y]))
            denom = math.sqrt(ss[x] * ss[y])
            result[x][y] = cov / denom

    return result
```

**Notes:**
- Each letter's counts across the strings are centered by their mean, then the Pearson correlation is the covariance divided by the product of the standard deviations (the square roots of the sums of squares, since the common factor of `n` cancels).
- The diagonal is set to exactly `1.0`, which avoids floating-point noise such as `0.9999999999999998`.
- The problem guarantees each letter's count varies, so `ss[x]` is never zero and no division by zero occurs.

For the example `['ab', 'ba', 'cc']`, this returns the dict given in the problem statement.

```python
import math

def letter_count_correlations(strings):
    if not strings:
        return None

    n = len(strings)
    letters = sorted(set("".join(strings)))

    # Per-string count vectors for each letter
    counts = {x: [s.count(x) for s in strings] for x in letters}

    # Centered vectors and their norms
    means = {x: sum(v) / n for x, v in counts.items()}
    dev = {x: [c - means[x] for c in counts[x]] for x in letters}
    norm = {x: math.sqrt(sum(d * d for d in dev[x])) for x in letters}

    result = {}
    for x in letters:
        result[x] = {}
        for y in letters:
            dot = sum(a * b for a, b in zip(dev[x], dev[y]))
            r = dot / (norm[x] * norm[y])
            # Clean up floating-point noise and keep within [-1, 1]
            r = round(max(-1.0, min(1.0, r)), 12)
            result[x][y] = r
    return result
```

