import csv
import io
import math


def _parse_numeric(values):
    """Return the values as floats if every value is a finite number, else None."""
    if not values:
        return None
    nums = []
    for v in values:
        try:
            x = float(v)
        except ValueError:
            return None
        if not math.isfinite(x):
            return None
        nums.append(x)
    return nums


def normalize_numeric_columns(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row]  # skip blank lines

    if not rows:
        raise ValueError("CSV text is empty; it must contain a header row")

    header = rows[0]
    data = rows[1:]

    for line_no, row in enumerate(data, start=2):
        if len(row) != len(header):
            raise ValueError(
                f"Row {line_no} has {len(row)} fields; expected {len(header)}"
            )

    result = {}
    found_numeric = False

    for i, name in enumerate(header):
        values = [row[i] for row in data]
        nums = _parse_numeric(values)

        if nums is None:
            # Non-numeric column: leave values unchanged as strings
            result[name] = values
            continue

        found_numeric = True
        lo, hi = min(nums), max(nums)
        if hi == lo:
            scaled = [0.0] * len(nums)
        else:
            span = hi - lo
            scaled = [(x - lo) / span for x in nums]
        result[name] = scaled

    if not found_numeric:
        raise ValueError("CSV data has no numeric columns")

    return result


if __name__ == "__main__":
    print(normalize_numeric_columns(
        'name,age,salary\nAlice,30,50000\nBob,32,60000\nCharlie,34,90000'
    ))
    # {'name': ['Alice', 'Bob', 'Charlie'], 'age': [0.0, 0.5, 1.0], 'salary': [0.0, 0.25, 1.0]}
```

Design choices:

- **Numeric detection:** a column counts as numeric only if it has at least one value and every value parses as a finite float. Empty cells, text, `nan`, and `inf` make a column non-numeric, so it is returned unchanged.
- **Constant columns:** if min equals max, every value becomes `0.0`.
- **Malformed input:** rows whose field count differs from the header raise `ValueError`, as does empty input.
- **No numeric columns:** raises `ValueError`, including the case where the CSV has a header but no data rows.
- **Duplicate header names:** not handled specially, so a later column with the same name overwrites an earlier one in the dict.

```python
import csv
import io
import math


def normalize_numeric_columns(csv_text):
    """
    Parse CSV text with a header row and min-max scale each numeric column to [0, 1].

    A column is numeric if it has at least one data row and every value parses as
    a finite number (nan and inf are treated as non-numeric). Numeric columns are
    scaled to floats in [0, 1]; a constant column becomes all 0.0. Other columns
    are returned unchanged as lists of strings.

    Returns a dict mapping column names (in header order) to value lists.
    Raises ValueError if there is no header or no numeric columns.
    """
    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text has no header row")

    rows = [row for row in reader if row]  # skip blank lines

    # Build column-wise lists, padding short rows with empty strings.
    columns = [[] for _ in header]
    for row in rows:
        for i in range(len(header)):
            columns[i].append(row[i] if i < len(row) else "")

    def parse_number(text):
        try:
            value = float(text)
        except ValueError:
            return None
        return value if math.isfinite(value) else None

    result = {}
    found_numeric = False

    for name, values in zip(header, columns):
        numbers = [parse_number(v) for v in values]
        if values and all(n is not None for n in numbers):
            found_numeric = True
            lo = min(numbers)
            hi = max(numbers)
            if hi == lo:
                result[name] = [0.0] * len(numbers)
            else:
                span = hi - lo
                result[name] = [(n - lo) / span for n in numbers]
        else:
            result[name] = values

    if not found_numeric:
        raise ValueError("CSV data contains no numeric columns")

    return result


