from html.parser import HTMLParser

# Elements that never have content or an end tag.
VOID_ELEMENTS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr",
}


class _FirstTagTextParser(HTMLParser):
    def __init__(self, tag):
        super().__init__(convert_charrefs=True)  # decode entities like &amp;
        self.tag = tag.lower()
        self.found = False   # have we seen the first matching start tag?
        self.done = False    # have we seen its matching end tag?
        self.depth = 0       # nesting depth of same-named tags inside the target
        self.parts = []

    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        if self.found:
            if tag == self.tag:
                self.depth += 1
        elif tag == self.tag:
            self.found = True
            if self.tag in VOID_ELEMENTS:
                self.done = True  # no content, no end tag
            else:
                self.depth = 1

    def handle_endtag(self, tag):
        if self.done or not self.found:
            return
        if tag == self.tag:
            self.depth -= 1
            if self.depth == 0:
                self.done = True

    def handle_data(self, data):
        if self.found and not self.done:
            self.parts.append(data)


def first_tag_text(html, tag):
    """Return the text content of the first element named `tag`, or None.

    Nested elements' text is included, tags are stripped, and entities
    are decoded. Returns None if no such element exists or its text is empty.
    """
    parser = _FirstTagTextParser(tag)
    parser.feed(html)
    parser.close()

    if not parser.found:
        return None
    text = "".join(parser.parts)
    return text if text else None


if __name__ == "__main__":
    print(first_tag_text('<html><body><p>First</p><p>Second</p></body></html>', 'p'))  # First
    print(first_tag_text('<div><p>a<b>b</b>&amp;c</p></div>', 'p'))                    # ab&c
    print(first_tag_text('<div><div>x</div>y</div>', 'div'))                           # xy
    print(first_tag_text('<p></p>', 'p'))                                              # None
    print(first_tag_text('<p>hi</p>', 'span'))                                         # None
```

The parser tracks nesting depth for the target tag so that the text collected runs until the matching end tag, including nested same-named elements. Text is collected only inside the first match, and the function returns `None` when there's no match or the collected text is an empty string. Whitespace-only text is returned as-is, since the spec only asked for an empty check; if you want whitespace-only results to return `None`, change the final check to `text.strip()`.

