        super().__init__(convert_charrefs=True)  # decodes entities in data
        self.tag = tag.lower()
        self.depth = 0        # nesting depth inside the target element
        self.done = False     # True once the target element has closed
        self.parts = []

    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        if self.depth == 0:
            if tag == self.tag:
                if self.tag in VOID_ELEMENTS:
                    # Void element: no content, so we're finished immediately.
                    self.done = True
                else:
                    self.depth = 1
        elif tag == self.tag and self.tag not in VOID_ELEMENTS:
            # Nested element with the same name.
            self.depth += 1

    def handle_endtag(self, tag):
        if self.done or self.depth == 0:
            return
        if tag == self.tag:
            self.depth -= 1
            if self.depth == 0:
                self.done = True

    def handle_data(self, data):
        if self.depth > 0 and not self.done:
            self.parts.append(data)


def first_tag_text(html, tag):
    """
    Return the text content of the first element named `tag` in `html`,
    including text from nested elements, with tags removed and entities
    decoded. Return None if no such element exists or its text is empty.
    """
    parser = _FirstTagTextParser(tag)
    parser.feed(html)
    parser.close()

    if not parser.parts and not parser.done:
        return None
    text = "".join(parser.parts)
    return text if text else None


