from html.parser import HTMLParser

# HTML void elements never have content or a closing tag.
VOID_ELEMENTS = {
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr',
}


class _FirstTagTextParser(HTMLParser):
    def __init__(self, tag):
        super().__init__(convert_charrefs=True)  # decodes entities in text
        self.tag = tag.lower()
        self.found = False   # have we entered the first matching element?
        self.done = False    # have we finished that element?
        self.depth = 0       # nesting depth of same-name elements
        self.parts = []

    def handle_starttag(self, name, attrs):
        if self.done:
            return
        if not self.found:
            if name == self.tag:
                self.found = True
                if name in VOID_ELEMENTS:
                    self.done = True
                else:
                    self.depth = 1
        elif name == self.tag and name not in VOID_ELEMENTS:
            # Nested element with the same name
            self.depth += 1

    def handle_startendtag(self, name, attrs):
        # Self-closing form such as <br/> or <p/>: an empty element.
        if self.done:
            return
        if not self.found and name == self.tag:
            self.found = True
            self.done = True

    def handle_endtag(self, name):
        if self.done or not self.found:
            return
        if name == self.tag:
            self.depth -= 1
            if self.depth == 0:
                self.done = True

    def handle_data(self, data):
        if self.found and not self.done:
            self.parts.append(data)


def first_tag_text(html, tag):
    """
    Return the text content of the first element with the given tag name,
    including nested text, with tags removed and entities decoded.
    Return None if no such element exists or its text is empty.
    """
    parser = _FirstTagTextParser(tag)
    parser.feed(html)
    parser.close()
    text = ''.join(parser.parts)
    return text if text else None


if __name__ == '__main__':
    print(first_tag_text('<html><body><p>First</p><p>Second</p></body></html>', 'p'))  # First
    print(first_tag_text('<div><p>Hello <b>big</b> &amp; <i>bold</i></p></div>', 'p'))  # Hello big & bold
    print(first_tag_text('<div><div>a</div>b</div>', 'div'))  # ab
    print(first_tag_text('<p></p>', 'p'))  # None
    print(first_tag_text('<span>x</span>', 'p'))  # None
```

**How it works**

- A `HTMLParser` subclass walks the document and ignores everything until it sees the first start tag matching `tag` (case-insensitively, since the parser lowercases names).
- It tracks nesting depth so that nested elements with the same name don't end the capture early. Capture stops when the matching end tag brings the depth back to zero.
- Only text data is collected, so nested tags are stripped while their text is kept. `convert_charrefs=True` makes the parser decode entities such as `&amp;` automatically.
- Void elements (like `<br>`) and self-closing forms (`<p/>`) have no content, so they produce `None`.
- If the collected text is an empty string, the function returns `None`.

