import csv
import io
import re
from datetime import datetime

_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def _parse_date(value):
    """Return a date object for a strict 'YYYY-MM-DD' string, or None if invalid."""
    if not _DATE_RE.match(value):
        return None
    try:
        return datetime.strptime(value, "%Y-%m-%d").date()
    except ValueError:
        return None


def filter_rows_by_date_range(csv_text, column_name, start_date, end_date):
    start = _parse_date(start_date)
    if start is None:
        raise ValueError(f"start_date is not a valid 'YYYY-MM-DD' date: {start_date!r}")
    end = _parse_date(end_date)
    if end is None:
        raise ValueError(f"end_date is not a valid 'YYYY-MM-DD' date: {end_date!r}")

    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError(f"Column {column_name!r} not found: CSV has no header row")

    if column_name not in header:
        raise ValueError(f"Column {column_name!r} not found in header {header!r}")
    idx = header.index(column_name)

    result = []
    for row in reader:
        if len(row) <= idx:
            continue  # skip blank or short rows
        row_date = _parse_date(row[idx])
        if row_date is not None and start <= row_date <= end:
            result.append(row)
    return result


