Notes on the behavior:
- Bounds and cell values must match the strict `YYYY-MM-DD` format (e.g., `2020-1-5` is rejected), and must be real calendar dates.
- A `ValueError` is raised if the column is missing from the header or if either bound is invalid.
- The spec doesn't say what to do with data cells that aren't valid dates, so this implementation treats them as non-matching and skips them rather than raising. Blank or short rows are skipped as well.
- Matching rows are returned in their original order as lists of strings, without the header.

```python
import csv
import io
import re
from datetime import datetime

_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def _parse_date(text):
    """Parse a strict 'YYYY-MM-DD' string; return a date or None if invalid."""
    if not _DATE_RE.match(text):
        return None
    try:
        return datetime.strptime(text, "%Y-%m-%d").date()
    except ValueError:
        return None


def filter_rows_by_date_range(csv_text, column_name, start_date, end_date):
    start = _parse_date(start_date)
    if start is None:
        raise ValueError(f"start_date is not a valid 'YYYY-MM-DD' date: {start_date!r}")
    end = _parse_date(end_date)
    if end is None:
        raise ValueError(f"end_date is not a valid 'YYYY-MM-DD' date: {end_date!r}")

    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text is empty; no header row found")

    if column_name not in header:
        raise ValueError(f"Column {column_name!r} not found in header")
    col_idx = header.index(column_name)

    result = []
    for row in reader:
        if not row:  # skip blank lines
            continue
        if col_idx >= len(row):
            continue  # row lacks this column; cannot be in range
        row_date = _parse_date(row[col_idx].strip())
        if row_date is None:
            continue  # unparseable date cannot fall within the range
        if start <= row_date <= end:
            result.append(row)
    return result


if __name__ == "__main__":
    sample = "Date,Value\n2020-01-01,0.5\n2020-02-15,1.2\n2020-03-10,3.4\n"
    print(filter_rows_by_date_range(sample, 'Date', '2020-01-15', '2020-03-01'))
    # [['2020-02-15', '1.2']]
```

The function validates the column and both bounds up front, then keeps rows whose date falls within the inclusive range, preserving order and omitting the header. Rows with a missing or malformed date in the target column are skipped, since they can't fall within the range. The spec didn't say how to handle those, so that's a judgment call you may want to change to raising instead.

