import re

def name_frequency_stats(text):
    # Pieces of text outside the square-bracketed addresses
    pieces = re.split(r'\[[^\]]*\]', text)
    names = [p.strip() for p in pieces if p.strip()]

    counts = {}
    for name in names:
        counts[name] = counts.get(name, 0) + 1

    values = list(counts.values())
    n = len(values)
    if n == 0:
        return (counts, None, None)

    mean = sum(values) / n
    m2 = sum((x - mean) ** 2 for x in values) / n
    if m2 == 0:
        # All counts equal (or no spread): skewness and kurtosis undefined
        return (counts, None, None)

    m3 = sum((x - mean) ** 3 for x in values) / n
    m4 = sum((x - mean) ** 4 for x in values) / n

    skewness = m3 / (m2 ** 1.5)          # population (biased) skewness
    kurtosis = m4 / (m2 ** 2) - 3.0      # excess (Fisher) kurtosis

    return (counts, skewness, kurtosis)
```

For the example `name_frequency_stats('Alice [1 A ST]Bob [2 B ST]Alice [3 C ST]Carol [4 D ST]')`, the counts are `{'Alice': 2, 'Bob': 1, 'Carol': 1}`, and the values `[2, 1, 1]` give skewness 1/√2 ≈ 0.7071 and excess kurtosis -1.5. The last digit of the floating-point skewness may differ slightly from the value shown in your example, depending on the order of floating-point operations.

