import csv
import io


def normalize_csv_columns(csv_text):
    """
    Min-max normalize each numeric column of a CSV text so values run from 0 to 1.

    The first row is treated as the header. Returns a dict mapping each column
    name to a list of normalized floats in row order. A column whose values are
    all identical is mapped to all zeros.

    >>> normalize_csv_columns('a,b\\n1,10\\n3,20\\n5,10')
    {'a': [0.0, 0.5, 1.0], 'b': [0.0, 1.0, 0.0]}
    """
    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if any(cell.strip() for cell in row)]

    if not rows:
        return {}

    header = [name.strip() for name in rows[0]]
    data_rows = rows[1:]

    # Collect values per column as floats.
    columns = {name: [] for name in header}
    for row in data_rows:
        for name, cell in zip(header, row):
            columns[name].append(float(cell.strip()))

    result = {}
    for name, values in columns.items():
        if not values:
            result[name] = []
            continue
        lo = min(values)
        hi = max(values)
        span = hi - lo
        if span == 0:
            result[name] = [0.0] * len(values)
        else:
            result[name] = [(v - lo) / span for v in values]

    return result
