    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row]  # skip blank lines

    if not rows:
        return {}

    header = rows[0]
    data_rows = rows[1:]

    # Parse each column into floats, column by column.
    columns = [[float(row[i]) for row in data_rows] for i in range(len(header))]

    result = {}
    for name, values in zip(header, columns):
        if not values:
            result[name] = []
            continue

        lo, hi = min(values), max(values)
        if hi == lo:
            result[name] = [0.0] * len(values)
        else:
            span = hi - lo
            result[name] = [(v - lo) / span for v in values]

    return result


if __name__ == "__main__":
    print(normalize_csv_columns('a,b\n1,10\n3,20\n5,10'))
    # {'a': [0.0, 0.5, 1.0], 'b': [0.0, 1.0, 0.0]}
