from html.parser import HTMLParser


class _DataTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.in_table = False       # currently inside the target table
        self.finished = False       # target table has been closed
        self.table_depth = 0        # nesting depth of <table> inside target
        self.rows = []              # list of rows, each a list of cell texts
        self.in_cell = False        # currently inside a <td> of the target table
        self.cell_buf = []          # text pieces of the current cell

    def _close_cell(self):
        if self.in_cell:
            self.rows[-1].append("".join(self.cell_buf))
            self.in_cell = False
            self.cell_buf = []

    def handle_starttag(self, tag, attrs):
        if self.finished:
            return
        if not self.in_table:
            if tag == "table":
                class_value = dict(attrs).get("class")
                if class_value == "data-table":
                    self.in_table = True
                    self.table_depth = 1
            return

        # Inside the target table
        if tag == "table":
            self.table_depth += 1
            return
        if self.table_depth != 1:
            return  # content of nested tables only contributes text
        if tag == "tr":
            self._close_cell()
            self.rows.append([])
        elif tag == "td":
            self._close_cell()
            if not self.rows:
                self.rows.append([])  # malformed: td without tr
            self.in_cell = True
            self.cell_buf = []

    def handle_endtag(self, tag):
        if self.finished or not self.in_table:
            return
        if tag == "table":
            self.table_depth -= 1
            if self.table_depth == 0:
                self._close_cell()
                self.in_table = False
                self.finished = True
            return
        if self.table_depth == 1:
            if tag == "td":
                self._close_cell()
            elif tag == "tr":
                self._close_cell()

    def handle_data(self, data):
        if self.in_table and not self.finished and self.in_cell:
            self.cell_buf.append(data)


def extract_data_table_rows(html):
    parser = _DataTableParser()
    parser.feed(html)
    parser.close()
    if not parser.rows and parser.in_table:
        # Unclosed table: still return what was collected
        parser._close_cell()
    return parser.rows
```

**How it works**

- It uses Python's built-in `html.parser` (no third-party dependencies). `convert_charrefs=True` decodes entities like `&amp;` and `&#39;` automatically.
- The parser looks for the first `<table>` whose `class` attribute equals `"data-table"` exactly, so `"data-table big"` does not match.
- It tracks table nesting so that rows and cells from nested tables are not mistaken for rows of the target table. Text from a nested table inside a cell is still included in that cell's text, with tags removed.
- Each `<td>` collects its raw text data (whitespace preserved), and the text is appended to the current row when the cell closes. Cells are also closed implicitly when a new `<tr>` or `<td>` starts, so slightly malformed HTML without `</td>` still works.
- If no matching table exists, or it has no rows, the function returns `[]`.

