        self.rows = []
        self.in_table = False      # currently inside the target table
        self.table_done = False    # target table has been fully read
        self.depth = 0             # nesting depth of <table> tags inside the target
        self.row = None            # list of cells for the open <tr>, or None
        self.cell = None           # list of text pieces for the open <td>, or None

    def _close_cell(self):
        if self.cell is not None and self.row is not None:
            self.row.append("".join(self.cell))
        self.cell = None

    def _close_row(self):
        self._close_cell()
        if self.row is not None:
            self.rows.append(self.row)
        self.row = None

    def handle_starttag(self, tag, attrs):
        if self.table_done:
            return
        if not self.in_table:
            if tag == "table" and dict(attrs).get("class") == "data-table":
                self.in_table = True
                self.depth = 1
            return

        if tag == "table":
            self.depth += 1
        elif self.depth == 1:
            if tag == "tr":
                self._close_row()
                self.row = []
            elif tag == "td" and self.row is not None and self.cell is None:
                self.cell = []
        # Tags nested inside a cell are ignored; their text is still captured.

    def handle_endtag(self, tag):
        if self.table_done or not self.in_table:
            return

        if tag == "table":
            self.depth -= 1
            if self.depth == 0:
                self._close_row()
                self.in_table = False
                self.table_done = True
        elif self.depth == 1:
            if tag == "td":
                self._close_cell()
            elif tag == "tr":
                self._close_row()

    def handle_data(self, data):
        if self.in_table and self.cell is not None:
            self.cell.append(data)


def extract_data_table_rows(html):
    parser = _DataTableExtractor()
    parser.feed(html)
    parser.close()
    # Flush anything left open if the markup was unterminated.
    if parser.in_table:
        parser._close_row()
    return parser.rows
