from html.parser import HTMLParser


class _DataTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)  # decode entities in text
        self.rows = []
        self.state = "seek"   # "seek" -> looking for the table, "inside", "done"
        self.depth = 0        # table nesting depth relative to the target table
        self.row = None       # list of cell texts for the current row
        self.cell = None      # list of text fragments for the current cell

    def handle_starttag(self, tag, attrs):
        if self.state == "seek":
            if tag == "table" and dict(attrs).get("class") == "data-table":
                self.state = "inside"
                self.depth = 1
            return
        if self.state != "inside":
            return

        if tag == "table":
            self.depth += 1
        elif self.depth == 1:
            if tag == "tr":
                self._end_row()
                self.row = []
            elif tag == "td":
                self._end_cell()
                if self.row is None:      # td without an explicit tr
                    self.row = []
                self.cell = []

    def handle_endtag(self, tag):
        if self.state != "inside":
            return

        if tag == "table":
            if self.depth == 1:
                self._end_row()
                self.state = "done"
                self.depth = 0
            else:
                self.depth -= 1
        elif self.depth == 1:
            if tag == "td":
                self._end_cell()
            elif tag == "tr":
                self._end_row()

    def handle_data(self, data):
        if self.state == "inside" and self.cell is not None:
            self.cell.append(data)

    def _end_cell(self):
        if self.cell is not None:
            self.row.append("".join(self.cell))
            self.cell = None

    def _end_row(self):
        self._end_cell()
        if self.row is not None:
            self.rows.append(self.row)
            self.row = None


def extract_data_table_rows(html):
    """
    Return the rows of the first <table> whose class attribute is exactly
    "data-table". Each row is a list of the text contents of its <td> cells,
    in document order. Returns [] if no such table exists or it has no rows.
    """
    parser = _DataTableParser()
    parser.feed(html)
    parser.close()
    # Finalize any row left open by an unclosed table or missing end tags.
    parser._end_row()
    return parser.rows
```

