def min_max_scale_columns(data, columns):
    """
    Return a new dict where each column named in `columns` is min-max scaled
    to the range [0, 1]. All other columns are copied unchanged.

    A constant column (max == min) scales to all zeros.
    """
    columns_to_scale = set(columns)
    result = {}

    for name, values in data.items():
        if name not in columns_to_scale:
            result[name] = list(values)
            continue

        values = list(values)
        if not values:
            result[name] = []
            continue

        lo = min(values)
        hi = max(values)
        span = hi - lo

        if span == 0:
            result[name] = [0.0] * len(values)
        else:
            result[name] = [(v - lo) / span for v in values]

    return result


