import string


def keyword_article_word_counts(articles):
    """
    Count word occurrences in the content of articles whose titles contain
    'like' or 'what' (case-insensitive).

    Words keep their original case, and punctuation is stripped from the
    edges of each word. Internal punctuation such as the apostrophe in
    "don't" is kept.

    Raises ValueError if any article lacks a 'Title' or 'Content' key.
    """
    # Validate every article first, so bad input is always reported.
    for article in articles:
        if not isinstance(article, dict) or 'Title' not in article or 'Content' not in article:
            raise ValueError("Each article must contain 'Title' and 'Content' keys.")

    keywords = ('like', 'what')
    counts = {}

    for article in articles:
        title_lower = article['Title'].lower()
        if not any(keyword in title_lower for keyword in keywords):
            continue

        for token in article['Content'].split():
            word = token.strip(string.punctuation)
            if word:
                counts[word] = counts.get(word, 0) + 1

    return counts


if __name__ == "__main__":
    result = keyword_article_word_counts([
        {'Title': 'What is happening', 'Content': 'Like what you see?'},
        {'Title': 'Nothing special', 'Content': 'Just normal text.'},
    ])
    print(result)  # {'Like': 1, 'what': 1, 'you': 1, 'see': 1}
```

The function first checks every article for the required keys and raises `ValueError` if one is missing. It then keeps only articles whose lowercased title contains "like" or "what", splits each selected article's content on whitespace, strips leading and trailing punctuation from each token, and tallies the results. Because the keys keep their original case, "Like" and "like" are counted separately.

