from html.parser import HTMLParser

_VOID_ELEMENTS = {
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr',
}


class _Node:
    def __init__(self, tag, attrs):
        self.tag = tag
        self.attrs = attrs
        self.children = []  # elements (_Node) or text strings


class _TreeBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)  # decodes entities in text
        self.root = _Node(None, {})
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        node = _Node(tag, {k: (v or '') for k, v in attrs})
        self.stack[-1].children.append(node)
        if tag not in _VOID_ELEMENTS:
            self.stack.append(node)

    def handle_startendtag(self, tag, attrs):
        node = _Node(tag, {k: (v or '') for k, v in attrs})
        self.stack[-1].children.append(node)

    def handle_endtag(self, tag):
        # Find the nearest open element with this tag and close it
        # along with anything opened inside it.
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                return
        # Stray end tag: ignore.

    def handle_data(self, data):
        self.stack[-1].children.append(data)


def _iter_elements(node):
    """Yield all descendant elements in document (pre-)order."""
    for child in node.children:
        if isinstance(child, _Node):
            yield child
            yield from _iter_elements(child)


def _text_of(node):
    parts = []
    for child in node.children:
        if isinstance(child, _Node):
            parts.append(_text_of(child))
        else:
            parts.append(child)
    return ''.join(parts)


def _classes(node):
    return node.attrs.get('class', '').split()


def _first(node, pred):
    for el in _iter_elements(node):
        if pred(el):
            return el
    return None


def extract_article_info(html):
    builder = _TreeBuilder()
    builder.feed(html)
    builder.close()

    results = []
    for el in _iter_elements(builder.root):
