```python
from html.parser import HTMLParser

_VOID_TAGS = {'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
              'link', 'meta', 'param', 'source', 'track', 'wbr'}


class _ArticleParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.records = []   # container records, in document order of their start tags
        self.stack = []     # open elements: dicts with 'tag', 'rec', 'cap'
        self.active = []    # captures still collecting text

    def handle_starttag(self, tag, attrs):
        # Use the first occurrence of each attribute, as browsers do.
        attr = {}
        for name, value in attrs:
            if name not in attr:
                attr[name] = value or ''
        classes = attr.get('class', '').split()

        entry = {'tag': tag, 'rec': None, 'cap': None}

        if tag == 'div' and 'container' in classes:
            rec = {'title': None, 'date': None, 'author': None, 'pending': set()}
            entry['rec'] = rec
            self.records.append(rec)

        field = None
        if tag == 'h1':
            field = 'title'
        elif tag == 'span' and 'date' in classes:
            field = 'date'
        elif tag == 'span' and 'author' in classes:
            field = 'author'

        if field is not None:
            # Every enclosing container that still lacks this field and
            # is not already capturing it gets this element as its candidate.
            owners = [e['rec'] for e in self.stack
                      if e['rec'] is not None
                      and e['rec'][field] is None
                      and field not in e['rec']['pending']]
            if owners:
                cap = {'field': field, 'owners': owners, 'parts': []}
                for o in owners:
                    o['pending'].add(field)
                self.active.append(cap)
                entry['cap'] = cap

        if tag not in _VOID_TAGS:
            self.stack.append(entry)

    def handle_endtag(self, tag):
        # Find the matching open element; if none, ignore the stray end tag.
        idx = None
        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i]['tag'] == tag:
                idx = i
                break
        if idx is None:
            return
        while len(self.stack) > idx:
            entry = self.stack.pop()
            if entry['cap'] is not None:
                self._finalize(entry['cap'])

    def handle_data(self, data):
        for cap in self.active:
            cap['parts'].append(data)

    def _finalize(self, cap):
        if cap in self.active:
            self.active.remove(cap)
        text = ''.join(cap['parts']).strip()
        field = cap['field']
        for rec in cap['owners']:
            rec['pending'].discard(field)
            if rec[field] is None:
                rec[field] = text

    def close(self):
        super().close()
        while self.stack:
            entry = self.stack.pop()
            if entry['cap'] is not None:
                self._finalize(entry['cap'])
        for cap in list(self.active):
            self._finalize(cap)


def extract_article_info(html):
    parser = _ArticleParser()
    parser.feed(html)
    parser.close()
    result = []
    for rec in parser.records:
        title = rec['title'] if rec['title'] is not None else 'No Title'
        date = rec['date'] if rec['date'] is not None else 'No Date'
        author = rec['author'] if rec['author'] is not None else 'No Author'
        result.append((title, date, author))
    return result
```

Example:

```python
>>> extract_article_info('<div class="container"><h1>Hello</h1><span class="author">Ann</span></div>')
[('Hello', 'No Date', 'Ann')]
```

The parser uses the standard library's `html.parser`, so entities are decoded and nested tags are stripped. For a container nested inside another, the outer container also picks up any title, date, or author it has not yet found, which matches "the first matching element inside the div."

