import json
import statistics


def key_mean_median(json_text):
    """
    Compute the mean and median of the numeric values for every key
    appearing in a JSON list of records.

    Missing, null, boolean, and non-numeric values are ignored. A key with
    no numeric values maps to {'mean': None, 'median': None}.
    """
    records = json.loads(json_text)

    # Collect numeric values per key, preserving first-seen key order.
    values_by_key = {}
    for record in records:
        if not isinstance(record, dict):
            continue
        for key, value in record.items():
            nums = values_by_key.setdefault(key, [])
            # bool is a subclass of int in Python, so exclude it explicitly.
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                nums.append(value)

    result = {}
    for key, nums in values_by_key.items():
        if nums:
            result[key] = {
                'mean': float(statistics.mean(nums)),
                'median': float(statistics.median(nums)),
            }
        else:
            result[key] = {'mean': None, 'median': None}
    return result


if __name__ == "__main__":
