        vals = [r[c] for r in t1.values() if r.get(c) is not None]
        if not vals:
            stats[c] = None  # nothing to standardize; stays None
        elif min(vals) == max(vals):
            stats[c] = ('constant', None)
        else:
            n = len(vals)
            mean = sum(vals) / n
            var = sum((v - mean) ** 2 for v in vals) / n
            stats[c] = ('normal', (mean, math.sqrt(var)))

    merged = []
    for id_ in sorted(set(t1) | set(t2)):
        r1 = t1.get(id_, {})
        r2 = t2.get(id_, {})
        out = {'id': id_}

        for c in cols1:
