```python
import math


def merge_and_standardize(rows1, rows2):
    """
    Outer-join two tables on 'id' and standardize the first table's feature columns.

    - Every output row contains 'id', every feature column of table 1, and every
      feature column of table 2. Missing values are None.
    - Table 1 feature columns are standardized to mean 0 and population standard
      deviation 1, computed over non-missing values only. A constant column maps
      to 0.0 (missing values stay None).
    - Table 2 columns are copied unchanged.
    - Output is sorted by 'id'.
    """

    def feature_columns(rows):
        cols = []
        for r in rows:
            for k in r:
                if k != 'id' and k not in cols:
                    cols.append(k)
        return cols

    def index_by_id(rows):
        table = {}
        for r in rows:
            # If an id is repeated within a table, its fields are merged
            # (later values win for the same column).
            table.setdefault(r['id'], {}).update(r)
        return table

    cols1 = feature_columns(rows1)
    cols2 = feature_columns(rows2)

    # Mean and population std of each table-1 column, ignoring missing values.
    stats = {}
    for c in cols1:
        vals = [float(r[c]) for r in rows1 if r.get(c) is not None]
        if not vals:
            stats[c] = (0.0, 0.0)
            continue
        mu = sum(vals) / len(vals)
        var = sum((v - mu) ** 2 for v in vals) / len(vals)
        stats[c] = (mu, math.sqrt(var))

    t1 = index_by_id(rows1)
    t2 = index_by_id(rows2)

    result = []
    for i in sorted(set(t1) | set(t2)):
        a = t1.get(i, {})
        b = t2.get(i, {})
        row = {'id': i}

        for c in cols1:
            v = a.get(c)
            if v is None:
                row[c] = None
            else:
                mu, sd = stats[c]
                row[c] = 0.0 if sd == 0 else (float(v) - mu) / sd

        for c in cols2:
            row[c] = b.get(c)

        result.append(row)

    return result
```

