```python
import math


def merge_and_standardize(rows1, rows2):
    """
    Outer-join two tables on 'id' and return the merged rows sorted by id.

    - Feature columns of rows1 are standardized to mean 0 and population
      standard deviation 1, using only non-missing values. A constant column
      becomes 0 (missing values stay None).
    - Feature columns of rows2 are left unchanged.
    - Missing values in the result are None.
    """

    # Collect feature column names, preserving first-seen order.
    cols1 = []
    for r in rows1:
        for k in r:
            if k != 'id' and k not in cols1:
                cols1.append(k)

    cols2 = []
    for r in rows2:
        for k in r:
            if k != 'id' and k not in cols2:
                cols2.append(k)

    # Index rows by id (if an id repeats, the last occurrence wins).
    t1 = {r['id']: r for r in rows1}
    t2 = {r['id']: r for r in rows2}

    # Compute mean and population std for each column of table 1,
    # ignoring missing (None) values.
    stats = {}
    for c in cols1:
        vals = [r[c] for r in rows1 if r.get(c) is not None]
        if not vals:
            stats[c] = (0.0, 0.0, True)
            continue
        mu = sum(vals) / len(vals)
        var = sum((v - mu) ** 2 for v in vals) / len(vals)
        sd = math.sqrt(var)
        # Detect constant columns by value equality rather than sd == 0,
        # to avoid floating-point noise producing spurious +/-1 values.
        is_constant = len(set(vals)) == 1
        stats[c] = (mu, sd, is_constant)

    # Outer join: union of ids, sorted.
    all_ids = sorted(set(t1) | set(t2))

    result = []
    for i in all_ids:
        r1 = t1.get(i, {})
        r2 = t2.get(i, {})
        row = {'id': i}

        for c in cols1:
            v = r1.get(c)
            if v is None:
                row[c] = None
            else:
                mu, sd, is_constant = stats[c]
                if is_constant or sd == 0:
                    row[c] = 0.0
                else:
                    row[c] = (v - mu) / sd

        for c in cols2:
            row[c] = r2.get(c)

        result.append(row)

    return result
