def scale_table_columns(data):
    if not data:
        return {}

    names = list(data.keys())
    columns = [list(data[name]) for name in names]
    n_rows = len(columns[0])

    # Keep only rows where no column has None.
    kept_rows = [
        row for row in zip(*columns)
        if all(value is not None for value in row)
    ]

    result = {}
    for idx, name in enumerate(names):
        values = [row[idx] for row in kept_rows]
        if not values:
            result[name] = []
            continue

        lo = min(values)
        hi = max(values)
        if lo == hi:
            result[name] = [0.0 for _ in values]
        else:
            span = hi - lo
            result[name] = [(v - lo) / span for v in values]

    return result
