from collections import Counter

def association_chi_square(left, right):
    """
    Inner-join two lists of [id, category] pairs on id, cross-tabulate the
    left category against the right category, and return the Pearson
    chi-square statistic of independence (no continuity correction) together
    with its degrees of freedom.

    Returns (statistic, dof) where statistic is a float and dof is an int.
    """
    # Group categories by id on each side
    left_by_id = {}
    for id_, cat in left:
        left_by_id.setdefault(id_, []).append(cat)

    right_by_id = {}
    for id_, cat in right:
        right_by_id.setdefault(id_, []).append(cat)

    # Inner join: every (left category, right category) pair for shared ids
    pairs = []
    for id_ in left_by_id:
        if id_ in right_by_id:
            for lc in left_by_id[id_]:
                for rc in right_by_id[id_]:
                    pairs.append((lc, rc))

    n = len(pairs)
    if n == 0:
        return (0.0, 0)

    # Build the contingency table
    observed = Counter(pairs)
    row_totals = Counter(lc for lc, _ in pairs)
    col_totals = Counter(rc for _, rc in pairs)

    rows = sorted(row_totals)
    cols = sorted(col_totals)
    r, c = len(rows), len(cols)

    dof = (r - 1) * (c - 1)
    if dof <= 0:
        # A single row or column means no variation, so the statistic is 0
        return (0.0, 0)

    stat = 0.0
    for lc in rows:
        for rc in cols:
            expected = row_totals[lc] * col_totals[rc] / n
            o = observed.get((lc, rc), 0)
            stat += (o - expected) ** 2 / expected

    return (float(stat), int(dof))


if __name__ == "__main__":
    print(association_chi_square([[1, 'A'], [2, 'B'], [3, 'A']],
                                 [[1, 'X'], [2, 'Y'], [3, 'X']]))  # (3.0, 1)
```

The function joins the lists as an inner join, so duplicate ids on either side produce every matching pair. It builds the observed table, computes expected counts as row total × column total / N, and sums (O − E)² / E over all cells. If the joined data has fewer than two distinct categories on either side, it returns `(0.0, 0)`, since there is no variation to test. For your example it returns `(3.0, 1)`.

