from datetime import datetime
from zoneinfo import ZoneInfo


def publication_hour_stats(articles, timezone):
    """
    Group articles by category and compute statistics on the local hour of
    publication in the given IANA timezone.

    Returns a dict mapping each category to a dict with 'count', 'mean',
    'min', and 'max' of the publication hours (0-23).

    Raises ValueError if the list is empty, if an article is missing
    'category' or 'published_time', or if a timestamp has no UTC offset.
    """
    if not articles:
        raise ValueError("articles list must not be empty")

    tz = ZoneInfo(timezone)  # raises ZoneInfoNotFoundError for unknown names
    hours_by_category = {}

    for index, article in enumerate(articles):
        if 'category' not in article or 'published_time' not in article:
            raise ValueError(
                f"article at index {index} is missing 'category' or 'published_time'"
            )

        ts = article['published_time']
        # Support the 'Z' UTC designator on Python versions before 3.11.
        if isinstance(ts, str) and ts.endswith('Z'):
            ts = ts[:-1] + '+00:00'
        dt = datetime.fromisoformat(ts)

        if dt.tzinfo is None:
            raise ValueError(
                f"article at index {index} has a timestamp without a UTC offset"
            )

        local_hour = dt.astimezone(tz).hour
        hours_by_category.setdefault(article['category'], []).append(local_hour)

    result = {}
    for category in sorted(hours_by_category):
        hours = hours_by_category[category]
        result[category] = {
            'count': len(hours),
            'mean': sum(hours) / len(hours),
            'min': min(hours),
            'max': max(hours),
        }
    return result


