import math

def column_correlations(data):
    """
    Return the pairwise Pearson correlation matrix of the columns in `data`.

    `data` maps column names to equal-length lists of numbers.
    The result is a nested dict where result[x][y] is the Pearson
    correlation between columns x and y, including x with itself.

    If a column has zero variance, its correlation with anything
    (including itself) is undefined and is returned as float('nan').
    """
    names = list(data.keys())

    # Precompute means and centered sums of squares for each column.
    means = {}
    centered = {}
    ss = {}
    for name in names:
        values = [float(v) for v in data[name]]
        n = len(values)
        mean = sum(values) / n if n else 0.0
        dev = [v - mean for v in values]
        means[name] = mean
        centered[name] = dev
        ss[name] = sum(d * d for d in dev)

    def corr(x, y):
        if x == y:
            # A column is perfectly correlated with itself when it varies.
            return 1.0 if ss[x] > 0 else float('nan')
        sxy = sum(a * b for a, b in zip(centered[x], centered[y]))
        denom = math.sqrt(ss[x] * ss[y])
        if denom == 0:
            return float('nan')
        r = sxy / denom
        # Guard against tiny floating-point overshoot.
        return max(-1.0, min(1.0, r))

    result = {x: {} for x in names}
    for i, x in enumerate(names):
        for y in names[i:]:
            r = corr(x, y)
            result[x][y] = r
            result[y][x] = r
    return result


if __name__ == "__main__":
    print(column_correlations({'a': [1, 2, 3], 'b': [4, 5, 6], 'c': [3, 1, 2]}))
    # {'a': {'a': 1.0, 'b': 1.0, 'c': -0.5}, 'b': {'a': 1.0, 'b': 1.0, 'c': -0.5},
    #  'c': {'a': -0.5, 'b': -0.5, 'c': 1.0}}
```

The function computes each column's centered values and sum of squares once, then fills in each pair's correlation for the upper triangle and mirrors it, so `result[x][y]` and `result[y][x]` are always identical. For your example it returns the matrix shown in the prompt.

```python
import math

def column_correlations(data):
    """
    Return the pairwise Pearson correlation matrix of the columns in `data`.

    `data` maps column names to equal-length lists of numbers. The result
    is a nested dict where result[x][y] is the correlation between columns
    x and y. A column with zero variance (or an empty column) has undefined
    correlation, which is reported as NaN.
    """
    names = list(data)
    means = {}
    devs = {}
    ss = {}  # sum of squared deviations per column

    for k in names:
        vals = data[k]
        n = len(vals)
        if n == 0:
            means[k] = float('nan')
            devs[k] = []
            ss[k] = 0.0
            continue
        m = sum(vals) / n
        means[k] = m
        devs[k] = [v - m for v in vals]
        ss[k] = sum(d * d for d in devs[k])

    result = {x: {} for x in names}

    for i, x in enumerate(names):
        for y in names[i:]:
            if x == y:
                r = 1.0 if ss[x] > 0 else float('nan')
            else:
                denom = math.sqrt(ss[x] * ss[y])
                if denom == 0:
                    r = float('nan')
                else:
                    cov = sum(a * b for a, b in zip(devs[x], devs[y]))
                    r = cov / denom
            result[x][y] = r
            result[y][x] = r  # correlation is symmetric

    return result


if __name__ == "__main__":
    print(column_correlations({'a': [1, 2, 3], 'b': [4, 5, 6], 'c': [3, 1, 2]}))
    # {'a': {'a': 1.0, 'b': 1.0, 'c': -0.5}, 'b': {'a': 1.0, 'b': 1.0, 'c': -0.5}, 'c': {'a': -0.5, 'b': -0.5, 'c': 1.0}}
```

The function computes each column's mean and centered values once, then fills the matrix using only the upper triangle and mirrors each result, so the output is symmetric by construction. Each off-diagonal entry is the covariance sum divided by the product of the two standard-deviation norms, and the diagonal is set to exactly `1.0`.

