    numeric_columns = set()
    for name in fieldnames:
        parsed = [_parse_number(row.get(name)) for row in rows]
        if all(value is not None for value in parsed):
            numeric_columns.add(name)
            for row, value in zip(rows, parsed):
                row[name] = value

