```python
import csv
import io
import math


def sort_csv_rows(csv_text, sort_by_column='title'):
    """
    Parse CSV text with a header row and return its data rows sorted in
    ascending order by `sort_by_column`.

    Each row is returned as a dict mapping column names to values. A column
    whose values are all numeric is converted to numbers (int if every value
    is an integer, otherwise float) and sorts numerically. Other columns stay
    as strings.
    """
    reader = csv.DictReader(io.StringIO(csv_text))
    fieldnames = reader.fieldnames or []
    rows = list(reader)

    if sort_by_column not in fieldnames:
        raise KeyError(f"Column {sort_by_column!r} not found in CSV header")

    def parse_number(value):
        """Return an int or float for a numeric string, or None otherwise."""
        if value is None:
            return None
        try:
            return int(value)
        except ValueError:
            pass
        try:
            number = float(value)
        except ValueError:
            return None
        return number if math.isfinite(number) else None

    # Decide, per column, whether it is numeric and how to convert it.
    converters = {}
    for col in fieldnames:
        values = [row[col] for row in rows]
        if not values:
            continue
        parsed = [parse_number(v) for v in values]
        if all(p is not None for p in parsed):
            if all(isinstance(p, int) for p in parsed):
                converters[col] = int
            else:
                converters[col] = float

    result = []
    for row in rows:
        new_row = {}
        for col in fieldnames:
            value = row[col]
            if col in converters and value is not None:
                new_row[col] = converters[col](value) if converters[col] is float \
                    else parse_number(value)
            else:
                new_row[col] = value
        result.append(new_row)

    result.sort(key=lambda r: r[sort_by_column])
    return result
```

