def normalized_cumulative_sums(data):
    """
    For each column in `data`, compute the running cumulative sum and
    min-max scale it to [0, 1]. A constant cumulative sum maps to all zeros.

    Raises:
        TypeError: if `data` is not a dict/list-valued mapping, or any
                   value is non-numeric (booleans are rejected).
        ValueError: if `data` is empty, a column is empty, columns have
                    unequal lengths, or any value is NaN (or infinite,
                    since infinities make min-max scaling undefined).
    """
    if not isinstance(data, dict):
        raise TypeError("data must be a dict mapping column names to lists")
    if len(data) == 0:
        raise ValueError("data is empty")

    # Type checks first
    for name, values in data.items():
        if not isinstance(values, (list, tuple)):
            raise TypeError(f"column {name!r} must be a list of numbers")
        for v in values:
            if isinstance(v, bool) or not isinstance(v, numbers.Real):
                raise TypeError(
                    f"column {name!r} contains non-numeric value {v!r}"
                )

    # Value checks: NaN / infinity, emptiness, equal lengths
    lengths = set()
    for name, values in data.items():
        if len(values) == 0:
            raise ValueError(f"column {name!r} is empty")
        lengths.add(len(values))
        for v in values:
            if math.isnan(v):
                raise ValueError(f"column {name!r} contains NaN")
            if math.isinf(v):
                raise ValueError(f"column {name!r} contains infinite value")
    if len(lengths) > 1:
        raise ValueError("all columns must have equal length")

    result = {}
    for name, values in data.items():
        cums = [float(c) for c in accumulate(values)]
        lo, hi = min(cums), max(cums)
        if hi == lo:
            result[name] = [0.0] * len(cums)
        else:
            span = hi - lo
            result[name] = [(c - lo) / span for c in cums]
    return result


