def standardize_by_group(records):
    """
    Standardize 'age' and 'income' to z-scores within each group of records
    sharing the same 'id'. Uses the group's mean and population standard
    deviation. A value that is constant within its group becomes 0.0.

    Returns a list of dicts (same order as input) with keys 'id', 'age', 'income'.
    Raises ValueError if any record lacks one of the required keys.
    """
    required = ('id', 'age', 'income')

    # Validate all records before doing any work.
    for rec in records:
        if not all(key in rec for key in required):
            raise ValueError(f"Record {rec!r} is missing one of the keys {required}")

    # Group record indices by id, preserving order.
    groups = {}
    for idx, rec in enumerate(records):
        groups.setdefault(rec['id'], []).append(idx)

    result = [None] * len(records)

    for gid, idxs in groups.items():
        # Compute (mean, std, is_constant) for each field within this group.
        params = {}
        for field in ('age', 'income'):
            vals = [float(records[i][field]) for i in idxs]
            n = len(vals)
            mean = sum(vals) / n
            if all(v == vals[0] for v in vals):
                params[field] = (mean, None)  # constant -> standardized to 0
            else:
                var = sum((v - mean) ** 2 for v in vals) / n  # population variance
                params[field] = (mean, var ** 0.5)

        for i in idxs:
            out = {'id': records[i]['id']}
            for field in ('age', 'income'):
                mean, std = params[field]
                if std is None:
                    out[field] = 0.0
                else:
                    out[field] = (float(records[i][field]) - mean) / std
            result[i] = out

    return result
