import math


def standardize_by_group(records):
    """
    Standardize 'age' and 'income' to z-scores within each group of records
    sharing the same 'id', using the group's mean and population standard
    deviation. A value that is constant within its group becomes 0.0.

    Returns a list of dicts (in input order) with keys 'id', 'age', 'income'.
    Raises ValueError if any record lacks one of the required keys.
    """
    required = ('id', 'age', 'income')
    fields = ('age', 'income')

    for rec in records:
        if not isinstance(rec, dict) or any(key not in rec for key in required):
            raise ValueError(f"record is missing one of the required keys {required}: {rec!r}")

    # Group records by id.
    groups = {}
    for rec in records:
        groups.setdefault(rec['id'], []).append(rec)

    # Compute (mean, population std, is_constant) per group and field.
    stats = {}
    for gid, rows in groups.items():
        stats[gid] = {}
        for field in fields:
            vals = [float(r[field]) for r in rows]
            n = len(vals)
            mean = math.fsum(vals) / n
            if all(v == vals[0] for v in vals):
                std = 0.0  # constant within group -> z-score is 0
            else:
                std = math.sqrt(math.fsum((v - mean) ** 2 for v in vals) / n)
            stats[gid][field] = (mean, std)

    # Build the output in input order.
    result = []
    for rec in records:
        out = {'id': rec['id']}
        for field in fields:
            mean, std = stats[rec['id']][field]
            if std == 0.0:
                out[field] = 0.0
            else:
                out[field] = (float(rec[field]) - mean) / std
        result.append(out)

    return result
