    Raises ValueError if any record is missing one of 'id', 'age', 'income'.
    """
    required = ('id', 'age', 'income')
    for rec in records:
        missing = [k for k in required if k not in rec]
        if missing:
            raise ValueError(f"record {rec!r} is missing key(s): {', '.join(missing)}")

    # Group records by id.
    groups = {}
    for rec in records:
        groups.setdefault(rec['id'], []).append(rec)

    # Compute per-group statistics for each field.
    stats = {}
    for gid, rows in groups.items():
        stats[gid] = {}
        for field in ('age', 'income'):
            vals = [float(r[field]) for r in rows]
            n = len(vals)
            mean = sum(vals) / n
            constant = all(v == vals[0] for v in vals)
            if constant:
                std = 0.0
            else:
                std = sqrt(sum((v - mean) ** 2 for v in vals) / n)
            stats[gid][field] = (mean, std, constant)

    # Build output in input order.
    result = []
    for rec in records:
        gid = rec['id']
        out = {'id': gid}
        for field in ('age', 'income'):
            mean, std, constant = stats[gid][field]
            value = float(rec[field])
            if constant:
                out[field] = 0.0
            else:
                out[field] = (value - mean) / std
        result.append(out)
    return result


if __name__ == '__main__':
    example = [
        {'id': 1, 'age': 25, 'income': 50000},
        {'id': 1, 'age': 26, 'income': 60000},
        {'id': 2, 'age': 35, 'income': 70000},
        {'id': 2, 'age': 36, 'income': 80000},
    ]
    print(standardize_by_group(example))
    # [{'id': 1, 'age': -1.0, 'income': -1.0}, {'id': 1, 'age': 1.0, 'income': 1.0},
    #  {'id': 2, 'age': -1.0, 'income': -1.0}, {'id': 2, 'age': 1.0, 'income': 1.0}]
