from numbers import Real


def _is_number(value):
    # bool is a subclass of int, but True/False are not treated as numeric data here.
    return isinstance(value, Real) and not isinstance(value, bool)


def cumulative_column_sums(data):
    """
    Return the running (cumulative) sum down each numeric column of a table.

    `data` maps column names to equal-length lists of values. Columns whose
    values are not all numbers are ignored. The result maps each numeric
    column name to its list of cumulative sums, preserving column order.

    Raises ValueError if the table has no rows or no numeric columns.
    """
    if not data:
        raise ValueError("table has no columns")

    lengths = {len(values) for values in data.values()}
    if len(lengths) != 1:
        raise ValueError("all columns must have the same length")
    if lengths.pop() == 0:
        raise ValueError("table has no rows")

    result = {}
    for name, values in data.items():
        if all(_is_number(v) for v in values):
            running = 0
            sums = []
            for v in values:
                running += v
                sums.append(running)
            result[name] = sums

    if not result:
        raise ValueError("table has no numeric columns")

    return result


if __name__ == "__main__":
    print(cumulative_column_sums({'A': [1, 2, 3], 'B': ['x', 'y', 'z'], 'C': [0.5, -1.5, 2.0]}))
    # {'A': [1, 3, 6], 'C': [0.5, -1.0, 1.0]}
```

The function works as follows:

- **Empty input:** if the table has no columns, or its columns have no rows, it raises `ValueError`. It also raises if the columns have unequal lengths, since that violates the table format.
- **Numeric detection:** a column counts as numeric if every value is a real number (`int` or `float`). `bool` is excluded even though it subclasses `int`, so `True` and `False` don't get treated as numbers.
- **Cumulative sums:** each numeric column is summed with a running total, so integer columns stay integers and float columns stay floats.
- **Order and filtering:** the result is a dict that keeps the original column order and omits non-numeric columns. If no column is numeric, it raises `ValueError`.

