```python
import xml.etree.ElementTree as ET


def _clean_text(s):
    """Strip surrounding whitespace; return None if nothing remains."""
    if s is None:
        return None
    s = s.strip()
    return s if s else None


def _element_value(elem):
    # Leaf element: no attributes and no children -> its text (or None).
    if not elem.attrib and len(elem) == 0:
        return _clean_text(elem.text)

    result = {}

    # Attributes, prefixed with '@'.
    for name, value in elem.attrib.items():
        result['@' + name] = value

    # Child elements, grouped by tag in document order.
    groups = {}
    for child in elem:
        groups.setdefault(child.tag, []).append(_element_value(child))
    for tag, values in groups.items():
        result[tag] = values[0] if len(values) == 1 else values

    # Direct text content (text before children and text after each child).
    pieces = [elem.text] + [child.tail for child in elem]
    text = _clean_text(''.join(p for p in pieces if p))
    if text is not None:
        result['#text'] = text

    return result


def xml_to_dict(xml):
    """Parse an XML string into nested dicts: {root_tag: value}.

    Raises ValueError if the XML is malformed.
    """
    try:
        root = ET.fromstring(xml)
    except ET.ParseError as exc:
        raise ValueError(f"Malformed XML: {exc}") from exc
    return {root.tag: _element_value(root)}
```

**Example:**

```python
>>> xml_to_dict('<family><person name="John"><age>30</age></person><person name="Jane"/></family>')
{'family': {'person': [{'@name': 'John', 'age': '30'}, {'@name': 'Jane'}]}}
```

**Design notes:**

- **Leaf text:** Whitespace is trimmed, and text that is empty after trimming is treated as no text, so the value is `None`. If you would rather keep an empty string for whitespace-only text, change `_clean_text` to return `s` instead of `None` when it is empty.
- **Mixed content:** The `'#text'` value joins the element's own text with the tails of its children, then trims the result. For example, `<a>hi <b/> there</a>` gives `'#text': 'hi  there'` after joining, with the internal spacing preserved.
- **Repeated tags:** A tag that appears once maps to its value directly. A tag that appears more than once maps to a list of values in document order. Because values are never lists themselves, this is unambiguous.
- **Malformed input:** `ET.ParseError` is a `SyntaxError` subclass, not a `ValueError`, so it is caught and re-raised as `ValueError`.
- **Namespaces:** Tags are used as they appear to the parser, so namespaced tags show up in ElementTree's `{uri}tag` form.

```python
import xml.etree.ElementTree as ET


def xml_to_dict(xml):
    """
    Parse an XML string into nested Python dicts.

    Returns {root_tag: value}, where:
      * An element with no attributes and no child elements becomes its text
        (whitespace-trimmed), or None if it has no text.
      * Any other element becomes a dict with:
          - attributes as keys prefixed with '@'
          - child elements keyed by tag (a list of values if the tag repeats
            among siblings, in document order)
          - text content under '#text' (omitted if there is none)

    Raises ValueError if the XML is malformed.
    """
    try:
        root = ET.fromstring(xml)
    except ET.ParseError as exc:
        raise ValueError(f"Malformed XML: {exc}") from exc

    def text_of(elem):
        # Direct text of the element plus the tail text of each child
        # (text that sits between/after child elements).
        pieces = [elem.text or ""] + [child.tail or "" for child in elem]
        stripped = [p.strip() for p in pieces if p.strip()]
        return " ".join(stripped)

    def value(elem):
        children = list(elem)
        text = text_of(elem)

        if not elem.attrib and not children:
            return text or None

        result = {}
        for name, val in elem.attrib.items():
            result["@" + name] = val

        groups = {}
        for child in children:
            groups.setdefault(child.tag, []).append(value(child))
        for tag, vals in groups.items():
            result[tag] = vals[0] if len(vals) == 1 else vals

        if text:
            result["#text"] = text

        return result

    return {root.tag: value(root)}
```

**Examples**

```python
>>> xml_to_dict('<family><person name="John"><age>30</age></person><person name="Jane"/></family>')
{'family': {'person': [{'@name': 'John', 'age': '30'}, {'@name': 'Jane'}]}}

>>> xml_to_dict('<a>hello</a>')
{'a': 'hello'}

>>> xml_to_dict('<a></a>')
{'a': None}

>>> xml_to_dict('<a x="1">text<b>2</b></a>')
{'a': {'@x': '1', 'b': '2', '#text': 'text'}}

>>> xml_to_dict('<a><b>1</a>')
ValueError: Malformed XML: ...
```

**Notes on choices**

- Text that is only whitespace is treated as "no text," so it yields `None` for a leaf and is omitted for a dict element.
- For mixed content, the element's own text and the text after each child are collected under `'#text'`, joined by single spaces.
- Parsing uses `xml.etree.ElementTree`. Its `ParseError` is caught and re-raised as `ValueError`.

