import math

def row_averages_and_correlations(data):
    # Validate that data is a list of lists
    if not isinstance(data, list):
        raise ValueError("data must be a list of rows")
    for row in data:
        if not isinstance(row, list):
            raise ValueError("each row must be a list")

    # An empty table has no rows, hence no averages and no columns
    if len(data) == 0:
        return ([], [])

    ncols = len(data[0])
    for row in data:
        if len(row) != ncols:
            raise ValueError("data must be rectangular (all rows the same length)")
        for x in row:
            if isinstance(x, bool) or not isinstance(x, (int, float)):
                raise ValueError("all entries must be numbers")

    if ncols == 0:
        raise ValueError("rows must not be empty")

    n = len(data)

    # Mean of each row
    averages = [sum(row) / ncols for row in data]

    # Extract columns and center them
    cols = [[data[r][c] for r in range(n)] for c in range(ncols)]
    means = [sum(col) / n for col in cols]
    centered = [[x - m for x in col] for col, m in zip(cols, means)]
    sq_sums = [sum(a * a for a in col) for col in centered]

    # Pairwise Pearson correlation matrix of columns
    corr = [[math.nan] * ncols for _ in range(ncols)]
    for i in range(ncols):
        for j in range(ncols):
            if i == j:
                corr[i][j] = 1.0 if sq_sums[i] > 0 else math.nan
                continue
            cov = sum(a * b for a, b in zip(centered[i], centered[j]))
            denom = math.sqrt(sq_sums[i] * sq_sums[j])
            corr[i][j] = cov / denom if denom > 0 else math.nan

    return (averages, corr)
```

For the example `row_averages_and_correlations([[1, 5], [1, 3], [2, 5]])`, this returns `([3.0, 2.0, 3.5], [[1.0, 0.5], [0.5, 1.0]])`.

