```python
import math


def row_averages_and_correlations(data):
    """
    Given a table `data` (a list of rows, each a list of numbers), return
    (averages, corr):
      - averages: the mean of each row, in row order.
      - corr: the pairwise Pearson correlation matrix of the columns, where
        corr[i][j] is the correlation between column i and column j.

    Raises ValueError if `data` is not a rectangular list of rows of numbers.
    """
    def is_number(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    if not isinstance(data, list):
        raise ValueError("data must be a list of rows")

    if len(data) == 0:
        return [], []

    for row in data:
        if not isinstance(row, (list, tuple)):
            raise ValueError("each row must be a list")
        for x in row:
            if not is_number(x):
                raise ValueError("all entries must be numbers")

    n_cols = len(data[0])
    for row in data:
        if len(row) != n_cols:
            raise ValueError("data must be rectangular (all rows same length)")

    if n_cols == 0:
        raise ValueError("rows must contain at least one column")

    # Row averages
    averages = [math.fsum(row) / n_cols for row in data]

    # Column-wise extraction
    n_rows = len(data)
    columns = [[data[r][c] for r in range(n_rows)] for c in range(n_cols)]
    col_means = [math.fsum(col) / n_rows for col in columns]

    # Centered columns
    centered = [[x - m for x in col] for col, m in zip(columns, col_means)]

    # Sums of squares and cross-products
    ss = [[0.0] * n_cols for _ in range(n_cols)]
    for i in range(n_cols):
        for j in range(i, n_cols):
            s = math.fsum(a * b for a, b in zip(centered[i], centered[j]))
            ss[i][j] = s
            ss[j][i] = s

    corr = [[0.0] * n_cols for _ in range(n_cols)]
    for i in range(n_cols):
        for j in range(n_cols):
            if i == j:
                corr[i][j] = 1.0 if ss[i][i] > 0 else float("nan")
            else:
                denom = math.sqrt(ss[i][i]) * math.sqrt(ss[j][j])
                if denom == 0:
                    corr[i][j] = float("nan")
                else:
                    corr[i][j] = ss[i][j] / denom

    return averages, corr
```

For the example `row_averages_and_correlations([[1, 5], [1, 3], [2, 5]])`, this returns `([3.0, 2.0, 3.5], [[1.0, 0.5], [0.5, 1.0]])`.

Two choices the spec didn't cover: an empty table returns `([], [])`, and a constant column (zero variance) gives `nan` in its correlation entries rather than raising an error.

