import math

def standardized_tensor_product(P, T):
    # ---- validation of P ----
    if not P or not all(isinstance(r, (list, tuple)) and len(r) > 0 for r in P):
        raise ValueError("P must be a non-empty matrix with non-empty rows")
    m = len(P)
    k = len(P[0])
    if any(len(r) != k for r in P):
        raise ValueError("P must be a rectangular matrix")

    # ---- validation of T ----
    if not T or not T[0] or not T[0][0]:
        raise ValueError("T must be a non-empty k x n x p tensor")
    if len(T) != k:
        raise ValueError("P's number of columns must match T's first dimension")
    n = len(T[0])
    p = len(T[0][0])
    for t in range(k):
        if len(T[t]) != n:
            raise ValueError("T must be a rectangular tensor")
        for j in range(n):
            if len(T[t][j]) != p:
                raise ValueError("T must be a rectangular tensor")

    # ---- build the n x (m*p) table ----
    rows = []
    for j in range(n):
        row = []
        for i in range(m):
            for q in range(p):
                s = sum(P[i][t] * T[t][j][q] for t in range(k))
                row.append(float(s))
        rows.append(row)

    # ---- standardise each column (population std) ----
    num_cols = m * p
    result = [[0.0] * num_cols for _ in range(n)]
    for c in range(num_cols):
        vals = [rows[j][c] for j in range(n)]
        if all(v == vals[0] for v in vals):
            # zero variance -> column becomes all zeros
            continue
        mean = sum(vals) / n
        var = sum((v - mean) ** 2 for v in vals) / n
        sd = math.sqrt(var)
        for j in range(n):
            result[j][c] = (vals[j] - mean) / sd

    return result
```

