import math

def standardized_tensor_product(P, T):
    # --- Validate inputs ---
    if not P or not all(isinstance(row, (list, tuple)) for row in P):
        raise ValueError("P must be a non-empty matrix (list of lists).")
    m = len(P)
    k = len(P[0])
    if k == 0:
        raise ValueError("P must have at least one column.")
    if any(len(row) != k for row in P):
        raise ValueError("P must be a rectangular matrix.")

    if not T:
        raise ValueError("T must be non-empty.")
    k_T = len(T)
    if k_T == 0:
        raise ValueError("T must be non-empty.")
    if not T[0]:
        raise ValueError("T must have a non-empty second dimension.")
    n = len(T[0])
    if n == 0:
        raise ValueError("T must have a non-empty second dimension.")
    p = len(T[0][0]) if T[0][0] is not None else 0
    if p == 0:
        raise ValueError("T must have a non-empty third dimension.")
    for i in range(k_T):
        if len(T[i]) != n:
            raise ValueError("T must be a rectangular tensor.")
        for j in range(n):
            if len(T[i][j]) != p:
                raise ValueError("T must be a rectangular tensor.")

    if k != k_T:
        raise ValueError("P's number of columns must match T's first dimension.")

    # --- Build the table: row j = flatten(P @ T[:, j, :]) ---
    table = []
    for j in range(n):
        row = []
        for r in range(m):
            for c in range(p):
                s = 0.0
                for i in range(k):
                    s += P[r][i] * T[i][j][c]
                row.append(float(s))
        table.append(row)

    # --- Standardise each column (population std) ---
    num_cols = m * p
    result = [[0.0] * num_cols for _ in range(n)]
    for c in range(num_cols):
        vals = [table[j][c] for j in range(n)]
        if all(v == vals[0] for v in vals):
            # zero variance -> column becomes all zeros
            continue
        mean = sum(vals) / n
        var = sum((v - mean) ** 2 for v in vals) / n
        sd = math.sqrt(var)
        if sd == 0:
            continue
        for j in range(n):
            result[j][c] = float((vals[j] - mean) / sd)

    return result
```

