def scale_by_group_with_histogram(ids, ages, incomes):
    n = len(ids)
    if n == 0:
        raise ValueError("no rows to scale")
    if len(ages) != n or len(incomes) != n:
        raise ValueError("ids, ages and incomes must have equal lengths")

    # Collect row indices for each group, preserving first-seen order.
    groups = {}
    for i, g in enumerate(ids):
        groups.setdefault(g, []).append(i)

    scaled = [[0.0, 0.0] for _ in range(n)]

    for rows in groups.values():
        for col, values in ((0, ages), (1, incomes)):
            lo = min(values[i] for i in rows)
            hi = max(values[i] for i in rows)
            span = hi - lo
            for i in rows:
                # A constant column within the group scales to 0.
                scaled[i][col] = 0.0 if span == 0 else (values[i] - lo) / span

    # Histogram of scaled incomes in 10 equal-width bins over [0, 1].
    counts = [0] * 10
    for _, scaled_income in scaled:
        b = min(int(scaled_income * 10), 9)  # 1.0 falls into the last bin
        counts[b] += 1

    return scaled, counts


