def scale_by_group_with_histogram(ids, ages, incomes):
    """
    Min-max scale ages and incomes within each id group to [0, 1].

    A column that is constant within a group scales to 0.
    Returns (scaled, counts):
      scaled: list of [scaled_age, scaled_income] in original row order.
      counts: counts of scaled incomes in 10 equal-width bins over [0, 1]
              (the last bin includes 1).
    """
    n = len(ids)
    if n == 0:
        raise ValueError("no rows to process")
    if len(ages) != n or len(incomes) != n:
        raise ValueError("ids, ages and incomes must have equal length")

    # First pass: per-group min and max for each column.
    stats = {}
    for g, a, inc in zip(ids, ages, incomes):
        if g not in stats:
            stats[g] = {"a_min": a, "a_max": a, "i_min": inc, "i_max": inc}
        else:
            s = stats[g]
            if a < s["a_min"]:
                s["a_min"] = a
            if a > s["a_max"]:
                s["a_max"] = a
            if inc < s["i_min"]:
                s["i_min"] = inc
            if inc > s["i_max"]:
                s["i_max"] = inc

    def scale(x, lo, hi):
        if hi == lo:
            return 0.0
        return (x - lo) / (hi - lo)

    # Second pass: scale each row using its group's statistics.
    scaled = []
