import csv
import io


def fill_missing_with_column_mean(csv_text):
    """
    Parse CSV text (with a header row) into a dict mapping each column name
    to its list of values in row order.

    - Numeric columns (every non-empty cell parses as a float) become lists of
      floats, with empty cells replaced by the mean of that column's present values.
    - Other columns become lists of strings, with empty cells set to None.
    - A column with no non-empty values becomes all None.
    - Empty input gives an empty dict.
    """
    # Skip completely blank lines; csv.reader returns [] for them.
    rows = [row for row in csv.reader(io.StringIO(csv_text)) if row]
    if not rows:
        return {}

    header = rows[0]
    data = rows[1:]

    result = {}
    for i, name in enumerate(header):
        # Short rows are padded with empty cells.
        raw = [row[i] if i < len(row) else '' for row in data]
        present = [v for v in raw if v.strip() != '']

        numbers = None
        if present:
            try:
                numbers = [float(v) for v in present]
            except ValueError:
                numbers = None

        if numbers is not None:
            mean = sum(numbers) / len(numbers)
            result[name] = [float(v) if v.strip() != '' else mean for v in raw]
        else:
            result[name] = [v if v.strip() != '' else None for v in raw]

    return result


if __name__ == '__main__':
