import math


def encode_and_standardize(data, replacements):
    """
    Preprocess a table given as a dict mapping column names to equal-length lists.

    1. Replace each value that is a key of `replacements` with its mapped value.
    2. Encode every column containing strings as integer codes 0..k-1, numbering
       the distinct values in sorted order.
    3. Standardize every column: subtract the mean and divide by the sample
       standard deviation (n - 1 denominator).

    Returns a dict mapping each column name to a list of standardized floats,
    preserving the original column order.

    Columns with zero sample standard deviation (including constant columns and
    columns with fewer than two rows, where the sample std is undefined) are
    returned as all 0.0 rather than raising a division error.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists")

    if replacements is None:
        replacements = {}

    # Check that all columns have the same length.
    lengths = {len(col) for col in data.values()}
    if len(lengths) > 1:
        raise ValueError("all columns must have equal length")

    def _replace(value):
        try:
            if value in replacements:
                return replacements[value]
        except TypeError:
            # Unhashable value cannot be a key of the replacements dict.
            pass
        return value

    result = {}
    for name, column in data.items():
        # Step 1: replacements
        values = [_replace(v) for v in column]

        # Step 2: integer-encode string columns
        if any(isinstance(v, str) for v in values):
            distinct = sorted(set(values))
            code_of = {v: i for i, v in enumerate(distinct)}
            values = [code_of[v] for v in values]

        # Step 3: standardize
        nums = [float(v) for v in values]
        n = len(nums)
        if n == 0:
            result[name] = []
            continue

        mean = sum(nums) / n
        if n < 2:
            std = 0.0
        else:
            var = sum((x - mean) ** 2 for x in nums) / (n - 1)
            std = math.sqrt(var)

        if std == 0:
            result[name] = [0.0] * n
        else:
            result[name] = [(x - mean) / std for x in nums]

    return result
```

**Example usage:**

