    """
    Preprocess a table (dict of column name -> equal-length list of values).

    1. Replace every value that is a key of `replacements` with its mapped value.
    2. Encode every column containing strings as integer codes 0..k-1, where the
       distinct values are numbered in sorted order.
    3. Standardize every column: subtract the mean and divide by the sample
       standard deviation (ddof=1).

    Returns a dict mapping each column name to its list of standardized floats,
    preserving the original column order.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists")
    if replacements is None:
        replacements = {}
    if not isinstance(replacements, dict):
        raise ValueError("replacements must be a dict")

    # Check that all columns have equal length.
    lengths = {len(col) for col in data.values()}
    if len(lengths) > 1:
        raise ValueError("all columns must have equal length")

    # Step 1: apply replacements.
    replaced = {}
    for name, values in data.items():
        new_values = []
        for v in values:
            try:
                if v in replacements:
                    new_values.append(replacements[v])
                    continue
            except TypeError:
                # Unhashable value cannot be a key of the dict.
                pass
            new_values.append(v)
        replaced[name] = new_values

    # Step 2: encode string-containing columns as integer codes.
    encoded = {}
    for name, values in replaced.items():
        if any(isinstance(v, str) for v in values):
            distinct = set(values)
            try:
                ordered = sorted(distinct)
            except TypeError:
                # Mixed, non-comparable types: fall back to a string ordering.
                ordered = sorted(distinct, key=lambda x: (type(x).__name__, str(x)))
            code = {v: i for i, v in enumerate(ordered)}
            encoded[name] = [code[v] for v in values]
        else:
            encoded[name] = list(values)

    # Step 3: standardize each column.
    result = {}
    for name, values in encoded.items():
        nums = [float(v) for v in values]
        n = len(nums)
        if n == 0:
            result[name] = []
            continue
        mean = sum(nums) / n
        if n > 1:
            var = sum((x - mean) ** 2 for x in nums) / (n - 1)
            std = math.sqrt(var)
        else:
            std = 0.0
        if std == 0:
            # Constant (or single-element) column: standardized values are all zero.
            result[name] = [0.0] * n
        else:
            result[name] = [(x - mean) / std for x in nums]

