import math


def encode_and_standardize(data, replacements):
    """
    Preprocess a table (dict of column name -> equal-length list of values).

    1. Replace any value that is a key of `replacements` with its mapped value.
    2. Encode every column containing strings as integer codes 0..k-1,
       numbering the distinct values in sorted order.
    3. Standardize every column: subtract the mean and divide by the
       sample standard deviation (ddof=1).

    Returns a dict mapping each column name to its list of standardized
    floats, preserving the original column order.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists")

    if not data:
        return {}

    lengths = {len(col) for col in data.values()}
    if len(lengths) != 1:
        raise ValueError("all columns must have equal length")
    n = lengths.pop()
    if n < 2:
        raise ValueError("at least two rows are required to compute a sample standard deviation")

    if replacements is None:
        replacements = {}

    def replace(value):
        try:
            if value in replacements:
                return replacements[value]
        except TypeError:  # unhashable value cannot be a key
            pass
        return value

    result = {}
    for name, column in data.items():
        # Step 1: replacements
        values = [replace(v) for v in column]

        # Step 2: encode string-containing columns as integer codes
        if any(isinstance(v, str) for v in values):
            try:
                distinct = sorted(set(values))
            except TypeError:
                # Mixed, non-comparable types: fall back to a stable ordering
                distinct = sorted(set(values), key=lambda v: (type(v).__name__, repr(v)))
            codes = {v: i for i, v in enumerate(distinct)}
            values = [codes[v] for v in values]

        # Step 3: standardize
        nums = [float(v) for v in values]
        mean = sum(nums) / n
        var = sum((x - mean) ** 2 for x in nums) / (n - 1)
        sd = math.sqrt(var)
        if sd == 0:
            standardized = [0.0] * n
        else:
            standardized = [(x - mean) / sd for x in nums]

        result[name] = standardized

    return result
```

**Notes on behavior:**

- Replacement is applied in a single pass, so a replacement's output is not itself re-replaced.
- A column is treated as "containing strings" if any of its values (after replacement) is a string; the whole column is then encoded, with non-string values ranked among the distinct values in sorted order.
- Sample standard deviation uses `n - 1` in the denominator. If a column has zero variance, its standardized values are all `0.0` rather than raising a division error.
- A `ValueError` is raised if `data` is not a dict, if columns have unequal lengths, or if there are fewer than two rows (the sample standard deviation is undefined).

