import math
from numbers import Real


def _is_number(value):
    # Booleans are technically ints in Python, but they are not treated as numeric here.
    return isinstance(value, Real) and not isinstance(value, bool)


def correlation_without_column(data, column):
    # Keep only numeric columns, skipping the excluded column.
    numeric = {}
    for name, values in data.items():
        if name == column:
            continue
        values = list(values)
        if all(_is_number(v) for v in values):
            numeric[name] = [float(v) for v in values]

    if not numeric:
        return None

    def pearson(xs, ys):
        n = len(xs)
        if n == 0:
            return float('nan')
        mx = sum(xs) / n
        my = sum(ys) / n
        sxy = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
        sxx = sum((x - mx) ** 2 for x in xs)
        syy = sum((y - my) ** 2 for y in ys)
        if sxx == 0 or syy == 0:
            # Correlation is undefined when a column is constant.
            return float('nan')
        return sxy / math.sqrt(sxx * syy)

    names = list(numeric)
    result = {}
    for x in names:
        result[x] = {}
        for y in names:
            result[x][y] = pearson(numeric[x], numeric[y])
    return result
