import math


def correlation_without_column(data, column):
    """
    Return the Pearson correlation matrix of the numeric columns in `data`,
    after dropping `column` (if present).

    A column is kept only if every value in it is a real number (int or float,
    excluding bool). If no numeric columns remain, returns None.

    Pearson correlation is undefined when a column is constant (zero variance)
    or empty; those entries are returned as float('nan').
    """

    def is_number(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    numeric = {}
    for name, values in data.items():
        if name == column:
            continue
        values = list(values)
        if all(is_number(v) for v in values):
            numeric[name] = [float(v) for v in values]

    if not numeric:
        return None

    def pearson(x, y):
        n = len(x)
        if n == 0:
            return float('nan')
        mx = sum(x) / n
        my = sum(y) / n
        sxy = sum((a - mx) * (b - my) for a, b in zip(x, y))
        sxx = sum((a - mx) ** 2 for a in x)
        syy = sum((b - my) ** 2 for b in y)
        denom = math.sqrt(sxx * syy)
        if denom == 0:
            return float('nan')
        return sxy / denom

    names = list(numeric)
    result = {}
    for x in names:
        result[x] = {}
        for y in names:
            result[x][y] = pearson(numeric[x], numeric[y])
    return result
```

