import math

def correlation_without_column(data, column):
    """
    Return the Pearson correlation matrix of the numeric columns in `data`,
    excluding `column`. Returns None if no numeric columns remain.

    A column is numeric if every value is an int or float (bools are excluded).
    If a column has zero variance, its correlations are NaN, since the
    correlation is undefined.
    """
    numeric = {}
    for name, values in data.items():
        if name == column:
            continue
        values = list(values)
        if all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in values):
            numeric[name] = [float(v) for v in values]

    if not numeric:
        return None

    names = list(numeric)
    n = len(numeric[names[0]])
    if n == 0:
        nan = float('nan')
        return {x: {y: nan for y in names} for x in names}

    means = {name: sum(vals) / n for name, vals in numeric.items()}
    centered = {name: [v - means[name] for v in vals] for name, vals in numeric.items()}
    ss = {name: sum(d * d for d in centered[name]) for name in names}

    result = {}
    for x in names:
        result[x] = {}
        for y in names:
            denom = math.sqrt(ss[x]) * math.sqrt(ss[y])
            if denom == 0:
                result[x][y] = float('nan')
            else:
                cov = sum(a * b for a, b in zip(centered[x], centered[y]))
                result[x][y] = cov / denom
    return result
```

