import math

def column_histograms(table):
    """
    Compute 10-bin equal-width histograms for every all-numeric column in `table`.

    `table` maps column names to equal-length lists of values. For each column
    whose values are all numbers (int or float, excluding bool), the histogram
    spans the column's min to max with 10 equal-width bins; the last bin includes
    the maximum. Returns a dict mapping each numeric column name to its list of
    10 bin counts, in the table's column order. Non-numeric columns are skipped.

    Raises ValueError if `table` is not a non-empty dict or has no numeric columns.
    """
    if not isinstance(table, dict) or len(table) == 0:
        raise ValueError("table must be a non-empty dict")

    def is_number(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    NUM_BINS = 10
    result = {}

    for name, values in table.items():
        # Skip columns that are not sequences, are empty, or contain non-numeric values.
        if not isinstance(values, (list, tuple)) or len(values) == 0:
            continue
        if not all(is_number(v) for v in values):
            continue
        # NaN has no place in an ordered histogram; treat such columns as non-numeric.
        if any(math.isnan(v) for v in values):
            continue

        lo = min(values)
        hi = max(values)
        counts = [0] * NUM_BINS

        if hi == lo:
            # All values identical: every value equals the maximum, so it falls in the last bin.
            counts[-1] = len(values)
        else:
            width = (hi - lo) / NUM_BINS
            for v in values:
                idx = int((v - lo) / width)
                if idx >= NUM_BINS:  # v == hi (and any floating-point overshoot)
                    idx = NUM_BINS - 1
                elif idx < 0:
                    idx = 0
                counts[idx] += 1

        result[name] = counts

    if not result:
        raise ValueError("table has no numeric columns")

    return result
```

