def column_histograms(table):
    """
    Compute 10-bin equal-width histograms for each all-numeric column.

    table: dict mapping column names to equal-length lists of values.
    Returns a dict mapping each numeric column name to its list of 10 bin counts,
    in the table's column order. Non-numeric columns are skipped.

    Raises ValueError if table is not a non-empty dict or has no numeric columns.
    """
    if not isinstance(table, dict) or len(table) == 0:
        raise ValueError("table must be a non-empty dict")

    def is_number(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    NUM_BINS = 10
    result = {}

    for name, values in table.items():
        values = list(values)
        # Only columns where every value is a number (and there is at least one) qualify.
        if not values or not all(is_number(v) for v in values):
            continue

        lo = min(values)
        hi = max(values)
        counts = [0] * NUM_BINS

        if hi == lo:
            # Zero-width range: all values fall into the first bin.
            counts[0] = len(values)
        else:
            width = hi - lo
            for v in values:
                idx = int((v - lo) * NUM_BINS / width)
                if idx >= NUM_BINS:  # the maximum value goes into the last bin
                    idx = NUM_BINS - 1
                counts[idx] += 1

        result[name] = counts

    if not result:
        raise ValueError("table has no numeric columns")

    return result


