import math
import re
from collections import Counter

def tfidf_scores_for_question_articles(titles, contents):
    # Keep bodies of articles whose title contains "how" or "what" (case-insensitive, anywhere)
    picked = [
        body for title, body in zip(titles, contents)
        if 'how' in title.lower() or 'what' in title.lower()
    ]

    N = len(picked)
    if N == 0:
        return {}

    # Raw term counts per picked article; words are lowercased runs of 2+ word characters
    docs = [Counter(re.findall(r'\w\w+', body.lower())) for body in picked]

    # Document frequency over the picked articles
    df = Counter()
    for counts in docs:
        df.update(counts.keys())

    # Smoothed idf: ln((1+N)/(1+df)) + 1
    idf = {word: math.log((1 + N) / (1 + d)) + 1 for word, d in df.items()}

    result = {}
    for counts in docs:
        vec = {word: tf * idf[word] for word, tf in counts.items()}
        norm = math.sqrt(sum(v * v for v in vec.values()))
        if norm == 0:
            continue  # article with no words contributes nothing
        for word, v in vec.items():
            result[word] = result.get(word, 0.0) + v / norm

    return result


if __name__ == "__main__":
    print(tfidf_scores_for_question_articles(
        ['How to make pancakes', 'News update'],
        ['Make pancakes, make friends', 'Politics today']
    ))
    # {'make': 0.8164965809277261, 'pancakes': 0.4082482904638631, 'friends': 0.4082482904638631}
```

