import math
import re
from collections import Counter


def tfidf_scores_for_question_articles(titles, contents):
    # Keep only articles whose title contains "how" or "what" (case-insensitive,
    # matching anywhere, including inside longer words).
    picked = [
        body
        for title, body in zip(titles, contents)
        if "how" in title.lower() or "what" in title.lower()
    ]

    if not picked:
        return {}

    n_docs = len(picked)

    # Tokenise: lowercased runs of two or more word characters.
    token_lists = [re.findall(r"\w{2,}", body.lower()) for body in picked]

    # Document frequency over the picked bodies.
    df = Counter()
    for tokens in token_lists:
        df.update(set(tokens))

    # Smoothed idf: ln((1+N)/(1+df)) + 1
    idf = {word: math.log((1 + n_docs) / (1 + d)) + 1 for word, d in df.items()}

    result = {}
    for tokens in token_lists:
        tf = Counter(tokens)  # raw term counts
        vec = {word: count * idf[word] for word, count in tf.items()}

        # L2 normalisation of this article's vector
        norm = math.sqrt(sum(v * v for v in vec.values()))
        if norm == 0:
            continue

        for word, v in vec.items():
            result[word] = result.get(word, 0.0) + v / norm

    return result
```

