def course_grade_summary(records):
    totals = {}  # course -> [sum_of_grades, number_of_grades, passing_count]

    for student, course, grade in records:
        if course not in totals:
            totals[course] = [0, 0, 0]
        entry = totals[course]
        entry[0] += grade
        entry[1] += 1
        if grade >= 60:
            entry[2] += 1

    summary = {}
    for course, (total, count, passing) in totals.items():
        summary[course] = (total / count, passing)

