import xml.etree.ElementTree as ET


def xml_to_dict(s):
    """
    Parse an XML string into nested Python dicts.

    - The result maps the root tag to its converted content.
    - An element containing only text becomes that text string.
    - An empty element (no attributes, children, or text) becomes None.
    - Otherwise it becomes a dict where:
        * attributes appear as '@name' keys,
        * child elements appear under their tag; repeated sibling tags
          map to a list of their values in document order,
        * text content appears under '#text'.
    - All values are strings (or None / nested dicts and lists).

    Raises ValueError if the input is empty or only whitespace
    (or is not well-formed XML).
    """
    if s is None or not s.strip():
        raise ValueError("XML input is empty or only whitespace")

    try:
        root = ET.fromstring(s)
    except ET.ParseError as exc:
        raise ValueError(f"Invalid XML: {exc}") from exc

    def convert(elem):
        result = {}
        list_keys = set()  # tags whose value is already a list of repeats

        # Attributes
        for name, value in elem.attrib.items():
            result['@' + name] = value

        # Child elements
        has_children = False
        for child in elem:
            has_children = True
            value = convert(child)
            if child.tag in result:
                if child.tag in list_keys:
                    result[child.tag].append(value)
                else:
                    result[child.tag] = [result[child.tag], value]
                    list_keys.add(child.tag)
            else:
                result[child.tag] = value

        # Text: element's own text plus tails of its children (non-whitespace only)
        pieces = []
        if elem.text and elem.text.strip():
            pieces.append(elem.text.strip())
        for child in elem:
            if child.tail and child.tail.strip():
                pieces.append(child.tail.strip())
        text = ' '.join(pieces)

        # Text-only element -> plain string; empty element -> None
        if not elem.attrib and not has_children:
            return text if text else None

        if text:
            result['#text'] = text
        return result

    return {root.tag: convert(root)}
