```python
import xml.etree.ElementTree as ET


def xml_to_dict(s):
    """
    Parse an XML string into nested Python dicts.

    Rules:
      - The result maps the root tag to its converted content.
      - An element with only text (no attributes, no children) becomes that text.
      - An empty element (no attributes, children, or text) becomes None.
      - Otherwise the element becomes a dict where:
          * attributes appear as '@name' keys,
          * child elements appear under their tag,
          * text appears under '#text'.
      - Sibling elements sharing a tag become a list in document order.
      - All values are strings (apart from None and the containing dicts/lists).

    Raises ValueError if the input is empty/whitespace-only or is not well-formed XML.
    """
    if not isinstance(s, str) or not s.strip():
        raise ValueError("Input XML string is empty or contains only whitespace")

    try:
        root = ET.fromstring(s.strip())
    except ET.ParseError as e:
        raise ValueError(f"Invalid XML: {e}") from e

    return {root.tag: _convert_element(root)}


def _convert_element(elem):
    children = list(elem)

    # Direct text: the element's leading text plus the tails of its children
    # (the text that follows each child), stripped of surrounding whitespace.
    text = (
        (elem.text or "") + "".join(child.tail or "" for child in children)
    ).strip()

    # Text-only element with no attributes becomes a plain string.
    if not elem.attrib and not children:
        return text if text else None

    result = {}

    for name, value in elem.attrib.items():
        result["@" + name] = value

    repeated = set()
    for child in children:
        value = _convert_element(child)
        tag = child.tag
        if tag in result:
            if tag not in repeated:
                result[tag] = [result[tag]]
                repeated.add(tag)
            result[tag].append(value)
        else:
            result[tag] = value

    if text:
        result["#text"] = text

    return result


if __name__ == "__main__":
    print(xml_to_dict('<book id="123">Python Guide</book>'))
    # {'book': {'@id': '123', '#text': 'Python Guide'}}

    print(xml_to_dict('<root><item>a</item><item>b</item><empty/></root>'))
    # {'root': {'item': ['a', 'b'], 'empty': None}}
```

