from html.parser import HTMLParser


class _TableRowParser(HTMLParser):
    """Collects the rows (as lists of cell texts) of the first table with a given id."""

    def __init__(self, table_id):
        super().__init__(convert_charrefs=True)  # decodes entities in data
        self.table_id = table_id
        self.found = False
        self.done = False
        self.depth = 0        # nesting depth of <table> elements inside the target
        self.rows = []
        self.row = None       # list of cells for the current <tr>, or None
        self.cell = None      # list of text fragments for the current <td>/<th>, or None

    def _finish_cell(self):
        if self.cell is not None and self.row is not None:
            self.row.append(''.join(self.cell).strip())
        self.cell = None

    def _finish_row(self):
        self._finish_cell()
        if self.row is not None:
            self.rows.append(self.row)
        self.row = None

    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        if not self.found:
            if tag == 'table' and dict(attrs).get('id') == self.table_id:
                self.found = True
                self.depth = 1
            return
        if tag == 'table':
            self.depth += 1
            return
        if self.depth > 1:
            # Inside a nested table: its text is kept as part of the current cell.
            return
        if tag == 'tr':
            self._finish_row()
            self.row = []
        elif tag in ('td', 'th'):
            self._finish_cell()
            if self.row is None:
                self.row = []
            self.cell = []

    def handle_endtag(self, tag):
        if self.done or not self.found:
            return
        if tag == 'table':
            self.depth -= 1
            if self.depth == 0:
                self._finish_row()
                self.done = True
            return
        if self.depth > 1:
            return
        if tag in ('td', 'th'):
            self._finish_cell()
        elif tag == 'tr':
            self._finish_row()

    def handle_data(self, data):
        if self.done or not self.found:
            return
        if self.cell is not None:
            self.cell.append(data)


def html_table_records(html, table_id):
    parser = _TableRowParser(table_id)
    parser.feed(html)
    parser.close()

    if not parser.found:
        raise ValueError(f"No table with id {table_id!r} found")

    rows = parser.rows
    if not rows:
        return []

    headers = rows[0]
    records = []
    for row in rows[1:]:
        record = {}
        for i, header in enumerate(headers):
            record[header] = row[i] if i < len(row) else ''
        records.append(record)
    return records
