from html.parser import HTMLParser


class _TableExtractor(HTMLParser):
    """Collects the rows of the first table whose id matches."""

    def __init__(self, table_id):
        super().__init__(convert_charrefs=True)  # decodes entities in data
        self.table_id = table_id
        self.stack = []        # currently open tables
        self.found = False     # whether the target table was seen
        self.done = False      # whether the target table has been closed
        self.rows = None       # list of rows (each a list of cell texts)

    # --- helpers -----------------------------------------------------------
    @staticmethod
    def _close_cell(top):
        if top["cell"] is not None:
            top["row"].append("".join(top["cell"]).strip())
            top["cell"] = None

    def _close_row(self, top):
        self._close_cell(top)
        if top["row"] is not None:
            top["rows"].append(top["row"])
            top["row"] = None

    def _finish_table(self, top):
        self._close_row(top)
        if top["target"]:
            self.rows = top["rows"]
            self.done = True

    # --- HTMLParser callbacks ----------------------------------------------
    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        if tag == "table":
            attr_map = dict(attrs)
            is_target = (not self.found) and attr_map.get("id") == self.table_id
            if is_target:
                self.found = True
            self.stack.append({"target": is_target, "rows": [],
                               "row": None, "cell": None})
            return
        if not self.stack:
            return
        top = self.stack[-1]
        if tag == "tr":
            self._close_row(top)
            top["row"] = []
        elif tag in ("td", "th"):
            self._close_cell(top)
            if top["row"] is None:
                top["row"] = []
            top["cell"] = []

    def handle_endtag(self, tag):
        if self.done or not self.stack:
            return
        top = self.stack[-1]
        if tag in ("td", "th"):
            self._close_cell(top)
        elif tag == "tr":
            self._close_row(top)
        elif tag == "table":
            self._finish_table(top)
            self.stack.pop()

    def handle_data(self, data):
        if self.done or not self.stack:
            return
        top = self.stack[-1]
        if top["cell"] is not None:
            top["cell"].append(data)

    def finish(self):
        """Close any tables left open at end of document."""
        while self.stack and not self.done:
            top = self.stack.pop()
            self._finish_table(top)


def html_table_records(html, table_id):
    parser = _TableExtractor(table_id)
    parser.feed(html)
    parser.close()
    parser.finish()

    if not parser.found:
        raise ValueError(f"No table with id {table_id!r} found")

    rows = parser.rows or []
    if not rows:
        return []

    headers = rows[0]
    records = []
    for row in rows[1:]:
        record = {}
        for i, header in enumerate(headers):
            record[header] = row[i] if i < len(row) else ""
        records.append(record)
    return records
