- If a data row has fewer cells than there are headers, the missing columns get `''`. Extra cells beyond the header count are ignored.
- Nested tables inside the target table are not treated as rows of it; their text is folded into the enclosing cell.
- A table with only a header row, or no rows at all, returns `[]`.
- If no element matches `table_id`, a `ValueError` is raised.

```python
import re
from html.parser import HTMLParser


class _TextExtractor(HTMLParser):
    """Collects the character data of a document, ignoring tags and attributes."""

    _RAW_TEXT_TAGS = {"script", "style"}  # content is code, not page text

    def __init__(self):
        # convert_charrefs=True makes the parser decode entities such as &amp; and &#64;
        super().__init__(convert_charrefs=True)
        self._parts = []
        self._skip_depth = 0

    def handle_starttag(self, tag, attrs):
        if tag in self._RAW_TEXT_TAGS:
            self._skip_depth += 1

    def handle_endtag(self, tag):
        if tag in self._RAW_TEXT_TAGS and self._skip_depth > 0:
            self._skip_depth -= 1

    def handle_data(self, data):
        if self._skip_depth == 0:
            self._parts.append(data)

    def get_text(self):
        return "".join(self._parts)


def extract_emails_from_html(
    html,
    pattern=r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,7}\b',
):
    """
    Return every match of `pattern` found in the text content of `html`,
    in document order, keeping duplicates.

    Only text content counts: tags are removed, entities are decoded, and
    attribute values (e.g. href="mailto:...") are ignored. Contents of
    <script> and <style> elements are also excluded since they are not
    page text.
    """
    parser = _TextExtractor()
    parser.feed(html)
    parser.close()  # flush any buffered trailing text
    text = parser.get_text()
    return re.findall(pattern, text)


if __name__ == "__main__":
    print(extract_emails_from_html(
        '<p>Write to <b>sales@corp.com</b> or support@corp.org.</p>'
    ))  # ['sales@corp.com', 'support@corp.org']

    print(extract_emails_from_html(
        '<a href="mailto:hidden@x.com">link</a> &#109;e@example.com'
    ))  # ['me@example.com']
```

The function uses `html.parser.HTMLParser` rather than a regex to strip tags, since regex tag stripping is fragile. The parser passes only text nodes to the handler, so attribute values never reach the pattern, and `convert_charrefs=True` decodes entities like `&#109;` before matching. The text pieces are concatenated without separators, which matches "text with tags removed" literally. Because of that, an address split across an inline tag (such as `sales@<b>corp</b>.com`) is still found, but two adjacent block elements with no whitespace between them can merge into one string (`a@b.com</p><p>c@d.com` becomes `a@b.comc@d.com`). If you want block boundaries to act as separators, insert a space in `handle_endtag` or `handle_starttag` for block-level tags.

