import csv
import io


def concat_csv_tables(csv_texts):
    """
    Concatenate the data rows of several CSV documents that share the same columns.

    Each document must have a header row. Rows are returned in order as dicts
    mapping column name to value. A column whose values are all integers becomes
    a list of ints; a column whose values are all numeric (but not all integers)
    becomes floats; any other column stays as strings.
    """
    if not csv_texts:
        raise ValueError("csv_texts must not be empty")

    header = None
    raw_rows = []  # list of (column -> string value) dicts

    for text in csv_texts:
        doc_rows = [row for row in csv.reader(io.StringIO(text)) if row]
        if not doc_rows:
            raise ValueError("each CSV document must have a header row")

        doc_header = doc_rows[0]
        if header is None:
            header = doc_header
        elif doc_header != header:
            raise ValueError("all CSV documents must share the same columns")

        for row in doc_rows[1:]:
            if len(row) != len(header):
                raise ValueError("row length does not match header length")
            raw_rows.append(dict(zip(header, row)))

    def _all_parse(values, parser):
        try:
            for v in values:
                parser(v)
        except ValueError:
            return False
        return True

    # Decide the type of each column and convert its values.
    converted = {}
    for col in header:
        values = [row[col] for row in raw_rows]
        if _all_parse(values, int):
            converted[col] = [int(v) for v in values]
        elif _all_parse(values, float):
            converted[col] = [float(v) for v in values]
        else:
            converted[col] = values

    result = []
    for i in range(len(raw_rows)):
        result.append({col: converted[col][i] for col in header})
    return result


if __name__ == "__main__":
    print(concat_csv_tables(["A,B\n0,3\n1,4\n", "A,B\n2,5\n"]))
    # [{'A': 0, 'B': 3}, {'A': 1, 'B': 4}, {'A': 2, 'B': 5}]
```

The function checks that the list is non-empty and that all headers match, then parses each column as int, then float, and falls back to strings if neither works for every value in that column.

```python
import csv
import io


def concat_csv_tables(csv_texts):
    """
    Concatenate the data rows of several CSV documents that share the same columns.

    Each document must have a header row. Rows are returned in order as dicts
    mapping column name to value. A column is converted to numbers only if every
    value in it (across all documents) is numeric: it becomes int if all values
    are integers, otherwise float. All other columns remain strings.

    Raises ValueError if the list is empty, if headers differ between documents,
    or if a row has the wrong number of fields.
    """
    if not csv_texts:
        raise ValueError("csv_texts must not be empty")

    columns = None
    raw_rows = []

    for text in csv_texts:
        reader = csv.reader(io.StringIO(text))
        header = next(reader, None)
        if header is None:
            continue  # completely empty document
        if columns is None:
            columns = header
        elif header != columns:
            raise ValueError(f"Mismatched columns: {header} != {columns}")

        for row in reader:
            if not row:  # skip blank lines
                continue
            if len(row) != len(columns):
                raise ValueError(
                    f"Row has {len(row)} fields, expected {len(columns)}: {row}"
                )
            raw_rows.append(row)

    if columns is None:
        return []

    def _as_int(s):
        try:
            return int(s)
        except ValueError:
            return None

    def _as_float(s):
        try:
            return float(s)
        except ValueError:
            return None

    # Determine the conversion for each column.
    converters = []
    for i in range(len(columns)):
        values = [row[i] for row in raw_rows]
        if values and all(_as_int(v) is not None for v in values):
            converters.append(_as_int)
        elif values and all(_as_float(v) is not None for v in values):
            converters.append(_as_float)
        else:
            converters.append(lambda v: v)  # keep as string

    result = []
    for row in raw_rows:
        result.append(
            {col: conv(val) for col, conv, val in zip(columns, converters, row)}
        )
    return result
```

For the example `concat_csv_tables(["A,B\n0,3\n1,4\n", "A,B\n2,5\n"])`, this returns `[{'A': 0, 'B': 3}, {'A': 1, 'B': 4}, {'A': 2, 'B': 5}]`.

Some behaviours to be aware of:
- A column with integer-only values becomes `int`. If any value in the column has a decimal point (e.g. `2.5`), the whole column becomes `float`.
- An empty cell makes its column a string column, since an empty string is not numeric.
- Documents with no content at all are skipped. If every document is empty, the function returns `[]`.
- I added one check beyond the spec: documents with different headers raise a `ValueError`.

