import csv
import io


def _parse_number(s):
    """Return int or float for a numeric string, or None if it is not numeric."""
    try:
        return int(s)
    except ValueError:
        pass
    try:
        return float(s)
    except ValueError:
        return None


def concat_csv_tables(csv_texts):
    """
    Concatenate the data rows of several CSV documents (each with a header row
    and the same columns) into a list of dicts.

    Columns whose values are all numeric are converted to int (if every value
    is an integer) or float (otherwise). All other columns remain strings.
    """
    if not csv_texts:
        raise ValueError("csv_texts must not be empty")

    header = None
    rows = []

    for text in csv_texts:
        reader = csv.reader(io.StringIO(text))
        try:
            doc_header = next(reader)
        except StopIteration:
            raise ValueError("every CSV document must have a header row")

        if header is None:
            header = doc_header
        elif doc_header != header:
            raise ValueError(
                f"header mismatch: expected {header!r}, got {doc_header!r}"
            )

        for row in reader:
            if not row:  # skip blank lines
                continue
            if len(row) != len(header):
                raise ValueError(
                    f"row {row!r} has {len(row)} fields, expected {len(header)}"
                )
            rows.append(row)

    # Decide the type of each column across all documents.
    converters = []
    for i in range(len(header)):
        parsed = [_parse_number(r[i]) for r in rows]
        if rows and all(p is not None for p in parsed):
            if all(isinstance(p, int) for p in parsed):
                converters.append(("int", parsed))
            else:
                converters.append(("float", [float(p) for p in parsed]))
        else:
            converters.append(("str", [r[i] for r in rows]))

    # Assemble the result dicts column by column.
    columns = [values for _, values in converters]
    result = []
    for row_idx in range(len(rows)):
        result.append({header[col]: columns[col][row_idx] for col in range(len(header))})
    return result
```

