```python
import csv
import io


def _parse_int(s):
    try:
        int(s)
        return True
    except ValueError:
        return False


def _parse_float(s):
    try:
        float(s)
        return True
    except ValueError:
        return False


def concat_csv_tables(csv_texts):
    """
    Concatenate the data rows of several CSV documents (each with a header row
    and the same columns) into a list of dicts.

    Columns whose values are all numeric are converted to int (if every value
    is an integer) or float (otherwise). All other columns remain strings.
    """
    if not csv_texts:
        raise ValueError("csv_texts must not be empty")

    columns = None
    raw_rows = []  # list of lists of strings, in order

    for text in csv_texts:
        header = None
        for row in csv.reader(io.StringIO(text)):
            if not row:  # skip blank lines
                continue
            if header is None:
                header = row
                if columns is None:
                    columns = header
                elif header != columns:
                    raise ValueError(
                        f"CSV header {header} does not match expected columns {columns}"
                    )
                continue
            if len(row) != len(columns):
                raise ValueError(
                    f"Row {row} has {len(row)} fields, expected {len(columns)}"
                )
            raw_rows.append(row)

        if header is None:
            raise ValueError("CSV document is missing a header row")

    # Determine the type of each column.
    column_types = {}
    for i, name in enumerate(columns):
        values = [r[i] for r in raw_rows]
        if values and all(_parse_float(v) for v in values):
            if all(_parse_int(v) for v in values):
                column_types[name] = int
            else:
                column_types[name] = float
        else:
            column_types[name] = str

    # Build the result.
    result = []
    for row in raw_rows:
        record = {}
        for i, name in enumerate(columns):
            typ = column_types[name]
            value = row[i]
            record[name] = value if typ is str else typ(value)
        result.append(record)

    return result
