import csv
import io
import statistics


def column_summary_stats(csv_text, column_name):
    """
    Return the mean, median, and population standard deviation of a numeric
    CSV column.

    Parameters:
        csv_text (str): The full text of a CSV file with a header row.
        column_name (str): The name of the column to summarize.

    Returns:
        dict: {'mean': float, 'median': float, 'std_dev': float}

    Raises:
        ValueError: If the column is not in the header, if a value in the
            column is not numeric, or if the column has no numeric values.
    """
    reader = csv.DictReader(io.StringIO(csv_text))

    if reader.fieldnames is None or column_name not in reader.fieldnames:
        raise ValueError(f"Column {column_name!r} not found in header")

    values = []
    for row in reader:
        raw = row.get(column_name)
        if raw is None or raw.strip() == "":
            continue  # skip blank cells
        try:
            values.append(float(raw))
        except ValueError:
            raise ValueError(
                f"Non-numeric value {raw!r} in column {column_name!r}"
            ) from None

    if not values:
        raise ValueError(f"Column {column_name!r} has no numeric values")

    return {
        'mean': float(statistics.mean(values)),
        'median': float(statistics.median(values)),
        'std_dev': float(statistics.pstdev(values)),
    }


if __name__ == "__main__":
    print(column_summary_stats('Sales\n100\n200\n150\n300\n250\n', 'Sales'))
    # {'mean': 200.0, 'median': 200.0, 'std_dev': 70.71067811865476}
```

The function uses `csv.DictReader` to parse the header and rows, and the `statistics` module for the calculations. `pstdev` gives the population standard deviation, as requested. Blank cells are skipped, and a non-numeric value or a missing column raises a `ValueError`.

