```python
import math


def mapped_correlation_matrix(data, mapping):
    """
    Replace values in each column using `mapping`, then return the pairwise
    Pearson correlation matrix of the columns as a nested dict.

    Any value that appears as a key in `mapping` is replaced by its mapped
    value; other values are left unchanged. After replacement every value
    must be numeric.

    Returns a dict where result[a][b] is the Pearson correlation between
    columns a and b. If a column has zero variance, its correlations are NaN.

    Raises ValueError if `data` is not a dict, if columns have unequal
    lengths, or if a column is empty.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    columns = {}
    length = None
    for name, values in data.items():
        values = list(values)
        if length is None:
            length = len(values)
        elif len(values) != length:
            raise ValueError("all columns must have equal length")
        columns[name] = [
            mapping[v] if v in mapping else v for v in values
        ]

    if length == 0:
        raise ValueError("columns must not be empty")

    # Ensure all values are numeric after mapping
    for name, vals in columns.items():
        for v in vals:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(
                    f"non-numeric value {v!r} in column {name!r} after mapping"
                )

    def _mean(xs):
        return sum(xs) / len(xs)

    means = {name: _mean(vals) for name, vals in columns.items()}

    def _corr(a, b):
        xa, xb = columns[a], columns[b]
        ma, mb = means[a], means[b]
        cov = sum((x - ma) * (y - mb) for x, y in zip(xa, xb))
        va = sum((x - ma) ** 2 for x in xa)
        vb = sum((y - mb) ** 2 for y in xb)
        if va == 0 or vb == 0:
            return float("nan")
        return cov / math.sqrt(va * vb)

    names = list(columns.keys())
    result = {a: {} for a in names}
    for a in names:
        for b in names:
            if a == b:
                result[a][b] = 1.0 if means and _corr(a, b) == _corr(a, b) else float("nan")
            else:
                result[a][b] = _corr(a, b)
    return result
```

For the example `mapped_correlation_matrix({'m': ['lo', 'lo', 'hi'], 'n': [5, 3, 5]}, {'lo': 1, 'hi': 2})`, the mapping turns `m` into `[1, 1, 2]`. The correlation between `m` and `n` works out to 6 / √(6 · 24/9 · 9/6)... more simply 6 / 12 = 0.5, so the function returns `{'m': {'m': 1.0, 'n': 0.5}, 'n': {'m': 0.5, 'n': 1.0}}`.

Two choices the spec left open:
- A constant column has zero variance, so its correlations (including with itself) are returned as `NaN`.
- Non-numeric values after mapping raise a `ValueError`.

```python
import math


def mapped_correlation_matrix(data, mapping):
    """
    Replace values in each column using `mapping`, then return the pairwise
    Pearson correlation matrix of the columns as a nested dict.

    data:    dict mapping column names to equal-length lists of values.
    mapping: dict; any value that is a key in `mapping` is replaced by
             the corresponding value. Other values are left unchanged.

    Returns result such that result[a][b] is the Pearson correlation
    between columns a and b. Correlations involving a constant column
    (zero variance) are float('nan').
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")
    if not isinstance(mapping, dict):
        raise ValueError("mapping must be a dict")

    # Apply the mapping and convert every value to a float.
    columns = {}
    length = None
    for name, values in data.items():
        values = list(values)
        if length is None:
            length = len(values)
        elif len(values) != length:
            raise ValueError("all columns must have equal length")
        mapped = []
        for v in values:
            try:
                key_present = v in mapping
            except TypeError:  # unhashable value cannot be a key
                key_present = False
            mapped.append(mapping[v] if key_present else v)
        try:
            columns[name] = [float(x) for x in mapped]
        except (TypeError, ValueError):
            raise ValueError(f"column {name!r} contains non-numeric values after mapping")

    names = list(columns.keys())
    n = length or 0

    means = {}
    for name in names:
        vals = columns[name]
        means[name] = sum(vals) / n if n else float('nan')

    def cov_sum(a, b):
        ma, mb = means[a], means[b]
        return sum((x - ma) * (y - mb) for x, y in zip(columns[a], columns[b]))

    ss = {name: cov_sum(name, name) for name in names}

    result = {a: {} for a in names}
    for a in names:
        for b in names:
            if a == b:
                if ss[a] == 0 or n == 0:
                    result[a][b] = float('nan')
                else:
                    result[a][b] = 1.0
                continue
            denom_sq = ss[a] * ss[b]
            if denom_sq <= 0 or n == 0:
                result[a][b] = float('nan')
            else:
                result[a][b] = cov_sum(a, b) / math.sqrt(denom_sq)
    return result
```

For the example `mapped_correlation_matrix({'m': ['lo', 'lo', 'hi'], 'n': [5, 3, 5]}, {'lo': 1, 'hi': 2})`, the column `m` becomes `[1, 1, 2]`, and the function returns `{'m': {'m': 1.0, 'n': 0.5}, 'n': {'m': 0.5, 'n': 1.0}}`.

