import math


def mapped_correlation_matrix(data, mapping):
    """
    Replace values in `data` using `mapping`, then return the pairwise
    Pearson correlation matrix of the columns as a nested dict.

    data:    dict mapping column names to equal-length lists of values.
    mapping: dict; any value that is a key in `mapping` is replaced by
             the corresponding value, other values are left unchanged.

    Returns result such that result[a][b] is the Pearson correlation
    between columns a and b.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")
    if mapping is None:
        mapping = {}
    if not isinstance(mapping, dict):
        raise ValueError("mapping must be a dict")

    # Apply the mapping and convert to numeric values.
    converted = {}
    lengths = set()
    for col, values in data.items():
        if not isinstance(values, (list, tuple)):
            raise ValueError(f"column {col!r} must be a list of values")
        new_vals = []
        for v in values:
            try:
                if v in mapping:
                    v = mapping[v]
            except TypeError:
                # unhashable value cannot be a mapping key
                pass
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(
                    f"non-numeric value {v!r} in column {col!r} after mapping"
                )
            new_vals.append(float(v))
        converted[col] = new_vals
        lengths.add(len(new_vals))

    if len(lengths) > 1:
        raise ValueError("all columns must have equal length")

    def pearson(x, y):
        n = len(x)
        if n == 0:
            return float("nan")
        mx = sum(x) / n
        my = sum(y) / n
        sxy = sum((a - mx) * (b - my) for a, b in zip(x, y))
        sxx = sum((a - mx) ** 2 for a in x)
        syy = sum((b - my) ** 2 for b in y)
        if sxx == 0 or syy == 0:
            return float("nan")  # correlation undefined for constant columns
        return sxy / math.sqrt(sxx * syy)

    result = {}
    for a in data:
        result[a] = {}
        for b in data:
            if a == b:
                # Diagonal: a column is perfectly correlated with itself
                x = converted[a]
                result[a][b] = 1.0 if len(set(x)) > 1 else float("nan")
            else:
                result[a][b] = pearson(converted[a], converted[b])
    return result
```

For the example `mapped_correlation_matrix({'m': ['lo', 'lo', 'hi'], 'n': [5, 3, 5]}, {'lo': 1, 'hi': 2})`, the code maps `m` to `[1, 1, 2]`, and the correlation between `m` and `n` works out to 0.5, giving `{'m': {'m': 1.0, 'n': 0.5}, 'n': {'m': 0.5, 'n': 1.0}}`.

Constant columns have undefined correlation, so the function returns `nan` for them rather than raising an error. The spec didn't say what to do in that case, so change it if you need a different behavior.

```python
import math


def mapped_correlation_matrix(data, mapping):
    """
    Replace values in `data` using `mapping`, then return the pairwise
    Pearson correlation matrix of the columns as a nested dict.

    - data: dict mapping column names to equal-length lists of values.
    - mapping: dict; any value that is a key in mapping is replaced by
      mapping[value]; other values are kept as they are.

    result[a][b] is the Pearson correlation between columns a and b.
    Correlations involving a constant column (zero variance) are NaN.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists")
    if mapping is None:
        mapping = {}
    if not isinstance(mapping, dict):
        raise ValueError("mapping must be a dict")

    # Apply the mapping and convert everything to float.
    columns = {}
    for name, values in data.items():
        if not isinstance(values, (list, tuple)):
            raise ValueError(f"column {name!r} must be a list of values")
        converted = []
        for v in values:
            replaced = mapping[v] if v in mapping else v
            converted.append(float(replaced))
        columns[name] = converted

    lengths = {len(vals) for vals in columns.values()}
    if len(lengths) > 1:
        raise ValueError("all columns must have equal length")

    names = list(columns.keys())
    n = lengths.pop() if lengths else 0

    # Precompute means and centered values.
    centered = {}
    for name in names:
        vals = columns[name]
        mean = sum(vals) / n if n else float("nan")
        centered[name] = [x - mean for x in vals]

    result = {a: {} for a in names}
    for i, a in enumerate(names):
        for b in names[i:]:
            if a == b:
                ss = sum(x * x for x in centered[a])
                r = 1.0 if ss > 0 else float("nan")
            else:
                da, db = centered[a], centered[b]
                sxy = sum(x * y for x, y in zip(da, db))
                sxx = sum(x * x for x in da)
                syy = sum(y * y for y in db)
                if sxx == 0 or syy == 0 or n == 0:
                    r = float("nan")
                else:
                    r = sxy / math.sqrt(sxx * syy)
                    # Guard against tiny floating-point overshoot.
                    r = max(-1.0, min(1.0, r))
            result[a][b] = r
            result[b][a] = r

    return result
```

