import math


def mapped_correlation_matrix(data, mapping):
    """
    Replace values using `mapping`, then return the pairwise Pearson
    correlation matrix of the columns in `data` as a nested dict.

    result[a][b] is the correlation between columns a and b.
    Zero-variance columns (or fewer than two rows) yield float('nan').
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists")
    if mapping is None:
        mapping = {}
    if not isinstance(mapping, dict):
        raise ValueError("mapping must be a dict")

    # Replace values and convert everything to float.
    columns = {}
    for name, values in data.items():
        converted = []
        for v in values:
            try:
                key_present = v in mapping
            except TypeError:  # unhashable value, cannot be a mapping key
                key_present = False
            x = mapping[v] if key_present else v
            converted.append(float(x))
        columns[name] = converted

    lengths = {len(v) for v in columns.values()}
    if len(lengths) > 1:
        raise ValueError("all columns must have equal length")
    n = lengths.pop() if lengths else 0

    def _sums(x, y):
        mx = sum(x) / n
        my = sum(y) / n
        sxy = sum((a - mx) * (b - my) for a, b in zip(x, y))
        sxx = sum((a - mx) ** 2 for a in x)
        syy = sum((b - my) ** 2 for b in y)
        return sxy, sxx, syy

    def _corr(a, b):
        x, y = columns[a], columns[b]
        if n < 2:
            return float("nan")
        sxy, sxx, syy = _sums(x, y)
        if a == b:
            return 1.0 if sxx > 0 else float("nan")
        if sxx == 0 or syy == 0:
            return float("nan")
        return sxy / (math.sqrt(sxx) * math.sqrt(syy))

    names = list(columns.keys())
    result = {}
    for a in names:
        result[a] = {}
        for b in names:
            result[a][b] = _corr(a, b)
    return result
```

