import csv
import io
import math


def csv_mean_median(csv_text):
    """
    Return (mean, median) of the numeric values in a single-column CSV text.

    The first row is treated as a header and skipped. Blank lines and
    non-numeric values are ignored. Returns (None, None) if there are
    no usable numeric values.
    """
    if not csv_text or not csv_text.strip():
        return (None, None)

    values = []
    reader = csv.reader(io.StringIO(csv_text))
    next(reader, None)  # skip header row

    for row in reader:
        if not row:
            continue
        cell = row[0].strip()
        if not cell:
            continue
        try:
            number = float(cell)
        except ValueError:
            continue
        if math.isfinite(number):
            values.append(number)

    if not values:
        return (None, None)

    values.sort()
    n = len(values)
    mean = sum(values) / n
    mid = n // 2
    if n % 2 == 1:
        median = values[mid]
    else:
        median = (values[mid - 1] + values[mid]) / 2.0

    return (mean, median)


if __name__ == "__main__":
    print(csv_mean_median("value\n10\n20\nabc\n40\n"))  # (23.333333333333332, 20.0)
    print(csv_mean_median(""))                          # (None, None)
    print(csv_mean_median("value\n"))                   # (None, None)
```

