import csv
import io
import math


def csv_mean_median(csv_text):
    """
    Return (mean, median) of the numeric values in the first column of a CSV
    text. The first row is treated as a header. Non-numeric values and blank
    lines are ignored. Returns (None, None) if there are no numeric values.
    """
    if not csv_text or not csv_text.strip():
        return (None, None)

    reader = csv.reader(io.StringIO(csv_text))
    next(reader, None)  # skip the header row

    values = []
    for row in reader:
        if not row:  # blank line
            continue
        cell = row[0].strip()
        if not cell:
            continue
        try:
            x = float(cell)
        except ValueError:
            continue
        # Ignore nan/inf, which would make the statistics meaningless.
        if math.isfinite(x):
            values.append(x)

    if not values:
        return (None, None)

    values.sort()
    n = len(values)
    mean = math.fsum(values) / n

    mid = n // 2
    if n % 2 == 1:
        median = values[mid]
    else:
        median = (values[mid - 1] + values[mid]) / 2

    return (mean, median)


if __name__ == "__main__":
    print(csv_mean_median("value\n10\n20\nabc\n40\n"))  # (23.333333333333332, 20.0)
    print(csv_mean_median(""))                          # (None, None)
    print(csv_mean_median("value\n"))                   # (None, None)
```

The function skips the header row, parses each row's first column as a float, and drops anything that fails to parse or is blank. It also drops `nan` and `inf`, since those would distort the statistics; if you want those kept, remove the `math.isfinite` check. For the example input, it returns `(23.333333333333332, 20.0)`.

