import ast
from html.parser import HTMLParser


class _ScriptCollector(HTMLParser):
    """Collects the text content of every <script> element, in document order."""

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.scripts = []
        self._in_script = False
        self._buf = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "script":
            self._in_script = True
            self._buf = []

    def handle_endtag(self, tag):
        if tag.lower() == "script" and self._in_script:
            self.scripts.append("".join(self._buf))
            self._in_script = False
            self._buf = []

    def handle_data(self, data):
        if self._in_script:
            self._buf.append(data)


def extract_script_dicts(html):
    """Return the dicts that can be parsed as Python literals from <script> bodies.

    Scripts are examined in document order. Any script whose content is not a
    valid Python literal evaluating to a dict is skipped.
    """
    collector = _ScriptCollector()
    collector.feed(html)
    collector.close()

    result = []
    for text in collector.scripts:
        try:
            value = ast.literal_eval(text.strip())
        except Exception:
            continue
        if isinstance(value, dict):
            result.append(value)
    return result


if __name__ == "__main__":
    print(extract_script_dicts('<script>{"a": 1}</script><script>var x = 2;</script>'))
    # [{'a': 1}]
```

The function uses `HTMLParser` rather than a regular expression, so it handles `<script>` tags with attributes, mixed-case tag names, and the raw-text nature of script bodies correctly. Each script body is passed to `ast.literal_eval` after stripping whitespace. Anything that fails to parse, or that parses to a non-dict value, is skipped.

