import re
import calendar
from datetime import date, timedelta

_WEEKDAYS = {'MON': 0, 'TUE': 1, 'WED': 2, 'THU': 3, 'FRI': 4, 'SAT': 5, 'SUN': 6}


def forecast_schedule(start_date, freq, sales):
    """
    Pair forecast sales figures with consecutive schedule dates.

    start_date : str, 'YYYY-MM-DD'
    freq       : 'month-end', 'quarter-end', or 'N-DAY' (e.g. '2-FRI'),
                 where N is 1-4 and DAY is MON..SUN (Nth weekday of each month)
    sales      : list of forecast sales figures

    Returns a list of (date 'YYYY-MM-DD', sales) tuples.
    Raises ValueError for an invalid start date or frequency code.
    """
    # Validate and parse the start date
    try:
        if not isinstance(start_date, str):
            raise ValueError
        start = date.fromisoformat(start_date) if re.fullmatch(r'\d{4}-\d{2}-\d{2}', start_date) else None
        if start is None:
            raise ValueError
    except ValueError:
        raise ValueError(f"Invalid start date: {start_date!r}; expected 'YYYY-MM-DD'")

    # Build the function that returns the matching date for a given (year, month)
    if freq == 'month-end':
        def candidate(y, m):
            return date(y, m, calendar.monthrange(y, m)[1])
    elif freq == 'quarter-end':
        def candidate(y, m):
            if m in (3, 6, 9, 12):
                return date(y, m, calendar.monthrange(y, m)[1])
            return None
    else:
        match = re.fullmatch(r'([1-4])-(MON|TUE|WED|THU|FRI|SAT|SUN)', str(freq))
        if not match:
            raise ValueError(f"Invalid frequency code: {freq!r}")
        n = int(match.group(1))
        wd = _WEEKDAYS[match.group(2)]

        def candidate(y, m):
            first = date(y, m, 1)
            offset = (wd - first.weekday()) % 7
            return first + timedelta(days=offset + 7 * (n - 1))

    # Walk month by month collecting one date per sales figure
    dates = []
    y, m = start.year, start.month
    while len(dates) < len(sales):
        c = candidate(y, m)
        if c is not None and c >= start:
            dates.append(c.isoformat())
        m += 1
        if m > 12:
            m = 1
            y += 1

    return list(zip(dates, sales))
```

Checking the example: `forecast_schedule('2021-01-01', '2-FRI', [272, 147, 217])` gives January's second Friday (2021-01-08), February's (2021-02-12), and March's (2021-03-12), matching the expected output.

```python
import re
from datetime import date, datetime, timedelta

_WEEKDAYS = {'MON': 0, 'TUE': 1, 'WED': 2, 'THU': 3, 'FRI': 4, 'SAT': 5, 'SUN': 6}
_WEEK_RE = re.compile(r'^([1-4])-(MON|TUE|WED|THU|FRI|SAT|SUN)$')


def _last_day_of_month(y, m):
    if m == 12:
        return date(y, 12, 31)
    return date(y, m + 1, 1) - timedelta(days=1)


def _nth_weekday(y, m, n, wd):
    first = date(y, m, 1)
    offset = (wd - first.weekday()) % 7
    return first + timedelta(days=offset + 7 * (n - 1))


def forecast_schedule(start_date, freq, sales):
    """Pair forecast sales with consecutive scheduled dates.

    start_date: 'YYYY-MM-DD'
    freq: 'month-end', 'quarter-end', or 'N-DAY' (e.g. '2-FRI')
    sales: list of forecast sales figures
    Returns a list of (date_string, sales) tuples.
    """
    try:
        if not isinstance(start_date, str):
            raise ValueError
        start = datetime.strptime(start_date, '%Y-%m-%d').date()
    except (ValueError, TypeError):
        raise ValueError(f"Invalid start date: {start_date!r}; expected 'YYYY-MM-DD'")

    if freq == 'month-end':
        def candidates(y, m):
            return [_last_day_of_month(y, m)]
    elif freq == 'quarter-end':
        def candidates(y, m):
            return [_last_day_of_month(y, m)] if m in (3, 6, 9, 12) else []
    else:
        match = _WEEK_RE.match(freq) if isinstance(freq, str) else None
        if not match:
            raise ValueError(f"Invalid frequency: {freq!r}")
        n = int(match.group(1))
        wd = _WEEKDAYS[match.group(2)]

        def candidates(y, m):
            return [_nth_weekday(y, m, n, wd)]

    sales = list(sales)
    if not sales:
        return []

    result = []
    y, m = start.year, start.month
    while len(result) < len(sales):
        for d in candidates(y, m):
            if d >= start and len(result) < len(sales):
                result.append(d)
        m += 1
        if m > 12:
            m = 1
            y += 1

    return [(d.strftime('%Y-%m-%d'), s) for d, s in zip(result, sales)]


if __name__ == '__main__':
    print(forecast_schedule('2021-01-01', '2-FRI', [272, 147, 217]))
    # [('2021-01-08', 272), ('2021-02-12', 147), ('2021-03-12', 217)]
```

The function walks forward month by month from the start date's month. For each month it computes the matching date(s): the last day for `month-end`, the last day only in March/June/September/December for `quarter-end`, or the Nth weekday for codes like `2-FRI`. Any candidate on or after `start_date` is paired with the next sales figure until the list is exhausted. An unparseable start date, or a frequency that isn't one of the supported forms, raises `ValueError`. An empty sales list returns an empty list.

```python
import calendar
import re
from datetime import date, datetime

_WEEKDAYS = {'MON': 0, 'TUE': 1, 'WED': 2, 'THU': 3, 'FRI': 4, 'SAT': 5, 'SUN': 6}
_NTH_WEEKDAY_RE = re.compile(r'^([1-4])-(MON|TUE|WED|THU|FRI|SAT|SUN)$')
_QUARTER_END_MONTHS = {3, 6, 9, 12}


def _parse_start_date(start_date):
    if not isinstance(start_date, str) or not re.fullmatch(r'\d{4}-\d{2}-\d{2}', start_date):
        raise ValueError(f"Invalid start date: {start_date!r}; expected 'YYYY-MM-DD'")
    try:
        return datetime.strptime(start_date, '%Y-%m-%d').date()
    except ValueError:
        raise ValueError(f"Invalid start date: {start_date!r}")


def _make_candidate_func(freq):
    """Return a function (year, month) -> date or None for the given frequency code."""
    if freq == 'month-end':
        def candidate(year, month):
            last = calendar.monthrange(year, month)[1]
            return date(year, month, last)
        return candidate

    if freq == 'quarter-end':
        def candidate(year, month):
            if month not in _QUARTER_END_MONTHS:
                return None
            last = calendar.monthrange(year, month)[1]
            return date(year, month, last)
        return candidate

    match = _NTH_WEEKDAY_RE.match(freq) if isinstance(freq, str) else None
    if match:
        nth = int(match.group(1))
        target_wd = _WEEKDAYS[match.group(2)]

        def candidate(year, month):
            first_wd = date(year, month, 1).weekday()
            first_occurrence = 1 + (target_wd - first_wd) % 7
            day = first_occurrence + 7 * (nth - 1)
            return date(year, month, day)
        return candidate

    raise ValueError(
        f"Invalid frequency: {freq!r}; expected 'month-end', 'quarter-end', "
        "or a code like '2-FRI'"
    )


def forecast_schedule(start_date, freq, sales):
    """
    Pair each forecast sales figure with a consecutive schedule date.

    start_date: 'YYYY-MM-DD'
    freq: 'month-end', 'quarter-end', or 'N-DAY' (e.g. '2-FRI', week 1-4, DAY in MON..SUN)
    sales: list of forecast sales figures

    Returns a list of (date_string 'YYYY-MM-DD', sales) tuples in order.
    """
    start = _parse_start_date(start_date)
    candidate = _make_candidate_func(freq)

    n = len(sales)
    dates = []
    year, month = start.year, start.month

    while len(dates) < n:
        d = candidate(year, month)
        if d is not None and d >= start:
            dates.append(d)
        month += 1
        if month > 12:
            month = 1
            year += 1

    return [(d.isoformat(), s) for d, s in zip(dates, sales)]


if __name__ == '__main__':
    print(forecast_schedule('2021-01-01', '2-FRI', [272, 147, 217]))
    # [('2021-01-08', 272), ('2021-02-12', 147), ('2021-03-12', 217)]
    print(forecast_schedule('2021-01-01', 'quarter-end', [1, 2, 3, 4]))
    # [('2021-03-31', 1), ('2021-06-30', 2), ('2021-09-30', 3), ('2021-12-31', 4)]
    print(forecast_schedule('2021-01-31', 'month-end', [10, 20]))
    # [('2021-01-31', 10), ('2021-02-28', 20)]
```

**How it works**

- **Start date validation:** The string must match `YYYY-MM-DD` and be a real calendar date; otherwise a `ValueError` is raised.
- **Frequency handling:** Each frequency is turned into a function that returns the matching date for a given year and month, or `None` if that month doesn't qualify:
  - `month-end`: the last day of the month.
  - `quarter-end`: the last day of March, June, September, or December only.
  - `N-DAY`: the Nth occurrence of that weekday. The first occurrence is `1 + (target - first_weekday) % 7`, and each later one is 7 days further on. Since N is 1 to 4, this always falls within the month.
  - Anything else raises a `ValueError`.
- **Scheduling:** Starting from the start date's month, the function walks forward month by month, keeping only candidate dates on or after `start_date`, until it has one date per sales figure.

