import csv
import io
from collections import Counter


def sales_report(csv_text):
    if not isinstance(csv_text, str):
        raise ValueError("csv_text must be a string")

    reader = csv.DictReader(io.StringIO(csv_text))
    if reader.fieldnames is not None:
        reader.fieldnames = [name.strip() for name in reader.fieldnames]

    def parse_number(value):
        value = value.strip()
        try:
            return int(value)
        except ValueError:
            return float(value)

    seen_customers = set()
    total_sales = 0
    category_counts = Counter()

    for row in reader:
        customer = row["Customer"].strip()
        if customer in seen_customers:
            continue
        seen_customers.add(customer)

        total_sales += parse_number(row["Sales"])
        category_counts[row["Category"].strip()] += 1

    if category_counts:
        # Highest count first; on ties, alphabetically first category.
        most_popular = min(category_counts.items(), key=lambda item: (-item[1], item[0]))[0]
    else:
        most_popular = None

    return {
        "Total Sales": total_sales,
        "Most Popular Category": most_popular,
    }
