import io
from collections import Counter


def _parse_number(text):
    """Parse a sales value, preferring int and falling back to float."""
    text = text.strip()
    try:
        return int(text)
    except ValueError:
        return float(text)


def sales_report(csv_text):
    if not isinstance(csv_text, str):
        raise ValueError("csv_text must be a string")

