        raise ValueError("CSV text has no header row")

    # Map stripped header names to their original keys so extra or
    # reordered columns are handled correctly.
    header_map = {name.strip(): name for name in reader.fieldnames if name is not None}
    missing = [col for col in ("Customer", "Category", "Sales") if col not in header_map]
    if missing:
        raise ValueError(f"Missing required column(s): {', '.join(missing)}")

    customer_key = header_map["Customer"]
    category_key = header_map["Category"]
    sales_key = header_map["Sales"]

