        category = (row.get(category_key) or "").strip()
        category_counts[category] += 1

    if category_counts:
        max_count = max(category_counts.values())
        most_popular = min(c for c, n in category_counts.items() if n == max_count)
    else:
        most_popular = None

    return {
        "Total Sales": total_sales,
        "Most Popular Category": most_popular,
    }


