import math
from numbers import Real


def column_covariance(columns):
    """
    Return the sample covariance matrix of a table.

    `columns` maps column names to equal-length lists of numbers (at least
    two rows). The result is a nested dict where result[a][b] is the
    covariance between columns a and b, normalised by n - 1.

    Raises:
        ValueError: if the table has no columns, no rows, fewer than two
            rows, or columns of unequal length.
        TypeError: if any column contains a non-numeric value.
    """
    if not columns:
        raise ValueError("table has no columns")

    data = {}
    n = None
    for name, values in columns.items():
        values = list(values)
        for v in values:
            # bool is a subclass of int, but is not meaningful as a number here
            if isinstance(v, bool) or not isinstance(v, Real):
                raise TypeError(
                    f"column {name!r} contains non-numeric value {v!r}"
                )
        if n is None:
            n = len(values)
        elif len(values) != n:
            raise ValueError("all columns must have the same length")
        data[name] = [float(v) for v in values]

    if n == 0:
        raise ValueError("table has no rows")
    if n < 2:
        raise ValueError("at least two rows are required for sample covariance")

    means = {name: math.fsum(vals) / n for name, vals in data.items()}
    devs = {
        name: [v - means[name] for v in vals] for name, vals in data.items()
    }

    result = {}
    for a in data:
        result[a] = {}
        for b in data:
            s = math.fsum(x * y for x, y in zip(devs[a], devs[b]))
            result[a][b] = s / (n - 1)
    return result
```

Example usage:

```python
>>> column_covariance({'x': [1, 2, 4], 'y': [3, 1, 2]})
{'x': {'x': 2.333..., 'y': -0.5}, 'y': {'x': -0.5, 'y': 1.0}}
```

The function centres each column by its mean, then computes the sum of products of deviations for every pair of columns and divides by n − 1. It uses `math.fsum` for more accurate summation. The result keys follow the input column order.

