import math
from numbers import Real


def column_covariance(columns):
    """
    Return the sample covariance matrix (normalised by n - 1) of a table.

    `columns` maps column names to equal-length lists of numbers with at
    least two rows. The result is a nested dict where result[a][b] is the
    covariance between columns a and b.

    Raises:
        ValueError: if the table has no columns, no rows, unequal column
            lengths, or fewer than two rows.
        TypeError: if any column contains a non-numeric value.
    """
    if not isinstance(columns, dict) or len(columns) == 0:
        raise ValueError("table has no columns")

    # Materialise and type-check every column first.
    data = {}
    for name, values in columns.items():
        values = list(values)
        for v in values:
            if isinstance(v, bool) or not isinstance(v, Real):
                raise TypeError(
                    f"column {name!r} contains non-numeric value {v!r}"
                )
        data[name] = values

    lengths = {len(v) for v in data.values()}
    if len(lengths) != 1:
        raise ValueError("all columns must have the same length")

    n = lengths.pop()
    if n == 0:
        raise ValueError("table has no rows")
    if n < 2:
        raise ValueError("at least two rows are required for sample covariance")

    names = list(data)
    means = {name: math.fsum(data[name]) / n for name in names}
    devs = {name: [x - means[name] for x in data[name]] for name in names}

    result = {a: {} for a in names}
    for i, a in enumerate(names):
        for b in names[i:]:
            cov = math.fsum(p * q for p, q in zip(devs[a], devs[b])) / (n - 1)
            result[a][b] = cov
            result[b][a] = cov

    return result
```

Example usage:

```python
>>> column_covariance({'x': [1, 2, 4], 'y': [3, 1, 2]})
{'x': {'x': 2.3333333333333335, 'y': -0.5}, 'y': {'x': -0.5, 'y': 1.0}}
```

Notes on the implementation:
- Each column is checked for numeric values before anything else. `bool` is rejected even though it subclasses `int`, since it is not really a numeric measurement.
- Column lengths must match, and the table must have at least two rows, because dividing by n - 1 is undefined otherwise.
- Each covariance is computed once and mirrored, so the matrix is exactly symmetric.
- `math.fsum` is used for the sums to reduce floating-point error.

