import random


def cluster_point_indices(points, n_clusters, n_init=10, max_iter=300, seed=0):
    """
    Group points into n_clusters clusters with k-means and return the
    point indices in each cluster.

    Args:
        points: list of points, each a list of numbers with the same dimension.
        n_clusters: number of clusters to form (1 <= n_clusters <= len(points)).
        n_init: number of k-means++ restarts; the lowest-inertia run is kept.
        max_iter: maximum Lloyd iterations per run.
        seed: random seed, so results are reproducible.

    Returns:
        A list of clusters. Each cluster is a list of point indices in
        ascending order, and the clusters are ordered by their smallest index.
    """
    n = len(points)
    if n == 0:
        return []
    if not (1 <= n_clusters <= n):
        raise ValueError("n_clusters must be between 1 and the number of points")

    k = n_clusters
    rng = random.Random(seed)

    def dist2(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))

    def init_centers():
        # k-means++ seeding
        centers = [list(points[rng.randrange(n)])]
        while len(centers) < k:
            d = [min(dist2(p, c) for c in centers) for p in points]
            total = sum(d)
            if total == 0:
                # All points coincide with existing centers; pick any point.
                idx = rng.randrange(n)
            else:
                r = rng.uniform(0, total)
                acc = 0.0
                idx = n - 1
                for i, di in enumerate(d):
                    acc += di
                    if acc >= r:
                        idx = i
                        break
            centers.append(list(points[idx]))
        return centers

    def lloyd(centers):
        labels = None
        for _ in range(max_iter):
            new_labels = [
                min(range(k), key=lambda j: dist2(p, centers[j])) for p in points
            ]
            if new_labels == labels:
                break
            labels = new_labels

            for j in range(k):
                members = [points[i] for i in range(n) if labels[i] == j]
                if members:
                    centers[j] = [sum(col) / len(members) for col in zip(*members)]
                else:
                    # Re-seat an empty cluster at the point farthest from its center.
                    far = max(
                        range(n),
                        key=lambda i: dist2(points[i], centers[labels[i]]),
                    )
                    centers[j] = list(points[far])

        inertia = sum(dist2(points[i], centers[labels[i]]) for i in range(n))
        return labels, inertia

    best_labels, best_inertia = None, float("inf")
    for _ in range(n_init):
        labels, inertia = lloyd(init_centers())
        if inertia < best_inertia:
            best_labels, best_inertia = labels, inertia

    groups = {}
    for i, lab in enumerate(best_labels):
        groups.setdefault(lab, []).append(i)

    # Indices are already ascending within each group; order groups by smallest index.
    return sorted(groups.values(), key=lambda g: g[0])


if __name__ == "__main__":
    print(cluster_point_indices([[1, 1], [1.1, 1.1], [5, 5], [5.1, 5.1]], 2))
    # [[0, 1], [2, 3]]
```

The function runs k-means++ initialization followed by Lloyd's iterations, repeats this `n_init` times with different starts, and keeps the run with the lowest within-cluster sum of squares. Empty clusters are re-seeded at the point farthest from its center. The final groups are built from the labels, so each cluster's indices are ascending and the clusters are sorted by their first index.

```python
import random


def cluster_point_indices(points, n_clusters, max_iter=100, n_init=10, seed=0):
    """
    Group points into n_clusters clusters with k-means and return the
    point indices in each cluster.

    Returns a list of clusters. Each cluster is a list of point indices in
    ascending order, and the clusters are ordered by their smallest index.

    Example:
        cluster_point_indices([[1, 1], [1.1, 1.1], [5, 5], [5.1, 5.1]], 2)
        -> [[0, 1], [2, 3]]
    """
    k = int(n_clusters)
    n = len(points)

    if k < 1:
        raise ValueError("n_clusters must be at least 1")
    if n == 0:
        return []
    if k > n:
        raise ValueError("n_clusters cannot exceed the number of points")

    pts = [[float(x) for x in p] for p in points]
    rng = random.Random(seed)

    def sqdist(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))

    def kmeans_pp_init():
        # k-means++ seeding: spread initial centers out using squared distances.
        centers = [list(pts[rng.randrange(n)])]
        while len(centers) < k:
            d2 = [min(sqdist(p, c) for c in centers) for p in pts]
            total = sum(d2)
            if total == 0:
                idx = rng.randrange(n)
            else:
                r = rng.uniform(0, total)
                acc = 0.0
                idx = n - 1
                for i, d in enumerate(d2):
                    acc += d
                    if acc >= r:
                        idx = i
                        break
            centers.append(list(pts[idx]))
        return centers

    def lloyd(centers):
        labels = None
        for _ in range(max_iter):
            new_labels = [
                min(range(k), key=lambda j: sqdist(p, centers[j])) for p in pts
            ]
            if new_labels == labels:
                break
            labels = new_labels

            for j in range(k):
                members = [pts[i] for i in range(n) if labels[i] == j]
                if members:
                    centers[j] = [sum(col) / len(members) for col in zip(*members)]
                else:
                    # Empty cluster: move its center to the point farthest
                    # from its currently assigned center.
                    far = max(range(n), key=lambda i: sqdist(pts[i], centers[labels[i]]))
                    centers[j] = list(pts[far])

        inertia = sum(sqdist(pts[i], centers[labels[i]]) for i in range(n))
        return labels, inertia

    best_labels, best_inertia = None, float("inf")
    for _ in range(n_init):
        labels, inertia = lloyd(kmeans_pp_init())
        if inertia < best_inertia:
            best_labels, best_inertia = labels, inertia

    groups = {}
    for i, label in enumerate(best_labels):
        groups.setdefault(label, []).append(i)

    # Indices are appended in increasing order, so each group is already sorted.
    clusters = sorted(groups.values(), key=lambda g: g[0])
    return clusters


if __name__ == "__main__":
    print(cluster_point_indices([[1, 1], [1.1, 1.1], [5, 5], [5.1, 5.1]], 2))
    # [[0, 1], [2, 3]]
```

The function runs Lloyd's algorithm with k-means++ initialization and `n_init` restarts, keeping the solution with the lowest inertia. It is seeded, so repeated calls give the same result. Each cluster's indices are built in ascending order, and the clusters are sorted by their first index.

One caveat: if the data contains many exact duplicate points, some clusters can end up empty and be dropped, so the result may contain fewer than `n_clusters` lists.

