def summarize_student_records(data):
    for key in ('Name', 'Age', 'Score'):
        if key not in data:
            raise ValueError(f"Missing key: {key}")

    names = data['Name']
    ages = data['Age']
    scores = data['Score']

    # Build records; zip stops at the shortest list.
    records = [[name, age, score] for name, age, score in zip(names, ages, scores)]

    # Sort by name, then age. Python's sort is stable, so ties keep original order.
    sorted_records = sorted(records, key=lambda r: (r[0], r[1]))

    # Average score per name.
    totals = {}
    counts = {}
    for name, _, score in records:
        totals[name] = totals.get(name, 0) + score
        counts[name] = counts.get(name, 0) + 1
    averages = {name: totals[name] / counts[name] for name in totals}

    # Most common age; on ties, the age that appears first in the input wins.
    most_common_age = None
    age_counts = {}
    best_count = 0
    for _, age, _ in records:
        age_counts[age] = age_counts.get(age, 0) + 1
        if age_counts[age] > best_count:
            best_count = age_counts[age]
            most_common_age = age

    return (sorted_records, averages, most_common_age)
