        counts[n] = counts.get(n, 0) + 1
    averages = {n: totals[n] / counts[n] for n in totals}

    # Most common age, or None if there are no records.
    if records:
        most_common_age = Counter(ages[:len(records)]).most_common(1)[0][0]
    else:
        most_common_age = None

    return (sorted_records, averages, most_common_age)
