import csv
import io
import math


def _parse_number(text):
    """Return int or finite float for numeric text, otherwise None."""
    try:
        return int(text)
    except ValueError:
        pass
    try:
        value = float(text)
    except ValueError:
        return None
    return value if math.isfinite(value) else None


def sort_csv_rows(csv_text, sort_key):
    reader = csv.DictReader(io.StringIO(csv_text))
    fieldnames = reader.fieldnames or []

    if sort_key not in fieldnames:
        raise ValueError(f"Column {sort_key!r} does not exist")

    # Normalize short rows (missing fields become empty strings).
    rows = [
        {col: ('' if row.get(col) is None else row.get(col)) for col in fieldnames}
        for row in reader
    ]

    # Convert columns whose values are all numeric.
    for col in fieldnames:
        parsed = [_parse_number(row[col]) for row in rows]
        if rows and all(value is not None for value in parsed):
            for row, value in zip(rows, parsed):
                row[col] = value

    # sorted() is stable, so rows with equal keys keep their original order.
    return sorted(rows, key=lambda row: row[sort_key])
```

Example:

```python
result = sort_csv_rows('title,x\nBook C,10\nBook A,9\nBook B,100\n', 'x')
print(result)
# [{'title': 'Book A', 'x': 9}, {'title': 'Book C', 'x': 10}, {'title': 'Book B', 'x': 100}]
```

Notes on the behavior:
- A column is treated as numeric only if every value in it parses as a finite number. Values like `nan` or `inf` are not treated as numeric, so such columns stay as strings.
- Integers are kept as `int` and other numbers become `float`.
- Missing trailing fields in short rows become empty strings, which makes their column non-numeric.
- Python's `sorted` is stable, so ties keep their original order.

