import json
import math


def numeric_correlation_from_json(json_text):
    """
    Parse a JSON object mapping column names to equal-length lists of values and
    return the pairwise Pearson correlation matrix of its numeric columns.

    A column is numeric if every value in it is an int or float (booleans are
    not treated as numbers). Non-numeric columns are ignored.

    Returns a dict: {col_i: {col_j: correlation}} over the numeric columns.
    A correlation involving a constant column is undefined and is returned as NaN.

    Raises ValueError if the text is not valid JSON, if the data is empty, if
    the top-level value is not an object, or if the columns have unequal lengths.
    """
    try:
        data = json.loads(json_text)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError(f"Invalid JSON: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError("JSON must be an object mapping column names to lists")
    if not data:
        raise ValueError("Data is empty")

    lengths = set()
    for name, values in data.items():
        if not isinstance(values, list):
            raise ValueError(f"Column {name!r} is not a list")
        lengths.add(len(values))

    if lengths == {0}:
        raise ValueError("Data is empty")
    if 0 in lengths:
        raise ValueError("Data is empty: some columns have no values")
    if len(lengths) > 1:
        raise ValueError("All columns must have equal length")

    def is_number(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    numeric = {
        name: [float(v) for v in values]
        for name, values in data.items()
        if all(is_number(v) for v in values)
    }

    def pearson(x, y):
        n = len(x)
        mx = sum(x) / n
        my = sum(y) / n
        sxx = sum((a - mx) ** 2 for a in x)
        syy = sum((b - my) ** 2 for b in y)
        sxy = sum((a - mx) * (b - my) for a, b in zip(x, y))
        if sxx == 0 or syy == 0:
            return math.nan
        r = sxy / math.sqrt(sxx * syy)
        return max(-1.0, min(1.0, r))

    names = list(numeric)
    result = {}
    for i in names:
        result[i] = {}
        for j in names:
            if i == j:
                # Diagonal is exactly 1 unless the column is constant (undefined).
                xi = numeric[i]
                result[i][j] = 1.0 if len(set(xi)) > 1 else math.nan
            else:
                result[i][j] = pearson(numeric[i], numeric[j])
    return result
```

