import json
import math


def numeric_correlation_from_json(json_text):
    """
    Parse a JSON object mapping column names to equal-length lists of values,
    and return the pairwise Pearson correlation matrix of the numeric columns.

    A column is numeric if it is a non-empty list in which every value is an
    int or float (booleans, strings, nulls, and nested structures disqualify it).
    Non-numeric columns are ignored.

    Returns a dict: {col_i: {col_j: correlation}}.
    Correlations involving a constant (zero-variance) column are NaN.

    Raises ValueError if the text is not valid JSON, the data is empty, the
    top-level value is not an object, or the columns have unequal lengths.
    """
    try:
        data = json.loads(json_text)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError(f"Invalid JSON: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError("JSON must contain an object mapping column names to lists")
    if len(data) == 0:
        raise ValueError("Data is empty")

    lengths = set()
    for col, values in data.items():
        if isinstance(values, list):
            lengths.add(len(values))
    if len(lengths) > 1:
        raise ValueError("All columns must have equal length")
    if lengths and 0 in lengths:
        raise ValueError("Data is empty")

    def is_numeric_value(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    numeric = {}
    for col, values in data.items():
        if isinstance(values, list) and values and all(is_numeric_value(v) for v in values):
            numeric[col] = [float(v) for v in values]

    result = {}
    means = {c: sum(v) / len(v) for c, v in numeric.items()}
    devs = {c: [x - means[c] for x in v] for c, v in numeric.items()}
    ss = {c: sum(d * d for d in devs[c]) for c in numeric}

    for ci in numeric:
        result[ci] = {}
        for cj in numeric:
            if ci == cj:
                result[ci][cj] = 1.0 if ss[ci] > 0 else float("nan")
                continue
            denom = math.sqrt(ss[ci] * ss[cj])
            if denom == 0:
                result[ci][cj] = float("nan")
                continue
            sxy = sum(a * b for a, b in zip(devs[ci], devs[cj]))
            r = sxy / denom
            result[ci][cj] = max(-1.0, min(1.0, r))

    return result
