```python
import json
import math


def _is_numeric(value):
    """True for int/float values (booleans are excluded)."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _pearson(xs, ys):
    """Pearson correlation of two equal-length numeric sequences.

    Returns NaN when either sequence has zero variance, since the
    correlation is undefined in that case.
    """
    n = len(xs)
    mean_x = sum(xs) / n
    mean_y = sum(ys) / n
    sxy = sum((x - mean_x) * (y - mean_y) for x, y in zip(xs, ys))
    sxx = sum((x - mean_x) ** 2 for x in xs)
    syy = sum((y - mean_y) ** 2 for y in ys)
    if sxx == 0 or syy == 0:
        return float("nan")
    return sxy / math.sqrt(sxx * syy)


def numeric_correlation_from_json(json_text):
    """Return the pairwise Pearson correlation matrix of the numeric columns
    in a JSON object mapping column names to equal-length lists of values.

    Non-numeric columns are ignored. The result is a dict of dicts:
    result[col_i][col_j] is the correlation between col_i and col_j.

    Raises ValueError if the text is not valid JSON, is not a JSON object,
    or the data is empty.
    """
    try:
        data = json.loads(json_text)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError(f"invalid JSON: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError("JSON must be an object mapping column names to lists")
    if not data:
        raise ValueError("data is empty")

    lengths = set()
    for name, values in data.items():
        if not isinstance(values, list):
            raise ValueError(f"column {name!r} is not a list")
        lengths.add(len(values))
    if len(lengths) != 1:
        raise ValueError("all columns must have equal length")
    n = lengths.pop()
    if n == 0:
        raise ValueError("data is empty")

    # Keep only columns whose values are all numeric.
    numeric_cols = {
        name: [float(v) for v in values]
        for name, values in data.items()
        if all(_is_numeric(v) for v in values)
    }

    result = {}
    for name_i, xs in numeric_cols.items():
        row = {}
        for name_j, ys in numeric_cols.items():
            if name_i == name_j:
                # Self-correlation is 1 unless the column is constant.
                mean = sum(xs) / n
                constant = all(x == xs[0] for x in xs)
                row[name_j] = float("nan") if constant else 1.0
            else:
                row[name_j] = _pearson(xs, ys)
        result[name_i] = row
    return result
