import csv
import io
import math


def _cube_root(x):
    """Real cube root of a float, exact for perfect cubes (e.g. 64 -> 4.0)."""
    if x == 0:
        return 0.0
    a = abs(x)
    r = a ** (1.0 / 3.0)
    if math.isfinite(r):
        n = round(r)
        if n ** 3 == a:
            r = float(n)
        else:
            # One Newton step to tighten the floating-point estimate.
            r = r - (r ** 3 - a) / (3.0 * r * r)
    return r if x > 0 else -r


def csv_cube_roots(csv_text, columns):
    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        header = []

    data = {name: [] for name in header}

    for row_num, row in enumerate(reader, start=2):
        if not row:  # skip completely blank lines
            continue
        if len(row) != len(header):
            raise ValueError(
                f"Row {row_num} has {len(row)} fields; expected {len(header)}"
            )
        for name, field in zip(header, row):
            try:
                value = float(field)
            except ValueError:
                raise ValueError(
                    f"Non-numeric value {field!r} in column {name!r} at row {row_num}"
                ) from None
            data[name].append(value)

    for col in columns:
        if col not in data:
            raise KeyError(f"Column {col!r} not found in CSV")

    cube_roots = {col: [_cube_root(v) for v in data[col]] for col in columns}

    return data, cube_roots
