import csv
import io
import math


def _cube_root(x):
    """Real cube root that keeps negative signs and returns exact results
    for perfect cubes (e.g. 64 -> 4.0, -64 -> -4.0)."""
    if math.isnan(x) or math.isinf(x):
        return x
    magnitude = abs(x)
    root = magnitude ** (1.0 / 3.0)
    candidate = round(root)
    if candidate ** 3 == magnitude:
        root = float(candidate)
    return -root if x < 0 else root


def csv_cube_roots(csv_text, columns):
    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        header = []

    data = {name: [] for name in header}

    for row in reader:
        if not row:
            continue
        for i, name in enumerate(header):
            raw = row[i] if i < len(row) else ""
            # float() raises ValueError for non-numeric text
            data[name].append(float(raw))

    cube_roots = {}
    for col in columns:
        if col not in data:
            raise KeyError(f"Column not found in CSV: {col!r}")
        cube_roots[col] = [_cube_root(v) for v in data[col]]

    return data, cube_roots
```

