import csv
import io
import math


def correlation_matrix_from_csv(csv_text):
    """
    Parse CSV text (first line is a header, all other values numeric) and
    return the pairwise Pearson correlation matrix of the columns as a
    dict of dicts: result[a][b] is the correlation between columns a and b.
    """
    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if any(cell.strip() for cell in row)]
    if not rows:
        return {}

    header = [name for name in rows[0]]
    n_cols = len(header)

    # Collect values column by column as floats.
    columns = [[] for _ in range(n_cols)]
    for row in rows[1:]:
        if len(row) != n_cols:
            raise ValueError(
                f"Row has {len(row)} fields, expected {n_cols}: {row!r}"
            )
        for j, cell in enumerate(row):
            columns[j].append(float(cell))

    n = len(columns[0]) if columns else 0

    # Precompute means.
    means = []
    for col in columns:
        means.append(sum(col) / n if n else float("nan"))

    # Precompute centered values and sum of squares.
    centered = [[x - m for x in col] for col, m in zip(columns, means)]
    ss = [sum(c * c for c in cc) for cc in centered]

    def corr(i, j):
        if i == j:
            return 1.0 if ss[i] > 0 else float("nan")
        denom = math.sqrt(ss[i] * ss[j])
        if denom == 0:
            return float("nan")
        sxy = sum(a * b for a, b in zip(centered[i], centered[j]))
        return sxy / denom

    result = {}
    for i, a in enumerate(header):
        result[a] = {}
        for j, b in enumerate(header):
            result[a][b] = corr(i, j)
    return result
```

Example usage:

```python
>>> correlation_matrix_from_csv('a,b\n1,2\n2,4\n3,5\n')
{'a': {'a': 1.0, 'b': 0.9819805060619657}, 'b': {'a': 0.9819805060619657, 'b': 1.0}}
```

Notes:
- The diagonal is set to exactly `1.0` for non-constant columns, avoiding floating-point drift.
- A constant column has undefined correlation, so it yields `nan` in its row and column.
- Means are subtracted before multiplying (two-pass method), which is more numerically stable than the one-pass `E[xy] - E[x]E[y]` formula.

```python
import csv
import io
import math


def correlation_matrix_from_csv(csv_text):
    """
    Parse CSV text (first line is a header, all other values numeric) and
    return the pairwise Pearson correlation matrix of its columns as a
    dict of dicts: result[a][b] is the correlation between columns a and b.

    If a column has zero variance, its correlations are NaN (the diagonal
    entry for such a column is also NaN, since correlation is undefined).
    """
    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if any(cell.strip() for cell in row)]
    if not rows:
        return {}

    header = [name.strip() for name in rows[0]]
    data_rows = rows[1:]

    # Collect each column's values as floats.
    columns = {name: [] for name in header}
    for row in data_rows:
        for i, name in enumerate(header):
            columns[name].append(float(row[i]))

    n = len(data_rows)

    def mean(xs):
        return sum(xs) / len(xs)

    means = {name: (mean(columns[name]) if n else float('nan')) for name in header}

    def pearson(x, y, mx, my):
        if n == 0:
            return float('nan')
        sxy = sum((a - mx) * (b - my) for a, b in zip(x, y))
        sxx = sum((a - mx) ** 2 for a in x)
        syy = sum((b - my) ** 2 for b in y)
        if sxx == 0 or syy == 0:
            return float('nan')
        return sxy / math.sqrt(sxx * syy)

    result = {a: {} for a in header}
    for a in header:
        for b in header:
            if a == b:
                # Self-correlation is exactly 1 whenever it is defined.
                x = columns[a]
                varies = n > 0 and any(v != x[0] for v in x)
                result[a][b] = 1.0 if varies else float('nan')
            else:
                result[a][b] = pearson(columns[a], columns[b], means[a], means[b])
    return result
```

