import csv
import io
import math


def correlation_matrix_from_csv(csv_text):
    """
    Parse CSV text (first line is a header, all other values numeric) and
    return the pairwise Pearson correlation matrix of its columns as a
    dict of dicts: result[a][b] is the correlation between columns a and b.

    A correlation involving a column with zero variance is returned as NaN.
    """
    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row and any(cell.strip() for cell in row)]
    if not rows:
        return {}

    header = [name.strip() for name in rows[0]]
    data_rows = rows[1:]

    # Collect each column as a list of floats.
    columns = {name: [] for name in header}
    for row in data_rows:
        for name, cell in zip(header, row):
            columns[name].append(float(cell))

    def pearson(x, y):
        n = len(x)
        if n == 0 or len(y) != n:
            return float('nan')
        mean_x = sum(x) / n
        mean_y = sum(y) / n
        dx = [v - mean_x for v in x]
        dy = [v - mean_y for v in y]
        sxy = sum(a * b for a, b in zip(dx, dy))
        sxx = sum(a * a for a in dx)
        syy = sum(b * b for b in dy)
        denom = math.sqrt(sxx * syy)
        if denom == 0:
            return float('nan')
        r = sxy / denom
        # Guard against tiny floating-point overshoot.
        return max(-1.0, min(1.0, r))

    result = {a: {} for a in header}
    for i, a in enumerate(header):
        for b in header[i:]:
            if a == b:
                value = pearson(columns[a], columns[a])
                if not math.isnan(value):
                    value = 1.0
            else:
                value = pearson(columns[a], columns[b])
            result[a][b] = value
            result[b][a] = value

    return result
```

