import re

def document_term_matrix(texts, stop_words):
    # A word is a maximal run of letters or digits. Underscores are separators,
    # so [^\W_] (word characters minus underscore) matches exactly those runs.
    token_pattern = re.compile(r'[^\W_]+')
    stops = {w.lower() for w in stop_words}

    tokenized = []
    for text in texts:
        words = [w for w in token_pattern.findall(text.lower()) if w not in stops]
        tokenized.append(words)

    terms = sorted({w for words in tokenized for w in words})
    index = {term: i for i, term in enumerate(terms)}

    counts = []
    for words in tokenized:
        row = [0] * len(terms)
        for w in words:
            row[index[w]] += 1
        counts.append(row)

    return (terms, counts)


if __name__ == "__main__":
    print(document_term_matrix(['Hello, world!', 'The world is big.'], ['the', 'is']))
    # (['big', 'hello', 'world'], [[0, 1, 1], [1, 0, 1]])
```

The function lowercases each text and splits it on runs of non-alphanumeric characters, with underscores treated as separators. Stop words are lowercased too, so matching is case-insensitive. It then collects the sorted distinct terms and fills one count row per document in that term order.

