def normalize_columns(data):
    """
    Rescale each column of `data` independently to the range [0, 1].

    Args:
        data: dict mapping column names to equal-length lists of numbers.

    Returns:
        dict with the same keys, each mapped to a list of floats in the
        original order. A column's minimum becomes 0.0 and its maximum
        becomes 1.0. A constant column becomes all 0.0.

    Raises:
        ValueError: if `data` is empty, if a column is empty, or if any
            column contains a non-numeric value (booleans are rejected).
    """
    if not data:
        raise ValueError("data must not be empty")

    def is_number(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    result = {}
    for name, column in data.items():
        values = list(column)
        if not values:
            raise ValueError(f"column {name!r} is empty")
        for v in values:
            if not is_number(v):
                raise ValueError(
                    f"column {name!r} contains non-numeric value {v!r}"
                )

        lo = min(values)
        hi = max(values)
        span = hi - lo
        if span == 0:
            result[name] = [0.0] * len(values)
        else:
            result[name] = [(v - lo) / span for v in values]

    return result


if __name__ == "__main__":
    print(normalize_columns({'a': [1, 2, 3], 'b': [10, 10, 10]}))
    # {'a': [0.0, 0.5, 1.0], 'b': [0.0, 0.0, 0.0]}
```

