from numbers import Real


def normalize_columns(data):
    """
    Rescale each column of `data` independently to the range [0, 1].

    Parameters
    ----------
    data : dict
        Maps column names to equal-length lists of numbers.

    Returns
    -------
    dict
        Same keys, each mapped to a list of rescaled floats in original order.
        A column whose values are all equal becomes all 0.0.

    Raises
    ------
    ValueError
        If `data` is empty, or if any column contains non-numeric values
        (booleans, strings, None, NaN, and infinities are rejected too).
    """
    if not data:
        raise ValueError("data must be a non-empty dict")

    result = {}
    for name, column in data.items():
        try:
            values = list(column)
        except TypeError:
            raise ValueError(f"column {name!r} is not a list of numbers")

        for v in values:
            if isinstance(v, bool) or not isinstance(v, Real):
                raise ValueError(
                    f"column {name!r} contains non-numeric value {v!r}"
                )
            if isinstance(v, float) and not math.isfinite(v):
                raise ValueError(
                    f"column {name!r} contains non-finite value {v!r}"
                )

        if not values:
            result[name] = []
            continue

        lo = float(min(values))
        hi = float(max(values))

        if lo == hi:
            result[name] = [0.0] * len(values)
        else:
            span = hi - lo
            result[name] = [(float(v) - lo) / span for v in values]

    return result


if __name__ == "__main__":
    print(normalize_columns({'a': [1, 2, 3], 'b': [10, 10, 10]}))
    # {'a': [0.0, 0.5, 1.0], 'b': [0.0, 0.0, 0.0]}
