import numbers


def normalize_columns(data):
    """
    Rescale each column of `data` independently to the range [0, 1].

    Args:
        data: dict mapping column names to equal-length lists of numbers.

    Returns:
        dict with the same keys, each mapped to a list of floats in the
        original order. A column's minimum becomes 0.0 and its maximum
        becomes 1.0. A column whose values are all equal becomes all zeros.

    Raises:
        ValueError: if `data` is empty or any column contains non-numeric values.
    """
    if not data:
        raise ValueError("data must be a non-empty dict")

    result = {}
    for name, values in data.items():
        values = list(values)

        for v in values:
            # bool is a subclass of int, but it is not a meaningful numeric value here
            if isinstance(v, bool) or not isinstance(v, numbers.Real):
                raise ValueError(
                    f"column {name!r} contains non-numeric value: {v!r}"
                )

        if not values:
            result[name] = []
            continue

        lo = min(values)
        hi = max(values)
        span = hi - lo

        if span == 0:
            result[name] = [0.0] * len(values)
        else:
            result[name] = [float(v - lo) / float(span) for v in values]

    return result


if __name__ == "__main__":
