from html.parser import HTMLParser


class _LinkExtractor(HTMLParser):
    def __init__(self):
        # convert_charrefs=True makes the parser decode entities like &amp; and &#39;
        super().__init__(convert_charrefs=True)
        self.links = []   # one entry per <a> start tag: [text_parts, href]
        self.open = []    # indices into self.links for anchors not yet closed

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            href = None
            for name, value in attrs:
                if name == 'href':  # first href wins, as in browsers
                    href = value if value is not None else ''
                    break
            self.links.append(([], href))
            self.open.append(len(self.links) - 1)

    def handle_endtag(self, tag):
        if tag == 'a' and self.open:
            self.open.pop()

    def handle_data(self, data):
        # Text belongs to every anchor currently open, including text
        # inside nested tags such as <b> within an <a>.
        for i in self.open:
            self.links[i][0].append(data)


def extract_links(html):
    """Return a list of (text, href) tuples for every <a> tag in document order.

    text is the anchor's inner text with nested tags removed and entities
    decoded; href is the href attribute value, or None if absent.
    """
    parser = _LinkExtractor()
    parser.feed(html)
    parser.close()
    return [(''.join(parts), href) for parts, href in parser.links]


if __name__ == '__main__':
    sample = '<p><a href="/home">Home</a> and <a href="https://example.com">Example <b>site</b></a></p>'
    print(extract_links(sample))
    # [('Home', '/home'), ('Example site', 'https://example.com')]
```

The function uses Python's standard `html.parser` rather than regular expressions, so it handles attribute quoting, uppercase tags, self-closing forms, and entity decoding correctly. Text from nested tags such as `<b>` is included in the anchor's text, and an `<a>` with no `href` yields `None`.

```python
from html.parser import HTMLParser


class _LinkParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)  # decode entities in text
        self.links = []
        self._current = None  # (href, list_of_text_parts) for the open <a>

    def handle_starttag(self, tag, attrs):
        if tag == "a":
            self._close()  # an <a> cannot contain another <a>; close the previous one
            href = None
            for name, value in attrs:
                if name == "href":
                    href = value if value is not None else ""
                    break
            self._current = (href, [])

    def handle_endtag(self, tag):
        if tag == "a":
            self._close()

    def handle_data(self, data):
        if self._current is not None:
            self._current[1].append(data)

    def _close(self):
        if self._current is not None:
            href, parts = self._current
            self.links.append(("".join(parts), href))
            self._current = None

    def close(self):
        super().close()
        self._close()  # handle an <a> that is never closed


def extract_links(html):
    parser = _LinkParser()
    parser.feed(html)
    parser.close()
    return parser.links
```

