from html.parser import HTMLParser


class _FirstTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.started = False    # have we entered the first <table>?
        self.finished = False   # have we left the first <table>?
        self.depth = 0          # nesting depth of <table> tags
        self.headers = []
        self.rows = []
        self.row = None         # list of (tag, text) for the current <tr>
        self.cell_tag = None    # 'td' or 'th' while inside a cell
        self.buf = []           # text collected for the current cell

    def _active(self):
        return self.started and not self.finished and self.depth == 1

    def _end_cell(self):
        if self.cell_tag is not None:
            text = "".join(self.buf).strip()
            if self.row is None:
                self.row = []
            self.row.append((self.cell_tag, text))
        self.cell_tag = None
        self.buf = []

    def _end_row(self):
        self._end_cell()
        if self.row is not None:
            for tag, text in self.row:
                if tag == "th":
                    self.headers.append(text)
            tds = [text for tag, text in self.row if tag == "td"]
            if tds:
                self.rows.append(tds)
        self.row = None

    def handle_starttag(self, tag, attrs):
        if tag == "table":
            if self.finished:
                return
            if not self.started:
                self.started = True
                self.depth = 1
            else:
                self.depth += 1
            return
        if not self._active():
            return
        if tag == "tr":
            self._end_row()
            self.row = []
        elif tag in ("td", "th"):
            self._end_cell()
            if self.row is None:
                self.row = []
            self.cell_tag = tag
            self.buf = []

    def handle_endtag(self, tag):
        if tag == "table":
            if not self.started or self.finished:
                return
            if self.depth == 1:
                self._end_row()
                self.finished = True
            else:
                self.depth -= 1
            return
        if not self._active():
            return
        if tag in ("td", "th"):
            self._end_cell()
        elif tag == "tr":
            self._end_row()

    def handle_data(self, data):
        if self._active() and self.cell_tag is not None:
            self.buf.append(data)


def extract_first_table(html):
    parser = _FirstTableParser()
    parser.feed(html)
    parser.close()

    if not parser.started:
        raise ValueError("no <table> found in HTML")

    # Flush anything left open if the table was never explicitly closed.
    if not parser.finished:
        parser._end_row()

    if not parser.rows:
        raise ValueError("first table has no data rows")

    return parser.headers, parser.rows
```

