Notes on the behavior:
- It uses the standard library's `html.parser` with `convert_charrefs=True`, so entities like `&amp;` are decoded and tags inside cells are dropped while their text is kept.
- Nested tables inside the first table are ignored for row and cell extraction, so the rows returned belong only to the outer table.
- Rows without `<td>` cells (such as a pure header row) are skipped for `rows`, but their `<th>` text still contributes to `headers`.

```python
from html.parser import HTMLParser


class _FirstTableParser(HTMLParser):
    def __init__(self):
        # convert_charrefs=True makes handle_data receive decoded entities.
        super().__init__(convert_charrefs=True)
        self.table_seen = False
        self.depth = 0          # table nesting depth; 1 = inside the first table
        self.done = False       # set once the first table has closed
        self.headers = []
        self.rows = []
        self._row = None        # {'th': [...], 'td': [...]} for the current <tr>
        self._cell = None       # list of text pieces for the open cell
        self._cell_kind = None  # 'th' or 'td'

    def _close_cell(self):
        if self._cell is not None:
            text = "".join(self._cell).strip()
            if self._row is None:
                self._row = {'th': [], 'td': []}
            self._row[self._cell_kind].append(text)
            self._cell = None
            self._cell_kind = None

    def _close_row(self):
        if self._row is not None:
            if self._row['th']:
                self.headers.extend(self._row['th'])
            if self._row['td']:
                self.rows.append(self._row['td'])
            self._row = None

    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        if tag == 'table':
            if self.depth == 0:
                self.depth = 1
                self.table_seen = True
            else:
                self.depth += 1
            return
        if self.depth != 1:
            return
        if tag == 'tr':
            self._close_cell()
            self._close_row()
            self._row = {'th': [], 'td': []}
        elif tag in ('td', 'th'):
            self._close_cell()
            if self._row is None:
                self._row = {'th': [], 'td': []}
            self._cell = []
            self._cell_kind = tag

    def handle_endtag(self, tag):
        if self.done:
            return
        if tag == 'table':
            if self.depth > 1:
                self.depth -= 1
            elif self.depth == 1:
                self._close_cell()
                self._close_row()
                self.depth = 0
                self.done = True
            return
        if self.depth != 1:
            return
        if tag in ('td', 'th'):
            self._close_cell()
        elif tag == 'tr':
            self._close_cell()
            self._close_row()

    def handle_data(self, data):
        if self.depth == 1 and self._cell is not None:
            self._cell.append(data)


def extract_first_table(html):
    parser = _FirstTableParser()
    parser.feed(html)
    parser.close()

    if not parser.table_seen:
        raise ValueError("No <table> found in the HTML")

    # Flush anything left open if the table was never explicitly closed.
    parser._close_cell()
    parser._close_row()

    if not parser.rows:
        raise ValueError("The first table has no data rows")

    return (parser.headers, parser.rows)
```

