```

Notes on the behavior:
- Only the first top-level `<table>` is read. If it contains a nested table, the nested table's rows and cells are ignored so they don't leak into the outer table's data.
- Text is stripped of surrounding whitespace, and entities like `&amp;` are decoded by the standard library's `HTMLParser`.
- Unclosed `<td>`, `<th>`, and `<tr>` tags are handled: a new cell or row implicitly closes the previous one.
- A `ValueError` is raised if there is no `<table>` or if the table has no `<td>`-containing rows.

```python
from html.parser import HTMLParser


class _FirstTableParser(HTMLParser):
    """Collects header cells and data rows from the first <table> in a document.

    Content of nested tables is ignored, and only the outermost table's
    rows and cells are recorded.
    """

    def __init__(self):
        super().__init__()  # convert_charrefs=True decodes entities in data
        self.depth = 0          # table nesting depth (0 = outside any table)
        self.found = False      # whether the first table has started
        self.done = False       # whether the first table has finished
        self.in_cell = None     # 'td' or 'th' while a cell is open
        self.cell_buf = []
        self.row_cells = None   # list of (kind, text) for the open row
        self.headers = []
        self.rows = []

    def _end_cell(self):
        if self.in_cell is None:
            return
        text = " ".join("".join(self.cell_buf).split())
        if self.in_cell == "th":
            self.headers.append(text)
        if self.row_cells is None:
            self.row_cells = []
        self.row_cells.append((self.in_cell, text))
        self.in_cell = None
        self.cell_buf = []

    def _end_row(self):
        if self.row_cells is None:
            return
        tds = [text for kind, text in self.row_cells if kind == "td"]
        if tds:
            self.rows.append(tds)
        self.row_cells = None

    def _finish_outer(self):
        self._end_cell()
        self._end_row()
        self.done = True

    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        if tag == "table":
            if self.depth == 0:
                self.found = True
            self.depth += 1
            return
        if self.depth != 1:
            return  # only the outermost table's rows/cells matter
        if tag == "tr":
            self._end_cell()
            self._end_row()
            self.row_cells = []
        elif tag in ("td", "th"):
            self._end_cell()
            self.in_cell = tag
            self.cell_buf = []

    def handle_endtag(self, tag):
        if self.done or self.depth == 0:
            return
        if tag == "table":
            if self.depth == 1:
                self._finish_outer()
            self.depth -= 1
            return
        if self.depth != 1:
            return
        if tag == "tr":
            self._end_cell()
            self._end_row()
        elif tag in ("td", "th"):
            self._end_cell()

    def handle_data(self, data):
        if self.in_cell is not None and self.depth == 1 and not self.done:
            self.cell_buf.append(data)


def extract_first_table(html):
    """Return (headers, rows) for the first <table> in the given HTML.

    headers: stripped text of every <th> cell in the table (empty list if none).
    rows: one list per <tr> containing <td> cells, each holding the stripped
          text of its <td> cells, in document order.

    Raises ValueError if there is no table or it has no data rows.
    """
    parser = _FirstTableParser()
    parser.feed(html)
    parser.close()

    if not parser.found:
        raise ValueError("no <table> found in HTML")
    if parser.depth > 0 and not parser.done:
        # Table was never closed; finalize whatever was open.
        parser._finish_outer()
    if not parser.rows:
        raise ValueError("table has no data rows")
    return parser.headers, parser.rows


if __name__ == "__main__":
    print(extract_first_table(
        "<table><tr><th>ID</th><th>Name</th></tr>"
        "<tr><td>1</td><td>Ann</td></tr></table>"
    ))  # (['ID', 'Name'], [['1', 'Ann']])
```

Design notes:

- **Parsing:** Uses the standard library's `html.parser`, so no third-party dependencies are needed. `convert_charrefs=True` decodes entities like `&amp;` and `&nbsp;`.
- **Text normalization:** Each cell's text is joined and whitespace is collapsed with `" ".join(text.split())`. This strips the ends and also turns internal runs of whitespace (including newlines) into single spaces. If you want only the outer strip, change that line.
- **Omitted end tags:** Unclosed `<td>`, `<th>`, and `<tr>` are handled, since HTML permits omitting them.
- **Nested tables:** Only the outermost table is read. Rows and cells of a table nested inside a cell are ignored, and their text is not added to the outer cell. The spec didn't cover this case, so this is my choice.
- **Headers:** Every `<th>` in the table is collected, including any in a row that also has `<td>` cells. Those rows still count only through their `<td>` cells.

The example from the prompt returns `(['ID', 'Name'], [['1', 'Ann']])`.

