import csv
import io


def grouped_column_means(csv_text, group_col, value_col):
    """
    Group the rows of CSV text by `group_col` and return the mean of `value_col`
    for each group.

    - Blank (or whitespace-only) cells in `value_col` are ignored.
    - Groups whose value cells are all blank do not appear in the result.
    - A non-numeric value in `value_col` raises ValueError.
    """
    reader = csv.DictReader(io.StringIO(csv_text))
    sums = {}
    counts = {}

    for row in reader:
        group = row[group_col]
        raw = row[value_col]

        # Ignore blank cells (a short row may also yield None here).
        if raw is None or raw.strip() == "":
            continue

        try:
            value = float(raw)
        except ValueError:
            raise ValueError(
                f"non-numeric value {raw!r} in column {value_col!r}"
            ) from None

        sums[group] = sums.get(group, 0.0) + value
        counts[group] = counts.get(group, 0) + 1

    return {group: sums[group] / counts[group] for group in sums}


if __name__ == "__main__":
    print(grouped_column_means('team,score\nA,1\nA,2\nB,3\nB,4\n', 'team', 'score'))
    # {'A': 1.5, 'B': 3.5}
