import csv
import io
import math


def grouped_column_means(csv_text, group_col, value_col):
    """
    Group the rows of CSV text by `group_col` and return the mean of
    `value_col` for each group.

    - Keys are group labels as strings.
    - Blank (empty or whitespace-only) value cells are ignored.
    - A group whose value cells are all blank maps to None, since it has no mean.
    - A non-numeric (or non-finite, e.g. 'nan') value raises ValueError.
    """
    reader = csv.DictReader(io.StringIO(csv_text))
    fieldnames = reader.fieldnames or []
    if group_col not in fieldnames:
        raise ValueError(f"group column {group_col!r} not found in header")
    if value_col not in fieldnames:
        raise ValueError(f"value column {value_col!r} not found in header")

    values_by_group = {}
    for row_num, row in enumerate(reader, start=2):  # row 1 is the header
        label = row.get(group_col) or ""
        raw = row.get(value_col)

        # Make sure the group appears in the result even if its values are blank.
        values = values_by_group.setdefault(label, [])

        if raw is None or raw.strip() == "":
            continue  # ignore blank cells

        try:
            number = float(raw)
        except ValueError:
            raise ValueError(
                f"non-numeric value {raw!r} in column {value_col!r} (line {row_num})"
            ) from None
        if not math.isfinite(number):
            raise ValueError(
                f"non-finite value {raw!r} in column {value_col!r} (line {row_num})"
            )
        values.append(number)

    return {
        label: (math.fsum(vals) / len(vals) if vals else None)
        for label, vals in values_by_group.items()
    }


if __name__ == "__main__":
    print(grouped_column_means('team,score\nA,1\nA,2\nB,3\nB,4\n', 'team', 'score'))
    # {'A': 1.5, 'B': 3.5}
