import csv
import io


def _parse_number(text):
    """Return text as an int or float, or None if it is not a number."""
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return None


def sort_csv_rows(csv_text, sort_by_column):
    reader = csv.reader(io.StringIO(csv_text))
    header = next(reader, [])

    if sort_by_column not in header:
        raise ValueError(f"Column {sort_by_column!r} not found in header: {header}")

    # Read data rows, skipping blank lines and padding short rows.
    raw_rows = []
    for row in reader:
        if not row:
            continue
        row = row + [""] * (len(header) - len(row))
        raw_rows.append(dict(zip(header, row)))

    # Determine which columns are entirely numeric.
    numeric_columns = set()
    for column in header:
        parsed = [_parse_number(r[column]) for r in raw_rows]
        if all(value is not None for value in parsed):
            numeric_columns.add(column)

    # Build the result records with converted values.
    records = []
    for r in raw_rows:
        record = {}
        for column in header:
            if column in numeric_columns:
                record[column] = _parse_number(r[column])
            else:
                record[column] = r[column]
        records.append(record)

    records.sort(key=lambda rec: rec[sort_by_column])
    return records
```

Example usage:

```python
