# [{'id': 3, 'title': 'Cherry', 'price': 0.2},
#  {'id': 1, 'title': 'Apple', 'price': 0.3},
#  {'id': 2, 'title': 'Banana', 'price': 0.5}]
```

A column is converted to numbers only if every value in it parses as a number; otherwise all its values stay as strings. Because the sort key comes from a single column, it always has a consistent type, so the sort never compares a number with a string.

```python
import csv
import io


def _parse_number(text):
    """Return int or float for text, or None if it is not a number."""
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return None


def sort_csv_rows(csv_text, sort_by_column):
    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text has no header row")

    if sort_by_column not in header:
        raise ValueError(f"Column {sort_by_column!r} not found in header")

    # Skip completely blank lines and pad/truncate rows to the header length.
    raw_rows = []
    for row in reader:
        if not row:
            continue
        row = (row + [""] * len(header))[:len(header)]
        raw_rows.append(row)

    # Determine which columns are entirely numeric.
    numeric_cols = []
    for i in range(len(header)):
        if all(_parse_number(row[i]) is not None for row in raw_rows):
            numeric_cols.append(i)

    # Build the typed rows.
    rows = []
    for raw in raw_rows:
        record = {}
        for i, name in enumerate(header):
            if i in numeric_cols:
                record[name] = _parse_number(raw[i])
            else:
                record[name] = raw[i]
        rows.append(record)

    # Sort ascending by the requested column.
    rows.sort(key=lambda r: r[sort_by_column])
    return rows
```

Example usage:

```python
print(sort_csv_rows("id,title,price\n2,Banana,0.5\n1,Apple,0.3\n3,Cherry,0.2\n", "price"))
# [{'id': 3, 'title': 'Cherry', 'price': 0.2},
#  {'id': 1, 'title': 'Apple', 'price': 0.3},
#  {'id': 2, 'title': 'Banana', 'price': 0.5}]
```

Notes on the behavior:
- A column is treated as numeric only if every value in it parses as a number; each value is then converted to an `int` if it looks like one, otherwise a `float`. Any other column keeps its values as strings.
- Sorting is numeric for numeric columns and lexicographic for string columns.
- Blank lines are skipped, and short rows are padded with empty strings so every row has every header key.
- A `ValueError` is raised if the requested column isn't in the header (or if the text has no header at all).

```python
from collections import Counter

_WS = frozenset(b' \t\r\n\x0b\x0c')   # PGM whitespace: blank, TAB, CR, LF, VT, FF
_HASH = ord('#')
_NEWLINES = frozenset(b'\r\n')


def _skip_whitespace_and_comments(data, pos):
    """Advance past whitespace and '#...' comments (to end of line)."""
    n = len(data)
    while pos < n:
        c = data[pos]
        if c in _WS:
            pos += 1
        elif c == _HASH:
            while pos < n and data[pos] not in _NEWLINES:
                pos += 1
        else:
            break
    return pos


def _read_token(data, pos):
    """Return (token_bytes, position_after_token)."""
    pos = _skip_whitespace_and_comments(data, pos)
    start = pos
    n = len(data)
    while pos < n and data[pos] not in _WS and data[pos] != _HASH:
        pos += 1
    if pos == start:
        raise ValueError("unexpected end of PGM data")
    return data[start:pos], pos


def _parse_uint(token):
    if not token or not token.isdigit():   # bytes.isdigit is ASCII-only
        raise ValueError(f"invalid PGM integer: {token!r}")
    return int(token)


def grayscale_histogram(data):
    """
    Return the pixel-value histogram of an 8-bit grayscale PGM image
    (P2 ASCII or P5 binary) as {pixel_value: count}.

    Raises ValueError if the data is not a valid 8-bit PGM image.
    """
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("PGM data must be bytes")
    data = bytes(data)

    magic = data[:2]
    if magic not in (b'P2', b'P5'):
        raise ValueError("not a P2 or P5 PGM file")
    pos = 2
    if pos >= len(data) or data[pos] not in _WS:
        raise ValueError("missing whitespace after magic number")

    tok, pos = _read_token(data, pos)
    width = _parse_uint(tok)
    tok, pos = _read_token(data, pos)
    height = _parse_uint(tok)
    tok, pos = _read_token(data, pos)
    maxval = _parse_uint(tok)

    if width == 0 or height == 0:
        raise ValueError("image dimensions must be positive")
    if not 1 <= maxval <= 255:
        raise ValueError("maxval must be between 1 and 255 for 8-bit PGM")

    count = width * height

    if magic == b'P5':
        # Exactly one whitespace byte separates the header from the raster.
        if pos >= len(data) or data[pos] not in _WS:
            raise ValueError("missing whitespace before raster data")
        pos += 1
        raster = data[pos:pos + count]
        if len(raster) != count:
            raise ValueError("raster data is shorter than width*height")
        counter = Counter(raster)          # iterating bytes yields ints 0-255
    else:  # P2
        values = []
        for _ in range(count):
            tok, pos = _read_token(data, pos)
            values.append(_parse_uint(tok))
        counter = Counter(values)

    for value in counter:
        if value > maxval:
            raise ValueError(f"pixel value {value} exceeds maxval {maxval}")

    return dict(sorted(counter.items()))


if __name__ == "__main__":
    print(grayscale_histogram(b'P5\n2 2\n255\n\x00\x01\x02\xff'))
    # {0: 1, 1: 1, 2: 1, 255: 1}
    print(grayscale_histogram(b'P2\n# comment\n2 2\n255\n0 0 7 7\n'))
    # {0: 2, 7: 2}
```

**Notes on the implementation**

- **Header parsing** follows the PGM spec: tokens are separated by whitespace (blank, tab, CR, LF, VT, FF), and `#` starts a comment that runs to the end of the line. This applies to both P2 and P5 headers.
- **Binary (P5)**: exactly one whitespace byte follows `maxval`, and the raster is read directly from the following `width*height` bytes. The raster may legitimately contain bytes that look like whitespace, so it is never tokenized.
- **ASCII (P2)**: the raster is read as `width*height` decimal tokens, skipping any whitespace and comments between them.
- **Validation** raises `ValueError` for a bad magic number, missing or non-numeric header fields, zero dimensions, `maxval` outside 1–255 (since this is an 8-bit image), truncated raster data, or pixel values greater than `maxval`. Trailing bytes after the raster are ignored.
- The result is a dict sorted by pixel value, containing only values that actually occur.

```python
from collections import Counter

_WHITESPACE = b' \t\r\n\x0b\x0c'


def grayscale_histogram(data):
    """
    Return the pixel-value histogram of an 8-bit grayscale PGM image
    (P5 binary or P2 ASCII) as a dict {value: count}.

    Raises ValueError if the data is not a valid 8-bit PGM image.
    """
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("data must be bytes")
    data = bytes(data)
    n = len(data)

    if n < 2 or data[:2] not in (b'P2', b'P5'):
        raise ValueError("not a PGM file (bad magic number)")
    is_binary = data[:2] == b'P5'

    def skip_ws(pos):
        # Skip whitespace and '#' comments (comment runs to end of line).
        while pos < n:
            c = data[pos]
            if c == ord('#'):
                while pos < n and data[pos] not in (10, 13):
                    pos += 1
            elif c in _WHITESPACE:
                pos += 1
            else:
                break
        return pos

    def read_int(pos):
        pos = skip_ws(pos)
        start = pos
        while pos < n and 48 <= data[pos] <= 57:
            pos += 1
        if pos == start:
            raise ValueError("expected a decimal integer in PGM header/data")
        return int(data[start:pos]), pos

    # The magic number must be followed by whitespace.
    if n < 3 or data[2] not in _WHITESPACE:
        raise ValueError("malformed PGM header after magic number")
    pos = 2

    width, pos = read_int(pos)
    height, pos = read_int(pos)
    maxval, pos = read_int(pos)

    if width <= 0 or height <= 0:
        raise ValueError("width and height must be positive")
    if not (1 <= maxval <= 255):
        raise ValueError("maxval must be between 1 and 255 for 8-bit images")

    # The maxval token must be followed by exactly one whitespace character.
    if pos >= n or data[pos] not in _WHITESPACE:
        raise ValueError("missing whitespace after header")
    pos += 1

    count = width * height

    if is_binary:
        raster = data[pos:pos + count]
        if len(raster) < count:
            raise ValueError("raster data is truncated")
        values = raster
    else:
        values = bytearray()
        for _ in range(count):
            v, pos = read_int(pos)
            if v > 255:
                raise ValueError("pixel value out of range")
            values.append(v)

    if values and max(values) > maxval:
        raise ValueError("pixel value exceeds maxval")

    return dict(Counter(values))
```

Usage example:

```python
>>> grayscale_histogram(b'P5\n2 2\n255\n\x00\x01\x02\xff')
{0: 1, 1: 1, 2: 1, 255: 1}
>>> grayscale_histogram(b'P2\n# comment\n2 2\n255\n0 0 7 255\n')
{0: 2, 7: 1, 255: 1}
```

Notes on the implementation:
- Both P2 and P5 headers allow whitespace and `#` comments between fields.
- For P5, exactly one whitespace byte separates the header from the binary raster, and the raster is read as exactly `width * height` bytes.
- For P2, exactly `width * height` decimal values are read. Non-numeric tokens are rejected.
- Values greater than `maxval` or greater than 255 are rejected, and `maxval` above 255 (16-bit PGM) is rejected since this function handles 8-bit images only.
- Truncated rasters, missing magic numbers, and nonpositive dimensions all raise `ValueError`. Trailing bytes after the expected pixel data are ignored.

```python
from collections import Counter

_WHITESPACE = b' \t\r\n\v\f'


def _read_token(data, pos):
    """Return (token, end_pos) for the next whitespace/comment-delimited token.

    Whitespace and '#...' comments (through end of line) are skipped first.
    `end_pos` points at the byte that terminated the token (not consumed).
    """
    n = len(data)
    while pos < n:
        c = data[pos]
        if c in _WHITESPACE:
            pos += 1
        elif c == ord('#'):
            while pos < n and data[pos] not in (ord('\n'), ord('\r')):
                pos += 1
        else:
            break
    if pos >= n:
        raise ValueError("unexpected end of PGM header")
    start = pos
    while pos < n and data[pos] not in _WHITESPACE and data[pos] != ord('#'):
        pos += 1
    return data[start:pos], pos


def _parse_int(token):
    if not token or not token.isdigit():
        raise ValueError("invalid integer in PGM header: %r" % token)
    return int(token)


def grayscale_histogram(data):
    """Return the pixel-value histogram of an 8-bit grayscale PGM image.

    Supports the binary (P5) and ASCII (P2) variants. The result maps each
    pixel value that occurs in the image to its pixel count.

    Raises ValueError if the data is not a valid 8-bit grayscale PGM image.
    """
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise ValueError("data must be bytes")
    data = bytes(data)

    magic, pos = _read_token(data, 0)
    if magic not in (b'P2', b'P5'):
        raise ValueError("not a grayscale PGM file (bad magic number)")

    width_tok, pos = _read_token(data, pos)
    height_tok, pos = _read_token(data, pos)
    maxval_tok, pos = _read_token(data, pos)

    width = _parse_int(width_tok)
    height = _parse_int(height_tok)
    maxval = _parse_int(maxval_tok)

    if width <= 0 or height <= 0:
        raise ValueError("image dimensions must be positive")
    if not (1 <= maxval <= 255):
        raise ValueError("maxval must be between 1 and 255 for 8-bit images")

    count = width * height

    if magic == b'P5':
        # Exactly one whitespace byte separates the header from the raster.
        if pos >= len(data) or data[pos] not in _WHITESPACE:
            raise ValueError("missing whitespace after PGM header")
        raster = data[pos + 1:pos + 1 + count]
        if len(raster) < count:
            raise ValueError("not enough pixel data in binary PGM")
        if max(raster) > maxval:
            raise ValueError("pixel value exceeds maxval")
        return dict(Counter(raster))

    # P2: ASCII pixel values, whitespace separated.
    counts = Counter()
    for _ in range(count):
        tok, pos = _read_token(data, pos)
        value = _parse_int(tok)
        if value > maxval:
            raise ValueError("pixel value exceeds maxval")
        counts[value] += 1
    return dict(counts)
```

**Example:**

```python
>>> grayscale_histogram(b'P5\n2 2\n255\n\x00\x01\x02\xff')
{0: 1, 1: 1, 2: 1, 255: 1}
>>> grayscale_histogram(b'P2\n# a comment\n2 2\n255\n0 0 7 255')
{0: 2, 7: 1, 255: 1}
```

**Validation performed:**
- Magic number must be `P2` or `P5`.
- Width and height must be positive integers; maxval must be in 1–255 (larger maxvals are 16-bit and rejected).
- Binary data must contain at least `width*height` bytes after the single separator byte.
- ASCII data must contain `width*height` integer tokens.
- No pixel value may exceed maxval.
- Comments (`#` to end of line) are skipped in the header and in ASCII data.

Any violation raises `ValueError`. Trailing bytes after the pixel data are ignored.

```python
from collections import Counter

_WHITESPACE = b" \t\r\n\v\f"


def _next_token(data, pos):
    """Return (token, end_pos) for the next whitespace-delimited header token.

    Skips whitespace and '#' comments (which run to the end of the line).
    `end_pos` is the index just past the token, i.e. the delimiter byte.
    """
    n = len(data)
    while pos < n:
        c = data[pos]
        if c in _WHITESPACE:
            pos += 1
        elif c == ord("#"):
            while pos < n and data[pos] not in b"\r\n":
                pos += 1
        else:
            break
    if pos >= n:
        raise ValueError("unexpected end of PGM header")
    start = pos
    while pos < n and data[pos] not in _WHITESPACE and data[pos] != ord("#"):
        pos += 1
    return data[start:pos], pos


def _parse_int(token):
    if not token or not token.isdigit():
        raise ValueError(f"invalid integer in PGM header: {token!r}")
    return int(token)


def grayscale_histogram(data):
    """Return {pixel_value: count} for an 8-bit grayscale PGM (P2 or P5) image.

    Raises ValueError if the data is not a valid 8-bit grayscale PGM image.
    """
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("PGM data must be bytes")
    data = bytes(data)

    magic, pos = _next_token(data, 0)
    if magic not in (b"P2", b"P5"):
        raise ValueError("not a P2 or P5 PGM file")

    width_tok, pos = _next_token(data, pos)
    height_tok, pos = _next_token(data, pos)
    maxval_tok, pos = _next_token(data, pos)

    width = _parse_int(width_tok)
    height = _parse_int(height_tok)
    maxval = _parse_int(maxval_tok)

    if width <= 0 or height <= 0:
        raise ValueError("image dimensions must be positive")
    if not (1 <= maxval <= 255):
        raise ValueError("maxval must be between 1 and 255 for 8-bit grayscale")

    count = width * height

    if magic == b"P5":
        # Exactly one whitespace byte separates the header from the raster.
        if pos >= len(data) or data[pos] not in _WHITESPACE:
            raise ValueError("missing whitespace before binary raster")
        raster = data[pos + 1:]
        if len(raster) < count:
            raise ValueError("not enough pixel data")
        raster = raster[:count]
        if max(raster) > maxval:
            raise ValueError("pixel value exceeds maxval")
        return dict(Counter(raster))

    # P2: ASCII raster
    counts = Counter()
    for _ in range(count):
        tok, pos = _next_token(data, pos)
        value = _parse_int(tok)
        if value > maxval:
            raise ValueError("pixel value exceeds maxval")
        counts[value] += 1
    return dict(counts)
```

**Notes on the implementation:**

- **Header parsing** handles whitespace and `#` comments between the magic number, width, height, and maxval, as the PGM spec allows.
- **P5 (binary):** exactly one whitespace byte follows maxval, and the raster begins right after it. Each byte is one pixel.
- **P2 (ASCII):** each pixel is a decimal integer token, read in sequence regardless of line breaks.
- **Validation:** raises `ValueError` for a bad magic number, non-positive or non-integer dimensions, maxval outside 1–255 (values above 255 are 16-bit, not 8-bit), insufficient pixel data, pixel values greater than maxval, and malformed numbers.
- **Trailing data** after the `width*height` pixels is ignored in both variants. If you want stricter behavior, you could raise an error when extra bytes remain.

**Example:**

```python
>>> grayscale_histogram(b'P5\n2 2\n255\n\x00\x01\x02\xff')
{0: 1, 1: 1, 2: 1, 255: 1}
>>> grayscale_histogram(b'P2\n# comment\n2 2\n255\n0 1\n2 255\n')
{0: 1, 1: 1, 2: 1, 255: 1}
```

```python
import csv
import io
import math
import re

# Matches plain numbers ("42", "-3.5", ".5") and numbers with proper
# thousands grouping ("1,000", "12,345,678.9").
_NUMBER_RE = re.compile(
    r'^[+-]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?$|^[+-]?\.\d+$'
)


def _parse_number(text):
    """Return the float value of a numeric string, or None if it isn't a number."""
    s = text.strip()
    if not _NUMBER_RE.match(s):
        return None
    return float(s.replace(',', ''))


def summarize_numeric_csv(csv_text):
    """
    Summarize the numeric columns of a CSV text with a header row.

    Returns a dict with:
      'means'    -> {column: mean}
      'std_devs' -> {column: sample standard deviation (n-1), or None if n < 2}
      'f_value'  -> one-way ANOVA F statistic comparing numeric columns as
                    groups, or None if there are fewer than two numeric columns
                    (or the F statistic is undefined, e.g. zero within-group
                    variance or too few observations).

    Columns in which any value is not a number (including empty cells or
    missing fields) are ignored.
    """
    rows = list(csv.reader(io.StringIO(csv_text)))
    if not rows:
        return {'means': {}, 'std_devs': {}, 'f_value': None}

    header = [name.strip() for name in rows[0]]
    data_rows = [r for r in rows[1:] if any(cell.strip() for cell in r)]

    columns = {}
    for idx, name in enumerate(header):
        values = []
        numeric = True
        for row in data_rows:
            if idx >= len(row):
                numeric = False
                break
            value = _parse_number(row[idx])
            if value is None:
                numeric = False
                break
            values.append(value)
        if numeric and values:
            columns[name] = values

    means = {}
    std_devs = {}
    for name, values in columns.items():
        n = len(values)
        mean = math.fsum(values) / n
        means[name] = mean
        if n >= 2:
            ss = math.fsum((x - mean) ** 2 for x in values)
            std_devs[name] = math.sqrt(ss / (n - 1))
        else:
            std_devs[name] = None

    f_value = None
    k = len(columns)
    if k >= 2:
        all_values = [x for vals in columns.values() for x in vals]
        n_total = len(all_values)
        grand_mean = math.fsum(all_values) / n_total

        ss_between = math.fsum(
            len(vals) * (means[name] - grand_mean) ** 2
            for name, vals in columns.items()
        )
        ss_within = math.fsum(
            math.fsum((x - means[name]) ** 2 for x in vals)
            for name, vals in columns.items()
        )

        df_between = k - 1
        df_within = n_total - k
        if df_within > 0:
            ms_between = ss_between / df_between
            ms_within = ss_within / df_within
            if ms_within > 0:
                f_value = ms_between / ms_within
            # If ms_within == 0 the F statistic is undefined/infinite; leave None.

    return {'means': means, 'std_devs': std_devs, 'f_value': f_value}
```

**Check against the example:** for `'A,B\n1,4\n2,5\n3,6\n'`, the means are 2.0 and 5.0, and the sample standard deviations are each 1.0. The grand mean is 3.5, so SS_between = 3·(1.5)² + 3·(1.5)² = 13.5 and SS_within = 2 + 2 = 4. With df_between = 1 and df_within = 4, MS_between = 13.5 and MS_within = 1, giving F = 13.5.

**Design choices:**
- Thousands separators are accepted only when properly grouped (e.g. `1,000` or `1,234,567`); malformed forms like `1,00` are treated as non-numeric.
- Blank lines are skipped, and a column with an empty cell is treated as non-numeric and dropped.
- `std_devs` is `None` for a column with only one value, since the sample standard deviation is undefined there.
- `f_value` is `None` when there are fewer than two numeric columns, or when the within-group variance is zero or there are no residual degrees of freedom, since the statistic is undefined in those cases.

```python
import csv
import io
import math
import re

# Accepts plain numbers ("1000", "-3.5", ".5") and numbers with
# thousands separators in standard grouping ("1,000", "1,234,567.89").
_NUMBER_RE = re.compile(
    r'^[+-]?(\d{1,3}(,\d{3})+|\d+)(\.\d*)?$|^[+-]?\.\d+$'
)


def _parse_number(text):
    """Return the float value of text, or None if it is not a valid number."""
    s = text.strip()
    if not _NUMBER_RE.match(s):
        return None
    value = float(s.replace(',', ''))
    if not math.isfinite(value):
        return None
    return value


def summarize_numeric_csv(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if any(cell.strip() for cell in row)]

    if not rows:
        return {'means': {}, 'std_devs': {}, 'f_value': None}

    header, data = rows[0], rows[1:]

    # Collect only the columns where every value is numeric.
    columns = {}
    for j, name in enumerate(header):
        values = []
        is_numeric = True
        for row in data:
            cell = row[j] if j < len(row) else ''
            value = _parse_number(cell)
            if value is None:
                is_numeric = False
                break
            values.append(value)
        if is_numeric and values:
            columns[name] = values

    means = {}
    std_devs = {}
    for name, values in columns.items():
        n = len(values)
        mean = sum(values) / n
        means[name] = mean
        if n >= 2:
            var = sum((x - mean) ** 2 for x in values) / (n - 1)
            std_devs[name] = math.sqrt(var)
        else:
            std_devs[name] = None

    f_value = None
    if len(columns) >= 2:
        groups = list(columns.values())
        k = len(groups)
        total_n = sum(len(g) for g in groups)
        grand_mean = sum(sum(g) for g in groups) / total_n

        ss_between = sum(len(g) * (sum(g) / len(g) - grand_mean) ** 2 for g in groups)
        ss_within = sum(
            (x - sum(g) / len(g)) ** 2 for g in groups for x in g
        )

        df_between = k - 1
        df_within = total_n - k
        if df_within > 0:
            ms_between = ss_between / df_between
            ms_within = ss_within / df_within
            if ms_within > 0:
                f_value = ms_between / ms_within

    return {'means': means, 'std_devs': std_devs, 'f_value': f_value}
```

**Notes on the implementation:**

- **Parsing:** The `csv` module handles quoted fields, so `"1,000"` arrives as the string `1,000`. A regex then checks that commas appear only in valid three-digit groups, so malformed input like `1,00` is treated as non-numeric rather than silently becoming `100`. Non-finite values such as `nan` or `inf` are rejected.
- **Column filtering:** A column is kept only if it has at least one data row and every value in it is numeric. Blank rows are skipped. A missing cell counts as non-numeric.
- **Standard deviation:** Uses the sample formula with `n - 1`. It is `None` for a column with a single value.
- **ANOVA:** Computes the between-group and within-group sums of squares directly, which also handles groups of unequal size. `f_value` is `None` when there are fewer than two numeric columns, when there are no within-group degrees of freedom, or when the within-group variance is zero (the F statistic is undefined there).

For the example `'A,B\n1,4\n2,5\n3,6\n'`, the function returns means `{'A': 2.0, 'B': 5.0}`, standard deviations `{'A': 1.0, 'B': 1.0}`, and F = 13.5.

