```python
def fit_and_evaluate_linear_regression(X_train, y_train, X_test, y_test):
    """
    Fit an ordinary least-squares linear regression with an intercept on the
    training data, then evaluate it on the test data.

    Returns (predictions, coefficients, intercept, mse).
    """
    if len(X_train) != len(y_train):
        raise ValueError("X_train and y_train must have the same length")
    if len(X_test) != len(y_test):
        raise ValueError("X_test and y_test must have the same length")
    if len(X_train) == 0:
        raise ValueError("Training data must not be empty")

    n_features = len(X_train[0])
    p = n_features + 1  # include intercept column

    # Build the normal equations (A^T A) beta = A^T y, where A = [1, x1, ..., xk].
    XtX = [[0.0] * p for _ in range(p)]
    Xty = [0.0] * p
    for row, target in zip(X_train, y_train):
        a = [1.0] + [float(v) for v in row]
        for i in range(p):
            Xty[i] += a[i] * target
            for j in range(p):
                XtX[i][j] += a[i] * a[j]

    # Solve the linear system with Gaussian elimination and partial pivoting.
    M = [XtX[i][:] + [Xty[i]] for i in range(p)]
    for col in range(p):
        pivot = max(range(col, p), key=lambda r: abs(M[r][col]))
        if abs(M[pivot][col]) < 1e-12:
            raise ValueError("Design matrix is singular; features are collinear")
        M[col], M[pivot] = M[pivot], M[col]
        for r in range(p):
            if r != col and M[r][col] != 0.0:
                factor = M[r][col] / M[col][col]
                for c in range(col, p + 1):
                    M[r][c] -= factor * M[col][c]

    beta = [M[i][p] / M[i][i] for i in range(p)]
    intercept = float(beta[0])
    coefficients = [float(b) for b in beta[1:]]

    # Predict on the test set.
    predictions = []
    for row in X_test:
        value = intercept
        for c, x in zip(coefficients, row):
            value += c * float(x)
        predictions.append(float(value))

    # Mean squared error against y_test.
    if len(y_test) == 0:
        mse = 0.0
    else:
        mse = sum((pred - float(actual)) ** 2
                  for pred, actual in zip(predictions, y_test)) / len(y_test)

    return predictions, coefficients, intercept, float(mse)


if __name__ == "__main__":
    result = fit_and_evaluate_linear_regression(
        [[1], [2], [3], [4]], [3, 5, 7, 9], [[5], [6]], [11, 14]
    )
    print(result)  # approximately ([11.0, 13.0], [2.0], 1.0, 0.5)
```

The function builds the normal equations with a column of ones for the intercept, solves them by Gaussian elimination with partial pivoting, and then computes predictions and the mean squared error on the test set. For the example, it recovers a slope of 2 and an intercept of 1, giving predictions `[11.0, 13.0]` and an MSE of `0.5`. Because the solve uses floating-point arithmetic, values may differ from the exact results in the last few bits.

