import math

def standardize_and_correlate(table):
    """
    Standardize numeric columns of `table` (mean 0, population std 1) and
    compute the Pearson correlation matrix of the numeric columns.

    Returns (standardized, corr), where `standardized` keeps every column in
    its original order (non-numeric columns unchanged) and `corr` is a list of
    lists in table column order.

    Raises ValueError if the table is empty or has no numeric columns.
    A numeric column with zero variance is standardized to all zeros, and its
    correlations are reported as NaN (they are undefined).
    """
    if not table:
        raise ValueError("table is empty")

    def is_numeric_value(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    numeric_names = []
    for name, col in table.items():
        values = list(col)
        if values and all(is_numeric_value(v) for v in values):
            numeric_names.append(name)

    if not numeric_names:
        raise ValueError("table has no numeric columns")

    standardized = {}
    z_cols = {}
    constant = {}

    for name, col in table.items():
        if name in numeric_names:
            vals = [float(v) for v in col]
            n = len(vals)
            mean = sum(vals) / n
            var = sum((v - mean) ** 2 for v in vals) / n
            sd = math.sqrt(var)
            if sd == 0:
                z = [0.0] * n
                constant[name] = True
            else:
                z = [(v - mean) / sd for v in vals]
                constant[name] = False
            z_cols[name] = z
            standardized[name] = z
        else:
            standardized[name] = list(col)

    corr = []
    for a in numeric_names:
        row = []
        za = z_cols[a]
        for b in numeric_names:
            if a == b:
                row.append(float('nan') if constant[a] else 1.0)
            elif constant[a] or constant[b]:
                row.append(float('nan'))
            else:
                zb = z_cols[b]
                n = len(za)
                row.append(sum(x * y for x, y in zip(za, zb)) / n)
        corr.append(row)

    return standardized, corr
```

**Notes on the implementation:**

- **Numeric detection:** a column is numeric if it is non-empty and every value is an `int` or `float` (booleans are excluded).
- **Standardization:** each numeric column becomes `(v - mean) / sd`, using the population standard deviation.
- **Correlation:** since the standardized columns have mean 0 and population std 1, Pearson's r reduces to the mean of the products of the z-scores. Diagonal entries are set to exactly `1.0` for non-constant columns.
- **Constant columns:** the spec doesn't cover zero variance. Here such a column is standardized to all zeros, and its correlations are `NaN` rather than raising an error. If you'd prefer a `ValueError` in that case, it's a one-line change.

For the example in the question, this returns the expected standardized values and `[[1.0, -0.5], [-0.5, 1.0]]`.

