import math


def standardize_and_correlate(table):
    """
    Standardize the numeric columns of `table` and compute their Pearson
    correlation matrix.

    A column is numeric if every value is an int or float (bools are not
    treated as numeric). Numeric columns are rescaled to mean 0 and population
    standard deviation 1; other columns are copied unchanged.

    Returns (standardized, corr), where `corr` is a list of lists of the
    Pearson correlations between numeric columns, in table order.

    A constant numeric column has zero standard deviation. Its standardized
    values are set to 0.0, and its correlations with other columns are NaN.

    Raises ValueError if the table is empty, has no numeric columns, has
    columns of unequal length, or has zero rows.
    """
    if not table:
        raise ValueError("table is empty")

    lengths = {len(col) for col in table.values()}
    if len(lengths) > 1:
        raise ValueError("all columns must have equal length")
    n = lengths.pop()
    if n == 0:
        raise ValueError("columns are empty")

    def is_numeric(col):
        return all(isinstance(x, (int, float)) and not isinstance(x, bool) for x in col)

    numeric_cols = [name for name, col in table.items() if is_numeric(col)]
    if not numeric_cols:
        raise ValueError("table has no numeric columns")

    standardized = {}
    devs = {}   # centered values for numeric columns
    ss = {}     # sum of squared deviations
    for name, col in table.items():
        if name in numeric_cols:
            vals = [float(x) for x in col]
            mean = sum(vals) / n
            d = [x - mean for x in vals]
            sum_sq = sum(x * x for x in d)
            sd = math.sqrt(sum_sq / n)
            if sd == 0:
                standardized[name] = [0.0] * n
            else:
                standardized[name] = [x / sd for x in d]
            devs[name] = d
            ss[name] = sum_sq
        else:
            standardized[name] = list(col)

    corr = []
    for a in numeric_cols:
        row = []
        for b in numeric_cols:
            if a == b:
                row.append(1.0 if ss[a] > 0 else float("nan"))
            else:
                denom = math.sqrt(ss[a] * ss[b])
                if denom == 0:
                    row.append(float("nan"))
                else:
                    num = sum(x * y for x, y in zip(devs[a], devs[b]))
                    row.append(num / denom)
        corr.append(row)

    return standardized, corr
```

For the example in the prompt, the `y` column's values are `[3, 1, 2]`. Its mean is 2 and its population standard deviation is √(2/3), so the standardized values are `[1.2247…, -1.2247…, 0.0]`. The correlation between `x` and `y` is −1 / (√2·√2) = −0.5, which matches the expected output.

