from html.parser import HTMLParser


class _RowExtractor(HTMLParser):
    """
    Collects the text of each <td> cell in each <tr> row.

    Open elements are tracked on a stack so that omitted end tags
    (e.g. <td> without </td>) are handled the way browsers handle them,
    and nested tables are kept separate from their parents.
    """

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = []    # each row is a list of text buffers (lists of str)
        self.stack = []   # entries: (kind, payload); kinds: table, tr, td, th
        self.skip = 0     # depth inside <script>/<style>

    # Pop entries from the top of the stack down to and including the
    # nearest entry of kind `tag`, unless a `stops` kind is met first.
    def _end(self, tag, stops):
        for i in range(len(self.stack) - 1, -1, -1):
            kind = self.stack[i][0]
            if kind == tag:
                del self.stack[i:]
                return
            if kind in stops:
                return

    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style"):
            self.skip += 1
            return

        if tag == "table":
            self.stack.append(("table", None))

        elif tag == "tr":
            # A new row closes any open row/cell in the current table.
            self._truncate_after_last(("table",))
            row = []
            self.rows.append(row)
            self.stack.append(("tr", row))

        elif tag in ("td", "th"):
            # A new cell closes any open cell in the current row.
            j = self._last_index(("tr", "table"))
            if j is not None:
                del self.stack[j + 1:]
            if tag == "td" and j is not None and self.stack[j][0] == "tr":
                buf = []
                self.stack[j][1].append(buf)
                self.stack.append(("td", buf))
            else:
                # Header cells, or cells outside any row: not collected.
                self.stack.append(("td", None))

    def handle_endtag(self, tag):
        if tag in ("script", "style"):
            if self.skip:
                self.skip -= 1
            return

        if tag == "table":
            self._end("table", ())
        elif tag == "tr":
            self._end("tr", ("table",))
        elif tag in ("td", "th"):
            self._end("td", ("table", "tr"))

    def handle_data(self, data):
        if self.skip:
            return
        if self.stack:
            kind, buf = self.stack[-1]
            if kind == "td" and buf is not None:
                buf.append(data)

    def _last_index(self, kinds):
        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i][0] in kinds:
                return i
        return None

    def _truncate_after_last(self, kinds):
        j = self._last_index(kinds)
        del self.stack[(j + 1) if j is not None else 0:]


def extract_table_rows(html):
    parser = _RowExtractor()
    parser.feed(html)
    parser.close()
    return [[''.join(buf).strip() for buf in row] for row in parser.rows]
```

