from html.parser import HTMLParser


class _TableRowParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = []    # result: one list per <tr>, in document order
        self.stack = []   # open elements we track: ('tr', row) or ('td'|'th', parts, row)

    def _finish_cell(self, entry):
        kind = entry[0]
        if kind == 'td':
            _, parts, row = entry
            row.append(''.join(parts).strip())
        # <th> cells are ignored

    def _close_open_cell(self):
        """Close a cell left open by omitted end tags (e.g. <td>a<td>b)."""
        if self.stack and self.stack[-1][0] in ('td', 'th'):
            self._finish_cell(self.stack.pop())

    def handle_starttag(self, tag, attrs):
        if tag == 'tr':
            self._close_open_cell()
            row = []
            self.rows.append(row)
            self.stack.append(('tr', row))
        elif tag in ('td', 'th'):
            self._close_open_cell()
            # Find the innermost open row; a cell only makes sense inside one.
            row = None
            for entry in reversed(self.stack):
                if entry[0] == 'tr':
                    row = entry[1]
                    break
            if row is not None or tag == 'th':
                self.stack.append((tag, [], row))

    def handle_endtag(self, tag):
        if tag in ('td', 'th'):
            idx = self._last_index(tag)
            if idx is not None:
                while len(self.stack) > idx:
                    entry = self.stack.pop()
                    if entry[0] in ('td', 'th'):
                        self._finish_cell(entry)
        elif tag == 'tr':
            idx = self._last_index('tr')
            if idx is not None:
                while len(self.stack) > idx:
                    entry = self.stack.pop()
                    if entry[0] in ('td', 'th'):
                        self._finish_cell(entry)

    def _last_index(self, kind):
        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i][0] == kind:
                return i
        return None

    def handle_data(self, data):
        if self.stack and self.stack[-1][0] in ('td', 'th'):
            self.stack[-1][1].append(data)


def extract_table_rows(html):
    parser = _TableRowParser()
    parser.feed(html)
    parser.close()
    # Finish any cells/rows left open at end of input.
    while parser.stack:
        entry = parser.stack.pop()
        if entry[0] in ('td', 'th'):
            parser._finish_cell(entry)
    return parser.rows
