from html.parser import HTMLParser


class _RowExtractor(HTMLParser):
    def __init__(self):
        # convert_charrefs=True makes the parser decode entities in text data.
        super().__init__(convert_charrefs=True)
        self.rows = []         # one list of cell texts per <tr>, in document order
        self.row_stack = []    # currently open <tr> lists (innermost last)
        self.cell_stack = []   # currently open cells: dicts with 'row', 'tag', 'buf'

    def _finish_cell(self):
        cell = self.cell_stack.pop()
        # Only <td> cells are recorded; <th> cells are ignored.
        if cell['row'] is not None and cell['tag'] == 'td':
            cell['row'].append(''.join(cell['buf']).strip())

    def _finish_row(self):
        # Close any cells still open inside this row (omitted </td>).
        current = self.row_stack[-1]
        while self.cell_stack and self.cell_stack[-1]['row'] is current:
            self._finish_cell()
        self.row_stack.pop()

    def handle_starttag(self, tag, attrs):
        if tag == 'tr':
            if self.row_stack:
                # Previous row was not explicitly closed.
                self._finish_row()
            row = []
            self.rows.append(row)
            self.row_stack.append(row)
        elif tag in ('td', 'th'):
            current_row = self.row_stack[-1] if self.row_stack else None
            # A new sibling cell closes an unclosed previous cell of the same row.
            if (current_row is not None and self.cell_stack
                    and self.cell_stack[-1]['row'] is current_row):
                self._finish_cell()
            self.cell_stack.append({'row': current_row, 'tag': tag, 'buf': []})

    def handle_endtag(self, tag):
        if tag in ('td', 'th'):
            if self.cell_stack:
                self._finish_cell()
        elif tag == 'tr':
            if self.row_stack:
                self._finish_row()

    def handle_data(self, data):
        if self.cell_stack:
            self.cell_stack[-1]['buf'].append(data)

    def close(self):
        super().close()
        while self.cell_stack:
            self._finish_cell()
        while self.row_stack:
            self.row_stack.pop()


def extract_table_rows(html):
    parser = _RowExtractor()
    parser.feed(html)
    parser.close()
    return parser.rows
