```python
from html.parser import HTMLParser


class _TableRowParser(HTMLParser):
    """Collects the text of each <td> cell, grouped by its enclosing <tr>."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = []    # one list per <tr>, in order of the opening tag
        self.stack = []   # open elements: [tag, row_list_or_None, text_parts_or_None]

    def _innermost_row(self):
        for entry in reversed(self.stack):
            if entry[0] == 'tr':
                return entry[1]
        return None

    def _end_cell_if_open(self):
        # Implicit end of a cell when a new cell or row starts (end tags are optional in HTML).
        if self.stack and self.stack[-1][0] in ('td', 'th'):
            self._pop_to(len(self.stack) - 1)

    def _finalize(self, entry):
        tag, row, parts = entry
        if tag == 'td' and row is not None:
            row.append(''.join(parts).strip())

    def _pop_to(self, index):
        while len(self.stack) > index:
            self._finalize(self.stack.pop())

    def _find_topmost(self, tags):
        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i][0] in tags:
                return i
        return None

    def handle_starttag(self, tag, attrs):
        if tag in ('td', 'th'):
            self._end_cell_if_open()
            self.stack.append([tag, self._innermost_row(), []])
        elif tag == 'tr':
            self._end_cell_if_open()
            if self.stack and self.stack[-1][0] == 'tr':
                self._pop_to(len(self.stack) - 1)
            row = []
            self.rows.append(row)
            self.stack.append(['tr', row, None])
        elif tag == 'table':
            self.stack.append(['table', None, None])

    def handle_endtag(self, tag):
        if tag in ('td', 'th'):
            idx = self._find_topmost((tag,))
            if idx is not None:
                self._pop_to(idx)
        elif tag == 'tr':
            idx = self._find_topmost(('tr',))
            if idx is not None:
                self._pop_to(idx)
        elif tag == 'table':
            idx = self._find_topmost(('table',))
            if idx is not None:
                self._pop_to(idx)

    def handle_data(self, data):
        # Text belongs to the innermost open cell, unless a table or row
        # opens between that cell and the top of the stack.
        for entry in reversed(self.stack):
            if entry[0] in ('td', 'th'):
                entry[2].append(data)
                return
            if entry[0] in ('table', 'tr'):
                return


def extract_table_rows(html):
    parser = _TableRowParser()
    parser.feed(html)
    parser.close()
    # Flush any cells still open at end of input.
    parser._pop_to(0)
    return parser.rows
