from html.parser import HTMLParser


class _RowParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.result = []    # one list per <tr>, in document order
        self.table_depth = 0
        self.rows = []      # open rows: (table_depth, row_list)
        self.cells = []     # open cells: (table_depth, row_list, parts or None for <th>)

    def _close_cell(self):
        _, row, parts = self.cells.pop()
        if parts is not None:
            row.append("".join(parts).strip())

    def _close_cells_at(self, depth):
        while self.cells and self.cells[-1][0] == depth:
            self._close_cell()

    def _close_rows_at(self, depth):
        while self.rows and self.rows[-1][0] == depth:
            self.rows.pop()

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        d = self.table_depth
        if tag == "table":
            self.table_depth += 1
        elif tag == "tr":
            # An unclosed previous row/cell at this table level ends here.
            self._close_cells_at(d)
            self._close_rows_at(d)
            row = []
            self.result.append(row)
            self.rows.append((d, row))
        elif tag in ("td", "th"):
            self._close_cells_at(d)
            if not self.rows or self.rows[-1][0] != d:
                # Cell without an enclosing <tr>: start an implicit row.
                row = []
                self.result.append(row)
                self.rows.append((d, row))
            row = self.rows[-1][1]
            parts = [] if tag == "td" else None  # <th> content is ignored
            self.cells.append((d, row, parts))

    def handle_endtag(self, tag):
        tag = tag.lower()
        d = self.table_depth
        if tag in ("td", "th"):
            if self.cells and self.cells[-1][0] == d:
                self._close_cell()
        elif tag == "tr":
            self._close_cells_at(d)
            self._close_rows_at(d)
        elif tag == "table":
            self._close_cells_at(d)
            self._close_rows_at(d)
            if self.table_depth > 0:
                self.table_depth -= 1

    def handle_data(self, data):
        if self.cells:
            d, _, parts = self.cells[-1]
            if parts is not None and d == self.table_depth:
                parts.append(data)


def extract_table_rows(html):
    parser = _RowParser()
    parser.feed(html)
    parser.close()
    # Finish any cells/rows left open by malformed markup.
    while parser.cells:
        parser._close_cell()
    return parser.result
```

