import json
from html.parser import HTMLParser


class _TitleParser(HTMLParser):
    """Collects the text of the first <title> element."""

    def __init__(self):
        # convert_charrefs=True makes the parser decode entities such as &amp; and &#39;
        super().__init__(convert_charrefs=True)
        self.title = None        # finished title text, once the element closes
        self._in_title = False
        self._parts = []

    def handle_starttag(self, tag, attrs):
        if tag == "title" and self.title is None and not self._in_title:
            self._in_title = True
            self._parts = []

    def handle_endtag(self, tag):
        if tag == "title" and self._in_title:
            self._in_title = False
            self.title = "".join(self._parts)

    def handle_data(self, data):
        if self._in_title:
            self._parts.append(data)


def extract_title_json(html):
    parser = _TitleParser()
    parser.feed(html)
    parser.close()

    # Handle an unclosed <title> that runs to the end of the document.
    if parser.title is None and parser._in_title:
        parser.title = "".join(parser._parts)

    title = parser.title.strip() if parser.title is not None else None
    return json.dumps({"title": title})


if __name__ == "__main__":
