import json
from html.parser import HTMLParser


class _TitleExtractor(HTMLParser):
    def __init__(self):
        # convert_charrefs=True makes the parser decode entities like &amp; and &#39;
        super().__init__(convert_charrefs=True)
        self._found = False      # have we seen the first <title> start tag?
        self._in_title = False   # are we currently inside that element?
        self._done = False       # have we finished the first title element?
        self._parts = []

    def handle_starttag(self, tag, attrs):
        if tag == "title" and not self._found:
            self._found = True
            self._in_title = True

    def handle_endtag(self, tag):
        if tag == "title" and self._in_title:
            self._in_title = False
            self._done = True

    def handle_data(self, data):
        if self._in_title and not self._done:
            self._parts.append(data)

    @property
    def title(self):
        return "".join(self._parts) if self._found else None


def extract_title_json(html):
    parser = _TitleExtractor()
    parser.feed(html)
    parser.close()
    return json.dumps({"title": parser.title})
