import json
import math


def _quantile(sorted_vals, q):
    """Quantile by linear interpolation between closest ranks (type 7)."""
    n = len(sorted_vals)
    if n == 1:
        return float(sorted_vals[0])
    pos = (n - 1) * q
    lo = math.floor(pos)
    hi = math.ceil(pos)
    frac = pos - lo
    return float(sorted_vals[lo] + (sorted_vals[hi] - sorted_vals[lo]) * frac)


def _summarize(values):
    s = sorted(values)
    n = len(s)
    mean = float(sum(s)) / n
    median = _quantile(s, 0.5)
    q1 = _quantile(s, 0.25)
    q3 = _quantile(s, 0.75)
    return {"mean": mean, "median": median, "q1": q1, "q3": q3}


def summarize_values_by_key(json_text):
    """
    Parse a JSON string encoding a list of objects mapping keys to numbers and
    return, for each key, a dict with 'mean', 'median', 'q1' and 'q3' computed
    over all values recorded for that key. Objects lacking a key do not
    contribute to it. Quartiles use linear interpolation between sorted values.

    Raises ValueError for invalid JSON or unexpected structure/value types.
    """
    try:
        data = json.loads(json_text)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError(f"Invalid JSON: {exc}") from exc

    if not isinstance(data, list):
        raise ValueError("JSON must encode a list of objects")

    collected = {}
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Every element of the list must be a JSON object")
        for key, value in item.items():
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(
                    f"Value for key {key!r} is not a number: {value!r}"
                )
            collected.setdefault(key, []).append(value)

    return {key: _summarize(vals) for key, vals in collected.items()}


if __name__ == "__main__":
    print(summarize_values_by_key(
        '[{"a": 1, "b": 4}, {"a": 2}, {"a": 3, "b": 6}, {"a": 10}]'
